window.POLICE_LESSONS = {
  "110-ge-1": ["辨認區域觀點","題幹把桃園大潭當成一個具體地區，綜合評估工業開發、經濟收益和藻礁保育。","同時比較同一地區內的自然與人文條件，依本題分類屬於區域傳統。"],
  "110-ge-2": ["工業革命的區位擴散","圖上可找到較早的工業核心，再沿年份線和箭頭看影響向外擴展。","新的生產技術由起源地傳到其他地區，稱為區位擴散。"],
  "110-ge-3": ["透過語言與殖民史辨識菲律賓","題目給了曾受美國殖民、英語普遍兩個線索。","菲律賓符合這些條件，英語能力也讓它成為國際客服外包的重要據點。"],
  "110-ge-4": ["冰島裂隙式熔岩噴發","岩漿從地表裂縫穩定流出，幾乎沒有火山灰，屬溢流式噴發。","基性岩漿通常黏度較低、容易流動，對應題目的寧靜噴發。"],
  "110-ge-5": ["用社會增加率判讀人口遷移","縱軸的自然增加率比較出生與死亡，橫軸的社會增加率比較遷入與遷出。","圖上最靠右的是丁，社會增加率最大，因此在四國中最能吸引人口遷入。"],
  "110-ge-6": ["衛星影像能直接看見的變化","比較不同日期的影像，可圈出海面油污、河川溢淹的範圍。","衛星無法從影像直接辨認病人的感染狀況，疾病分布需要醫療或通報資料。"],
  "110-ge-7": ["寒帶針葉林的酸性表土","針葉落葉分解慢，能產生有機酸。","水分往下滲時會把表層的部分礦物與鹽基帶走，因此強淋洗下表土容易偏酸。"],
  "110-ge-8": ["英、法、西、義之間的陸路","英國和法國可經英吉利海峽隧道連接，法國與西班牙、義大利也有陸上交通。","各國的語言不同，英國也不以歐元為通用貨幣，故可把握全程能走陸路。"],
  "110-ge-9": ["大地主制度與財富差距","拉丁美洲一些地方長期存在大莊園，土地與收益集中於少數地主。","多數人難以取得足夠資產，城鄉間的貧富差距因此延續。"],
  "110-ge-10": ["按曲線起點和成長速度辨認各洲","最高的是人口最多的亞洲甲；後期快速上升成為第二的是非洲乙。","歐洲丙成長較緩，中南美洲丁後期高於北美洲戊。按題目順序排出甲、丙、戊、丁、乙。"],
  "110-ge-11": ["防波堤上游側的堆積","沿岸流從北往南搬運砂粒，砂粒先遇到堤防的北側。","堤防截住部分沉積物，北側因而堆積較明顯，南側補砂減少。"],
  "110-ge-12": ["高鐵壓縮城市之間的旅行時間","高鐵的車站主要服務都會區，降低不同城市之間通勤、洽公和旅遊所需時間。","往返變容易，因此促進都市與都市間的交互作用。"],
  "110-ge-13": ["海岸地形的主要塑形力量","桃竹苗海岸沙丘主要是海灘乾砂被風搬運，在海岸後方堆起。","海蝕崖、海階與濱外沙洲的形成均和海水作用有關，海階抬升也涉及地殼變動。"],
  "110-ge-14": ["洪水歷線與地表覆蓋","圖上 A 在降雨後較快出現高尖洪峰，表示雨水很快進入河道。","建物、道路等不透水地面較多，水難以下滲，因此符合 A 流域建物覆蓋較多。"],
  "110-ge-15": ["澳洲大分水嶺與古褶曲地形","題目定義的古褶曲山脈形成久，長期受風化、侵蝕後地勢較和緩。","澳洲大分水嶺符合這個課本分類。中央、洛磯、天山常歸入較年輕的山系。"],
  "110-ge-16": ["美國五大湖工業帶與酪農帶","先在圖上定位，鑄造廠區位於五大湖周圍和東北部。","酪農帶橫跨五大湖周邊至東北部，乳品也可供應該區密集的城市。玉米帶主要在更偏西、偏南的中西部。"],
  "110-ge-17": ["蘇伊士運河連接的兩個海域","蘇伊士運河穿過埃及，北口通地中海，南口通紅海。","它讓歐洲與亞洲間船舶縮短航程，不用繞非洲南端。"],
  "110-ge-18": ["西南季風與跨境霾害","風向以風吹來的方向命名。蘇門答臘位於新加坡及馬來半島西南側。","西南季風吹向東北，能把蘇門答臘的煙霾帶到新馬一帶，故選西南風。"],
  "110-ge-19": ["南韓透過自由貿易協定拓展市場","金融風暴後，南韓加強外向貿易，簽訂自由貿易協定以降低進入他國市場的障礙。","其經濟成長仍與大型企業集團及製造業出口關係密切。"],
  "110-ge-20": ["中南美洲快速都市化帶來的問題","人口和資源往大城市集中，基礎建設跟不上，容易出現資源分配不均。","住宅不足也可能形成擁擠聚落並加重治安問題，故選甲、乙。"],
  "110-ge-21": ["用美國天氣現象分布判讀龍捲風","圖上高值集中在美國中部大平原一帶，向東南也有分布。","這些地方常有冷乾與暖濕氣團相遇，容易形成劇烈雷雨與龍捲風。颶風則常先從沿海登陸。"],
  "110-ge-22": ["集約畜牧和狂牛症","狂牛症與牛隻攝入感染普立昂的動物性飼料有關。","密集飼養時，若許多牛使用同一批有問題的飼料，影響可迅速擴大。"],
  "110-ge-23": ["稻作規模與平均生產成本","臺灣不少稻農經營的土地面積較小，機具、管理等成本分攤到每單位稻米會偏高。","題目問缺乏競爭力的根本原因，對照開放進口後的大規模國外米，選生產規模小。"],
  "110-ge-24": ["製程標準化與跨國分工","研發期需要熟練人才和較多試驗，難把所有生產部門搬走。","製程標準化後，每道生產步驟可依固定規格操作，企業較能將生產移往成本較低的地區。"],
  "110-ge-25": ["阿他加馬沙漠用霧取水","沿岸有祕魯涼流，冷卻近海空氣，容易形成低雲、霧。","降雨極少時，捕霧網可以攔截霧滴，累積後導入容器。"],
  "110-ge-26": ["阿爾卑斯山的冰河槽","冰河沿谷地移動時會向下及向兩旁侵蝕，形成寬闊的 U 形谷。","這種谷底相對寬的冰河槽較容易形成穿越山地的交通路線。"],
  "110-ge-27": ["虛擬水與缺水地區的進口","虛擬水指生產商品總共需要的水。題表中每公斤牛肉需 16000 公升，超過其他選項。","西亞水資源少，進口耗水最多的商品可省下最多本地用水，故選牛肉。"],
  "110-ge-28": ["西非沿岸都市與資源輸出","圖中不少大城在海岸，內陸交通線往這些港口匯集。","路線便於把內陸農礦資源運到港口出口，港口因此聚集人口和商業活動。"],
  "110-ge-29": ["無店鋪銷售對商圈與商品圈的影響","商圈指實體店吸引顧客到店消費的範圍。無店鋪銷售興起，顧客不必到店，實體商圈縮小。","商品圈指商品能銷往的範圍。物流配送可以把貨送到更遠的地方，因此商品圈擴大。"],
  "110-ge-30": ["利用時差和相對位置推測曼谷座標","每小時約差 15 度經度，3 小時約 45 度。曼谷比雪梨偏西，151°E 減約 45° 得約 106°E。","曼谷位在北半球低緯，選項中最接近的是 13°N、100°E。"],
  "110-ge-31": ["南沙群島的主權主張","先區分提出主權主張和單純位於南海附近。越南、菲律賓、馬來西亞都有提出主張。","泰國和新加坡未主張南沙群島主權。依題中給的國家，勾 A、D、E。"],
  "110-ge-32": ["由人口金字塔看日本老化","圖中底部窄、老年人口比重大，表示出生人數少。就分級名稱而言，日本當時已進入「超高齡社會」，故不選 B 的「高齡化社會」。","少子高齡使人口成長率有下降趨勢，也會提高高齡照護等銀髮商品需求，因此選 D、E。"],
  "110-ge-33": ["中美洲常見自然災害","中美洲位於板塊交界附近，可能發生地震；暴雨和熱帶氣旋也可能帶來水災。","山地坡陡，降雨後也可能發生土石流。凍土融化不符合當地低緯環境。"],
  "110-ge-34": ["判讀都市擴張的三個階段","由 A 到 C，兩個中心周圍的住宅分布向外擴張，通勤範圍增加，兩城之間的空地逐漸減少。","都市化程度提高，最後可形成由多個中心連接的都會帶。圖中的人口集中也擴及外圍，不能據此推論中心商業區住宅密度提高。"],
  "110-ge-35": ["比較 1 比 5000 與 1 比 25000 的地圖","5000 的分母較小，甲是大比例尺，圖上可呈現更多細節，較適合記錄土地利用現況。","同一實地距離畫在甲圖較長。若比較同一地區的圖上面積，甲是乙的 25 倍，因為長度比例要平方。"],
  "110-ge-36": ["辨認主要石油輸出國組織成員","本題所問 OPEC 成員中，伊拉克和科威特是創始成員，應選 C、E。","俄羅斯參與 OPEC+ 合作但非正式成員。印尼與阿富汗也不符合本題的成員條件。"],
  "110-ge-37": ["使河流河道延長的三種變化","曲流讓河道彎曲，從起點到終點實際經過的路更長。向源侵蝕則使上游河道向源頭伸展。","三角洲向海推進時，部分河道也可延伸。單純下切主要是加深河床。"],
  "110-ge-38": ["高溫多雨區的強烈化學風化","圖中甲區在高溫、多雨的一側，水與礦物的化學反應快，淋洗也強。","石灰岩溶蝕可形成錐丘，強烈風化和淋洗可形成磚紅壤，所以選 A、D。"],
  "110-ge-39": ["申根區內減少邊境查驗的影響","減少一般跨境旅行時的查驗，可方便旅遊及跨境活動，也能帶來經濟效益。","就題目考慮的可能代價，減少例行查驗也會影響對走私、逃犯或疫病等跨境風險的攔查，故選 A、B、C。"],
  "110-ge-40": ["紐西蘭的冰河及火山地形","冰河侵蝕留下深谷，海水淹入後形成峽灣，例如南島西南部的峽灣。","板塊交界也帶來火山與地熱活動，可見火山和間歇泉。珊瑚堡礁與廣大岩漠並非本題所指。"],
  "110-hi-1": ["乾隆年間的林爽文事件","題幹直接提到乾隆，又說頒匾嘉獎廣東莊和泉州莊的義民。","林爽文事件在乾隆年間，清廷動員地方義民協助平亂。朱一貴事件則發生在康熙年間。"],
  "110-hi-2": ["北京改名北平的時間","把改名、換國旗和讀孫中山遺囑一起看，表示國民政府的統治進入北京。","1928 年國民政府完成北伐，並將北京改名北平。"],
  "110-hi-3": ["克里米亞戰爭的近代戰況報導","英國記者能以電報快速傳回戰況，政府還派攝影師留下紀錄。","蒸汽軍艦和鐵路運兵等科技一起出現，符合十九世紀的克里米亞戰爭。"],
  "110-hi-4": ["荷西時期臺灣的轉口貿易","題中各國貨幣同時流通，表示當地與多方商人交易。","十七世紀前半臺灣曾有荷蘭、西班牙據點，也與中國、日本及東南亞貿易，符合題意。"],
  "110-hi-5": ["穆罕默德與伊斯蘭勢力擴張","穆罕默德以伊斯蘭信仰整合阿拉伯半島部族。","繼起的政權由北非跨過直布羅陀進入伊比利半島，後來向法蘭克擴張時受阻。"],
  "110-hi-6": ["清代臺灣的築城限制","行政中心一開始不准築城，動亂後才允許以木柵防禦，後來又修築磚城。","清廷早期擔心地方勢力利用城防據守，這組線索對應清代臺灣。"],
  "110-hi-7": ["在印度競爭的英國與法國","1664 年成立東印度公司的是法國。英國公司成立更早，也較早與蒙兀兒帝國接觸。","七年戰爭後英國取得優勢，法國主要保有少數商站，所以甲法國、乙英國。"],
  "110-hi-8": ["臺灣經濟政策的三個階段","乙是戰後早期的肥料換穀，透過農業資源支持工業發展。","後來設加工出口區吸引投資、擴大出口，1980 年新竹科學園區成立以發展高科技產業。順序是乙、丙、甲。"],
  "110-hi-9": ["中華人民共和國初期的外交","中華人民共和國成立初期採向社會主義陣營「一邊倒」的外交路線。","其後與蘇聯簽訂同盟互助條約，也得到經濟援助，故為中共與蘇聯。"],
  "110-hi-10": ["奧古斯都與羅馬的元首制","奧古斯都保留元老院等共和體制的外觀，實際上集中權力。","這是羅馬由共和走向帝制的重要一步，辨認出奧古斯都就能選羅馬帝國。"],
  "110-hi-11": ["傳染病造成美洲人口大幅下跌","歐洲人到達後，天花等傳染病進入美洲，許多原住民對疾病缺乏免疫力。","戰爭和殖民壓迫也有影響，但題中跨多地的大幅減少，主要與傳染病流行有關。"],
  "110-hi-12": ["科舉名額與南方興起","江南經濟發展後，南方學校與應考人才增加，錄取者容易集中於發達地區。","按地區分配名額可避免某些地區長期無人及第，對應江南經濟與人才的興起。"],
  "110-hi-13": ["明清商人的會館","會館讓在外地經商的同鄉有聚會地點，可交流商情並互相照應。","明清長距離貿易和商幫發展，會館因此更加普遍。"],
  "110-hi-14": ["臺北帝國大學與南進政策","題中機構研究南洋的社會和天然資源，對象與方向都指向南方。","日本把臺灣當作向東南亞發展的據點，這是南進政策的配套。"],
  "110-hi-15": ["康熙所面對的人口壓力","找句中的數量變化，重點是「戶口雖增，而土田並無所增」。","人口增加、耕地沒有跟上，每份土地要供養的人更多，因此選人口眾多。"],
  "110-hi-16": ["阿姆斯特丹的金融發展","十七世紀的荷蘭因海運與遠洋商業興盛，阿姆斯特丹商船和商店集中。","股票交易所是辨別城市的關鍵，對應阿姆斯特丹。"],
  "110-hi-17": ["永嘉之亂後的北人南遷","西晉末年永嘉之亂後，北方許多人遷往江南，東晉在南方建立政權。","「僑州、郡、縣」是為南遷人口而設的行政單位。題目以南朝宋作統計終點，也指向這次早期南遷。"],
  "110-hi-18": ["馬歇爾計畫的援助國","西德、英法、義大利等在二戰後獲得美國的歐洲復興援助。","名單也有冰島、挪威和土耳其，可排除歐盟成員選項。"],
  "110-hi-19": ["印巴分治引發宗教人口遷徙","1947 年英屬印度分治，大批印度教徒、錫克教徒與穆斯林遷往不同國家。","遷徙伴隨大規模衝突。題中的跨國移居和宗教群體對立都吻合。"],
  "110-hi-20": ["日本扶植的滿洲國","文中把蔣中正與汪精衛的政權視作兩個鄰國，自己又是受日本控制的「祖國」。","日本扶植的滿洲國位於中國東北，符合鄰近中國政權且教育受日本支配的線索。"],
  "110-hi-21": ["日治臺灣的臺灣民眾黨","文中提到「本島」自治，顯示是臺灣日治時期的政治運動。","1927 年成立的臺灣民眾黨曾支持勞工運動，黨內也出現是否強調階級的爭論。"],
  "110-hi-22": ["戰後臺灣的耕者有其田","關鍵是政府強制徵收地主超額出租的耕地，再讓農民取得耕地。","以實物土地債券及公營事業股票補償地主，是臺灣 1953 年耕者有其田政策的特徵。"],
  "110-hi-23": ["秦代法令與財產清冊","文書詳細記載屋舍、樹木、家人、奴婢等，並提到查封。","「無爵平民」及清點家產的辦法，符合秦代戶籍、徵稅、徵役的統治需要。"],
  "110-hi-24": ["唐代節度使與安史之亂","唐朝在邊疆設軍區，節度使能掌軍並累積地方權力。","安祿山等起兵造成安史之亂，亂後藩鎮更普遍，中央控制地方更難。"],
  "110-hi-25": ["1930 年代日治臺灣的地方選舉","半數議員官派，限符合年齡、居住和納稅條件的男子投票。","這些限制符合 1935 年臺灣的地方選舉，臺北是其中一處。"],
  "110-hi-26": ["二二八事件處理委員會的要求","「長官公署」是戰後早期臺灣的行政機關，與日治時期不同。","增加臺灣人任職、民選縣市長、改革專賣等訴求，對應二二八事件處理委員會。"],
  "110-hi-27": ["雍正認為華夷界線會變動","雍正舉古代曾被視為夷狄的地區，指出那些地方今天已在中國統治範圍內。","他也以蒙古諸部納入清朝版圖為例，說明華夷界線不能永遠用同一標準劃定。"],
  "110-hi-28": ["啟蒙運動的理性觀點","以機器比喻宇宙，強調自然有可理解的規律。","批判教會與專制君主，也對應十八世紀啟蒙運動對權威的反思。"],
  "110-hi-29": ["法西斯主義的極端民族與國家觀","題目強調國家統治、極端民族主義與反共。","這些特色組合符合戰間期法西斯主義，國家與領袖的權力被抬到個人之上。"],
  "110-hi-30": ["西安事變與停止內戰","張學良、楊虎城於西安扣留蔣中正，要求停止內戰、共同抗日。","事變和平解決後，國共關係轉向合作抗日，對應「全國統一，一致對外」。"],
  "110-hi-31": ["由材料重建西拉雅社會","材料提到有供少年居住與議事的公廨，表示存在公共場所。","原文也說沒有文字、曆法和書契。婚居習俗和捕鹿紀錄不足以推出男尊女卑、農業經濟或國家組織。"],
  "110-hi-32": ["兩漢經學所讀的典籍","《詩經》《易經》《春秋》屬於經書，與漢代經學教育有關。","《史記》《漢書》記載歷史，二者在傳統圖書分類中屬史部。"],
  "110-hi-33": ["《漢摩拉比法典》的刑罰觀","同是傷眼或打落牙齒，對同等地位者可能以相同傷害回報，稱報復原則。","受害者是奴隸或平民時，賠償方式會因身分而異，可見階級有別。"],
  "110-hi-34": ["坊市分隔的城市規劃","坊是住宅區，市是集中交易的區域。漢代長安、洛陽和唐代長安都可見這種區隔。","宋代汴京商業已大量沿街發展，明代北京也不屬題意所指的嚴格坊市制度。"],
  "110-hi-35": ["馬丁路德宗教改革的主張","路德批評出售贖罪券，認為信徒靠信仰得救。","他重視聖經，也承認基督，因此不能把反對教會的某些做法當成否認聖經與基督。"],
  "110-hi-36": ["從航線辨認鄭和下西洋","船隊經過南海、麻六甲海峽，曾到爪哇、蘇門答臘等地，並航入印度洋。","日本位在中國東北方向，並非題意所指的下西洋航路。"],
  "110-hi-37": ["太平天國實際占領過的城市","太平軍占領南京，改稱天京並定都，後來也攻占杭州與蘇州。","北伐軍未拿下天津，上海也未被太平軍攻占。"],
  "110-hi-38": ["柴契爾和雷根的保守政策","柴契爾夫人和雷根主張市場競爭、壓縮部分政府支出，並採鮮明反共立場。","同時符合國防、經濟與冷戰立場三組線索，所以選 A、E。"],
  "110-hi-39": ["一戰前後消失的帝國","鄂圖曼、德意志、俄羅斯和奧匈帝國在第一次世界大戰前後解體或終結。","神聖羅馬帝國早在 1806 年就解散，1900 年時已不存在。"],
  "110-hi-40": ["東漢末年的民變與宗教","張角以太平道組織黃巾起事，張魯以五斗米道在漢中建立政權。","五斗米道與早期天師道密切相關。白蓮教與淨土宗不符合題中的東漢末年民變。"],
  "110-ch-1": ["形近字辨音","「嫵媚」的嫵和「憮然」的憮都讀ㄨˇ。","「緝」讀ㄑㄧˋ，「楫」讀ㄐㄧˊ。形近字仍要放進詞裡讀。"],
  "110-ch-2": ["辨別錯別字","逐詞看字義，A 的寫法符合句意。","D 的「平淡無其」應作「平淡無奇」，意思是平凡而沒有特別之處。"],
  "110-ch-3": ["用上下文解釋一字多義","「北通巫峽，南極瀟湘」的「極」是到達。「意有所極」的「極」也是到達。","「職分」的「分」是本分。遇到多義字時，可把每個意思代回原句，看是否通順。"],
  "110-ch-4": ["從景物讀懂比喻","〈荷塘月色〉寫月光像流水靜靜瀉下，薄霧中的葉和花彷彿在牛乳中洗過。","〈樹猶如此〉寫樹木間的缺口，又提到女媧煉石，提示第三空是「天裂」。三空依次為流水、牛乳、天裂。"],
  "110-ch-5": ["看成語的適用情境","「家喻戶曉」指人人都知道，「見仁見智」指不同的人有不同看法，乙、丙用得合適。","「前倨後恭」須有先傲慢、後恭敬的轉變；井底之蛙一類的成語用來形容見識狹窄。"],
  "110-ch-6": ["稱謂與新生兒賀詞","「天賜石麟」是祝賀得子的詞語，適合用在歐陽脩道賀的情境。","「令郎」敬稱對方的兒子，「舍弟」謙稱自己的弟弟。先弄清楚說話者和被稱呼的人。"],
  "110-ch-7": ["由自己想到別人的感受","兩人分食魚果時想到兒童的處境，又想到他們父母的難過。","從眼前的感受設想他人，這是「推己及人」。"],
  "110-ch-8": ["用承接詞排出文句順序","「沒有一個字」先接乙的「無字天書」，接著丁說書裡夾了哪些物品。","甲以「還有」補充一雙鞋面，丙以母親一直把它們夾在書裡收尾。順序是乙、丁、甲、丙。"],
  "110-ch-9": ["文言的意動用法","題幹以「遠」來評斷某個對象，可譯為「認為……遠」。","B 的「恥」可譯為「以自身做不到為恥」。兩者都表達主觀評價，語法相同。"],
  "110-ch-10": ["辨別分承與平行句","分承要把前面並列的內容和後面分說的句子一一配對。A 的形容並列成句。","C 的廟堂憂民、江湖憂君也各自成句。校方更正後，A 或 C 都計分。"],
  "110-ch-11": ["從語氣辨認激將","C 點出對方只想報答顏倫，再用「寧不哀哉」加重質問，藉此刺激對方採取行動。","其他句子的「駑鈍」「寡人之過」「得罪於先生」都在放低自己的姿態。"],
  "110-ch-12": ["法家主張依法律辦事","「不別親疏，不殊貴賤」說明辦事時不問關係親疏或身分高低。","「一斷於法」明說以法為同一標準，符合先秦法家的主張。"],
  "110-ch-13": ["《詩經》的文學史地位","《詩經》又稱「詩三百」，是中國早期的詩歌總集。","記住「風、雅、頌」三部分，可以和其他朝代、其他文類的作品區分。"],
  "110-ch-14": ["辨別唐詩與元曲","元曲可稱「詞餘」，演唱時可依曲調加入襯字。","唐代代表性的律詩、絕句屬近體詩。比較文體時，分清詩、詞、曲各自的格律。"],
  "110-ch-15": ["唐宋古文運動與作家","韓愈與柳宗元都是唐代古文運動的代表，重視文章傳達思想與道理。","范仲淹未列唐宋八大家。慶曆新政是范仲淹等人推動，王安石則與熙寧變法有關。"],
  "110-ch-16": ["由節俗與景物判斷季節","登高、茱萸和菊花提示農曆九月重陽，屬於秋天。","C 的桂子、玉露和月華同樣營造秋夜景象，其他選項的季節線索不合。"],
  "110-ch-17": ["書名與文體配對","《左傳》常錄諸侯交涉辭令，《戰國策》善寫策士遊說，《世說新語》有魏晉名士清談。","袁枚《子不語》是志怪筆記，與題中要求配對的內容不同，因而留空。"],
  "110-ch-18": ["文字難以說盡心意","題中從「言」與「意」的關係立論。文字能表達一部分意思，讀者仍須體會未直接說出的部分。","因此「言不盡意」最符合題旨，可從能否把全部心意說清楚來理解。"],
  "110-ch-19": ["古文雜記中的人事類","題目以記載人物或事件為分類線索，屬於人事雜記。","〈傷仲永〉記方仲永的才華與後來的變化，〈義田記〉記設置義田以照顧族人的事。"],
  "110-ch-20": ["通感是把感官經驗交疊","把笑聲寫成可以插在髮間的東西，讓耳朵聽見的聲音有了可見的形象。","C 把馬蹄聲比成白色小花，也由聽覺轉為視覺，和題幹最接近。"],
  "110-ch-21": ["從家族名稱辨認小說","寧國府和榮國府都是《紅樓夢》中的賈府，宗祠祭祖、元宵夜宴也是小說情節。","人物綽號也能辨書名，例如花和尚、豹子頭是《水滸傳》裡的角色。"],
  "110-ch-22": ["從親友與詞句辨認作家","子由是蘇軾的弟弟蘇轍，朝雲是蘇軾身邊的伴侶。","「大江東去」出自蘇軾的〈念奴嬌・赤壁懷古〉，三個線索都指向蘇東坡。"],
  "110-ch-23": ["共同處境與相互依存","虞國、虢國相互依存，一方失去屏障，另一方也會受威脅。","「休」是喜樂，「戚」是憂愁，「休戚相關」形容彼此的利害緊密相連。"],
  "110-ch-24": ["勤學的成語","「牛角掛書」是把書掛在牛角上，騎牛時仍能讀書；「韋編三絕」是反覆讀書，編書的皮繩斷過多次。","兩則都在寫勤奮讀書；「不恥下問」則強調請教他人時不以為羞。"],
  "110-ch-25": ["辨詩中人物與時代","漂母一飯指韓信，汨羅指屈原，泛舟五湖指范蠡，吳宮和效顰指西施。","四人都不屬三國時代。校方公布本題送分。"],
  "110-ch-26": ["「殆」表示推測","「殆有神護者」可譯成「大概有神靈保護」，說話者在猜測原因。","「殆」也可能表示危險或幾乎，判讀時應把詞義放回整句檢查。"],
  "110-ch-27": ["依敘事順序判讀〈縣令〉故事","縣令對畫軸落地起疑，清早去看，發現畫軸在地上、貓蹲在一旁。","「漫懸」是隨意掛上。後文用貓追撲畫鼠來解釋畫軸落地，並非路人碰落。"],
  "110-ch-28": ["以旁觀者的反應烘托畫技","故事以貓的行為讓讀者推知畫鼠十分逼真。","貓把畫上的老鼠當成活物追撲，這是用側面描寫表現畫家的技藝。"],
  "110-ch-29": ["從描述區辨藝術種類","「銀鉤鐵畫」形容書法筆勢，墨竹、畫菊屬於繪畫。","典故和駢文是文學線索。文中沒有拍照或照相技法，因此選攝影。"],
  "110-ch-30": ["駢文的對偶與用典","留意文中上下句字數、句法相近的地方，這是對偶。","文章又借前人的故事和語句表達意思，屬於用典。兩個特色都符合駢文。"],
  "110-mb-1": ["兩個絕對值是兩段數線距離","原式是 x 到 2 的距離，加上 x 到 −5 的距離，總和至少為兩端間距 7。","當 x 在 −5 到 2 之間時，兩段距離正好拼成 7，所以最小值是 7。"],
  "110-mb-2": ["圖形在 x 軸下方時，函數值才小於零","曲線在 x＝1 碰到 x 軸後仍留在下方，在 x＝3 才穿到上方。","因此所有小於 3 的 x 都可取，唯獨 x＝1 的值正好是零，必須排除。"],
  "110-mb-3": ["把前五項、後五項分開","前五項每項多加了 2，故原和是 100−5×2＝90。後五項各乘 2，因此原和是 100÷2＝50。","兩段相加得 140。"],
  "110-mb-4": ["第二象限的正弦從 90° 到 180° 逐漸下降","110°、120°、130°、140° 都在同一段。離 90° 最近的角，其正弦值最大。","因此 sin110° 最大，也可用 sin110°＝sin70° 回到第一象限比較。"],
  "110-mb-5": ["真分數的正分子要小於分母","從八個互異正數選一對後，用較小者作分子、較大者作分母，剛好一種。","選兩數有 C(8,2)＝8×7÷2＝28 對。相等時為 1，不能算真分數。"],
  "110-mb-6": ["相加兩個集合時，要扣掉重複的部分","紅心有 4 張，A 有 4 張，紅心 A 同時屬兩類。","符合條件共 4＋4−1＝7 張，所以機率是 7/16。"],
  "110-mb-7": ["散布圖的相關要同時判斷方向和緊密程度","圖 C 整體仍有向右上趨勢，但比 A、B 更分散，所以應為較小的正相關。","0.4267 符合；1.3215 超出相關係數的 −1 至 1 範圍。"],
  "110-mb-8": ["重心把中線分成 2 比 1","令 M 是 BC 中點。中線平方 AM²＝(AB²＋AC²)/2−BC²/4＝(4＋9)/2−4＝5/2。","AM＝√10/2；從頂點到重心走中線的 2/3，故 AG＝√10/3。"],
  "110-mb-9": ["列運算後從最後一列往回代","第三列 z＝2；第二列 3y＋10z＝−4，所以 y＝−8。","第一列 x−2y−3z＝11，代回得 x＝1，解是 (1,−8,2)。"],
  "110-mb-10": ["垂直線斜率是負倒數","4x＋y＝5 的斜率為 −4，垂線斜率為 1/4。","過 (1,2) 可寫 y−2＝(x−1)/4，整理為 x−4y＝−7。"],
  "110-mb-11": ["先把正方形的頂點放到坐標上","可取 A=(0,0)、B=(6,0)、C=(6,6)、D=(0,6)。BE＝4，故 E=(6,4)，F=(3,6)。","BF=(−3,6)，DE=(6,−2)。內積＝−18−12＝−30。"],
  "110-mb-12": ["兩平面夾角可用法向量夾角計算","法向量分別為 (3,4,−5)、(4,−1,1)，內積是 12−4−5＝3。","長度分別為 √50 和 √18，相乘為 30；餘弦絕對值為 3/30＝1/10。"],
  "110-mb-13": ["保費需涵蓋預期理賠和預期獲利","不平安的機率為 1−99.98%＝0.0002，保額 100 萬元乘該機率，平均理賠 200 元。","若期望多賺 100 元，保費為 200＋100＝300 元。"],
  "110-mb-14": ["分母相同，較大的根號分配較多權重，總和較大","每個分子在 √2 和 √3 前的係數共 7。將一份 √2 換成 √3，值就增加。","D 有 5 份 √3，四項中最多，所以值最大。"],
  "110-mb-15": ["兩次除法都在 x＝2 檢查","f(x)＝(x−2)²Q(x)＋x＋2。令 x＝2，整個商的部分為零。","所以 f(2)＝4，除以一次式 x−2 的餘式就是 4。"],
  "110-mb-16": ["指數差可用兩個 y 值的比求出","A 的 x 為 log₂3，B 的 x 為 log₂6，差是 log₂(6/3)＝1。","y 的差為 6−3＝3，所以有向線段 AB 的分量是 (1,3)。"],
  "110-mb-17": ["巴斯卡三角形每一列加總是上一列的兩倍","下一列每個數是上一列相鄰數字相加，兩端也算進去。上一列每個數剛好貢獻兩次。","第一列和為 1，第十列是 2⁹＝512。"],
  "110-mb-18": ["連續三天可把日期切成固定的三組","從第 1 天起的值班者須連做三天；接下來只能由下一人連做三天，最後三天給第三人。","只需排列甲、乙、丙三個人，故為 3! 種。"],
  "110-mb-19": ["已知點數和為 8，先列所有可能的有序結果","結果為 (2,6)、(3,5)、(4,4)、(5,3)、(6,2)，共 5 種。","第一次是偶數的為 2、4、6 開頭，共 3 種，所以機率 3/5＝0.6。"],
  "110-mb-20": ["把題目條件和所求用平方連起來","由 (2x−y)²≥0，得 4x²＋y²≥4xy，所以 xy≤20/4＝5。","取 y＝2x 且 8x²＝20 時可達等號，xy＋2 的最大值為 7。"],
  "110-mb-21": ["組別人數不同，要用加權平均","三組身高總和分別為 500×161、200×166、300×171。","合計 165000 公分，除以總人數 1000，平均 165 公分。"],
  "110-mb-22": ["向量和可寫成以中點為基準的距離","AP=(x,y)，BP=(x−6,y)，相加是 (2x−6,2y)。","長度等於 10，兩邊除 2 後為 √((x−3)²＋y²)＝5，所以軌跡是圓。"],
  "110-mb-23": ["同時垂直兩條直線的方向可用外積","兩方向分別是 (2,3,4) 和 (2,−1,1)。外積為 (7,6,−8)，與兩個方向的內積都為 0。","再加上通過原點，直線可寫 x/7＝y/6＝z/(−8)。"],
  "110-mb-24": ["矩陣乘法按欄分開解","第二欄滿足 b−d＝7、3b＋2d＝1。由第一式得 d＝b−7，代入第二式得 5b＝15。","所以 b＝3。第一欄解得 a＝1、c＝−2，第二欄 d＝−4。"],
  "110-mb-25": ["二項分布的變異數是 np(1−p)","期望值 np＝5，標準差 2 表示變異數 4。","代入 4＝5(1−p)，得 p＝1/5。"],
  "110-mb-26": ["比較相對表現需用標準化分數","計算 (個人成績−全班平均)÷標準差。國文 −2、英文 2、數學 1、社會 −1。","英文的 2 最大，表示高於同科平均兩個標準差。"],
  "110-mb-27": ["A 部分固定選完後，再安排另外三題","B、C 一共 7 題，任選三題有 C(7,3)＝35。","扣除三題全來自 B 的 C(5,3)＝10，便符合 C 至少一題，得到 25 種。"],
  "110-mb-28": ["用等差關係寫出 d，再和等比關係比對","令 a、b、d 的公比 r，則 b＝ar、d＝ar²。等差公差為 b−a，故 d＝a＋3(b−a)。","得 r²−3r＋2＝0，根為 1、2。選項只有 2。"],
  "110-mb-29": ["原點到平面距離看法向量的長度","四個平面的常數項相同，到原點的距離都為 2 除以法向量長度。","四個法向量長度平方依序為 27、21、19、17；分母最小的 D 距離最遠。"],
  "110-mb-30": ["每天用前一天的兩地數量更新","第 1 天臺北為 0.6×200＋0.5×100＝170 台，其餘 130 台在新北。","第 2 天臺北為 0.6×170＋0.5×130＝167 台。"],
  "110-mb-31": ["拋物線通常只有一個變數帶平方","D 可把 y 寫成 x 的二次式；E 可把 x 寫成 y 的二次式，所以都是拋物線。","A、B、C 都有 x² 與 y²，且平方項同號，配方後不是拋物線。"],
  "110-mb-32": ["歪斜線在空間中既不相交也不平行","DF 與 BH、CE 都是體對角線，交於立方體中心；FC 與 DF 在 F 相交。","EG、AB 既不與 DF 相交，方向也不平行，所以 C、D 正確。"],
  "110-mb-33": ["把二次式配方後直接讀頂點","f(x)＝−2(x−1)²−1。頂點在 x＝1，最大值 −1，函數往左右可一直變小，沒有最小值。","式子恆為負，沒有 x 軸交點。因此 B、C、E。"],
  "110-mb-34": ["取圖中三角形內測試點，判斷半平面方向","例如 (1,0) 在內部，代入三條線：1＜4、3＞1、2＜5。","因此所有內點滿足 a−2b＜4、3a−b＞1、2a＋3b＜5。頂點附近的內點不一定 a＞b 或兩坐標皆正，故 A、C。"],
  "110-mb-35": ["同底對數可直接比較真數","5＞3＞2，所以 log₂5＞log₂3＞log₂2＝1。另一方面 0＜log₃2＜1。","綜合得 a＞b＞1＞c＞0，所以 A、B、C、E。"],
  "110-mb-36": ["圓錐曲線的交點數與擺放位置有關","例如雙曲線 x²−y²＝1 的頂點距原點 1，半徑小於 1 的同心圓和它不相交。半徑大於 1 時左右兩支各可交兩點。","移動曲線或相切時，交點數也可改變。本題依更正公告一律給分。"],
  "110-mb-37": ["每人可出 1～5 支，先把每種有序組合當等可能","最多 5＋5＋5＝15，所以 B；三人都出 3 支的機率為 (1/5)³＝1/125，所以 D。甲自己出 3 是 1/5。","按甲出 1～5 分開列舉，總和 9 的組合數依序 3、4、5、4、3，共 19；總和 8 為 4、5、4、3、2，共 18，故 C。"],
  "110-mb-38": ["終邊上點的坐標決定三角函數","x、y 都負，終邊在第三象限。點到原點的距離為 5，所以 sinθ＝−4/5，選 A、C。","B 只寫一圈內的角度範圍。若 θ 再加 360°，終邊不變但會超出範圍。tanθ＝4/3，(3,4) 則位於相反射線。"],
  "110-mb-39": ["正方形的對角線與邊夾 45°","斜率 5 是邊角的正切。若轉加 45°，新斜率為 (5＋1)/(1−5)＝−3/2。","若轉減 45°，新斜率為 (5−1)/(1＋5)＝2/3。兩條都可，選 A、D。"],
  "110-mb-40": ["「增加 2 倍」在原題指新增原數的兩倍","一天後的總數是原來的 3 倍，因此 100 變 300，B、E 成立。","指數成長時，半天為 100√3，兩天為 900，三天為 2700。注意「增加 2 倍」和「增加到 2 倍」不同。"],
  "110-en-1": ["privately＝私下地","前一句說她不喜歡公開談私事，所以她偏好私下談，和 publicly 相對。","effectively 是有效地，generously 是慷慨地。"],
  "110-en-2": ["military power＝軍事力量","後文的 army 和 navy 是陸軍、海軍，說明空格要修飾軍事力量。","若查歷史，題中 10 萬陸軍的典型限制出自一戰後《凡爾賽條約》；這不影響單字配對。"],
  "110-en-3": ["adopt a child＝收養孩子","這對夫婦無法生育，希望增加家庭成員，所以選擇收養。","sprain 是扭傷，elbow 可指用肘推，dodge 是閃躲。"],
  "110-en-4": ["lullaby＝搖籃曲","一邊搖晃嬰兒、一邊唱東西讓他入睡，唱的是搖籃曲。","helmet 是頭盔，medium 是媒介，property 是財產。"],
  "110-en-5": ["in isolation＝處於隔離狀態","句尾說目的是不讓其他人感染，因此疑似感染者應隔離。","intonation、construction、emphasis 分別是語調、建造和強調。"],
  "110-en-6": ["conserve water＝節約用水","刮鬍或刷牙時關水龍頭，是減少用水的具體做法。","grease 是塗油，mutter 是低聲說，vibrate 是振動。"],
  "110-en-7": ["contagious＝具傳染性的","流感或感冒能在人與人之間傳播，後面的 spread from person to person 直接解釋空格。","adolescent 是青少年的，transparent 是透明的，marginal 是邊緣的。"],
  "110-en-8": ["seating capacity＝可容納的座位數","體育場可容納多少觀眾，屬於容量。capacity 也可指設備的最大容積或能力。","digestion、fragrance、invention 分別是消化、香氣和發明。"],
  "110-en-9": ["assume＝以為、假定","有人以為蜘蛛是昆蟲，but in fact 引出與其假設不同的情況。","assign 是指派，devise 是設計，differ 是不同。"],
  "110-en-10": ["figure out＝弄清楚","要弄懂兩件事的關聯，才能解決它們造成的問題，所以接 figure out the connection。","take place 是發生，wear out 是磨損或精疲力竭。"],
  "110-en-11": ["under the weather＝身體不舒服","第二句直接用 feeling sick 解釋空格，說生病應避免開車。","out of the blue 是出乎意料；pie in the sky 是不切實際的期待。"],
  "110-en-12": ["put out the fire＝把火撲滅","消防員最終做的是滅火；加過去時間脈絡後 put 的形式仍相同。","put off 是延後，pass away 是過世，pass down 是傳承給下一代。"],
  "110-en-13": ["come around＝甦醒","Sebastian 先昏倒，fortunately 提示打電話前情況好轉，恢復了意識。","break in 是闖入，show off 是炫耀，cross out 是劃掉。"],
  "110-en-14": ["beat about the bush＝拐彎抹角","後面說直接切入重點、把事談完，表示請對方別繞圈子。","face the music 是面對後果，make ends meet 是勉強維持生計。"],
  "110-en-15": ["brush up on＝複習、重新練熟","課程不只給初學者，也適合曾學過、想把法語練回來的人。","find fault with 是挑毛病；lose track of 是失去追蹤；come up with 是想出。"],
  "110-en-16": ["used to＋原形表示以前常做","「以前喜歡打籃球，但現在沒時間」，用 used to enjoy 表前後對比。","be used to 或 get used to 表習慣，to 後若接動詞須是 V-ing。"],
  "110-en-17": ["過去式被動用 was／were＋過去分詞","國家公園是被建立的，in 1872 又是明確過去時間，所以用 was established。","established 單用會變成公園主動建立某物。"],
  "110-en-18": ["should have＋過去分詞表本該做卻沒做","Samuel 今早本來應該早起但沒有，後面的 but he didn't 正是提示。","用 should have gotten up，回頭評論已過去的事。"],
  "110-en-19": ["record-breaking＝破紀錄的","熱浪打破紀錄，形容熱浪用主動意味的 breaking，整組放在 heat wave 前。","record-broken 會把重點變成「紀錄被打破」，不符合這個固定形容詞。"],
  "110-en-20": ["have difficulty V-ing＝做某事有困難","有計算障礙的學童理解數字和符號較不容易，故填 understanding。","也可寫 have difficulty with numbers，其中 with 後接名詞。"],
  "110-en-21": ["間接問句保持陳述語序","C 的 what 就是 caused 的主詞，what had caused the problem 可直接放在 tell you 後。","A、B、D 把助動詞置於主詞前，像獨立問句，放進這裡要改語序。"],
  "110-en-22": ["逗號後的 which 可以指前面整件事","讓父母難過的是 Leo 決定離婚這件事，which 能作 upset 的主詞。","that 不用來引出這種逗號後的非限定補充說明。"],
  "110-en-23": ["過去分詞片語可交代主詞的情緒","Filled with anger 表 Owen 心中充滿怒氣，和衝出房間、摔門的動作相合。","To fly into a rage 在此會表目的；後半句不是為了故意發怒才離開。"],
  "110-en-24": ["It was said that…＝據說……","It 是形式主詞，that 後是傳聞內容，講《老人與海》的創作靈感來自一位漁夫。","其他選項無法把空格後完整的敘述接成一個合乎文法的句子。"],
  "110-en-25": ["副詞＋as＋主詞＋動詞可表示讓步","Bravely as the king fought 等於 Although the king fought bravely。","儘管國王作戰勇敢，仍與全軍一同被殺，前後語意能連上。"],
  "110-en-26": ["主旨是新式、可用意念控制的義手","文章談神經訊號難題、新植入物和義手能完成的動作，重心在先進義手。","腦機介面是對照的技術，並未涵蓋全文研究主題。"],
  "110-en-27": ["先找研究要改善誰的能力","研究對象是截肢者，功能是控制義手拿物品或做手勢。","因意外失去手的人最直接受益，失去聽覺或視覺者不是此研究目標。"],
  "110-en-28": ["peripheral 指周邊的","文中 peripheral nerves 是周邊神經，描述神經的位置。","prosthetic、bionic、artificial 則可在文中用來描述義肢或人造肢體。"],
  "110-en-29": ["回到研究成果找明示細節","文章說植入物用機器學習增強、解讀訊號，讓截肢者能精細控制義手。","原文並沒有說這種義肢用了 50 年，且舊的腦機植入方法反而具侵入性、成本高。"],
  "110-en-30": ["從最後一段推下一段可能繼續講什麼","結尾說較強的訊號讓演算法把意念轉成動作，且可立刻反應。","接下來最可能接著解釋這種義肢如何運作，選 A。"],
  "110-en-31": ["因果片語注意方向","濃霧是原因，車禍是結果。led to、resulted in、brought about、gave rise to 都由原因導向結果。","arose from 則說某個結果來自某原因，把 A from B 的因果方向倒過來。"],
  "110-en-32": ["修飾人可用現在分詞或關係子句","主句已有 is my new English teacher。前面的 lady 可用 sitting next to… 或 who is sitting next to… 修飾。","A、B 直接放另一個限定動詞而缺連接。E 的 are 也不合單數 lady。"],
  "110-en-33": ["介系詞後整個子句作受詞","whoever 在整個 whoever disagrees 裡作 disagrees 的主詞。anyone who 同樣可接 disagrees。","不能因前面有 with 就寫 whomever；空格裡仍要能當子句的主詞。"],
  "110-en-34": ["seem 可接形容詞、不定詞或 like 片語","seems very nice、seems to be nice、seems like a nice person 都自然。","seems 後在此不用 being nice 或 to being nice。"],
  "110-en-35": ["money 是不可數名詞","lots of、large quantities of、huge amounts of、a good deal of 都能表大量金錢。","a large number of 主要配可數複數，如 students。"],
  "110-en-36": ["花時間做某事的兩種結構","以人作主詞用 Liam spent six hours drawing…。以 it 作主詞用 It took Liam six hours to draw…。","D、E 各符合一種。take 的這個句型要有 to draw，不能直接接 draw。"],
  "110-en-37": ["unlikely 可用人作主詞或 it 形式主詞","James is unlikely to pass 說他不大可能通過。It is unlikely that James will pass 也傳達相同意思。","不能寫 James is unlikely that…；that 子句版本要用形式主詞 it。"],
  "110-en-38": ["instead 和 instead of 用法不同","B 用 instead of going…，表示去圖書館而沒有和我們去看電影。","E 另起一句 Instead, he went to the library，意思相同。先核對他真正去了哪裡。"],
  "110-en-39": ["讓步可寫 though、although 或 despite the fact that","A 的 Though in poor health 省略 she was；D 用 Although 加完整子句；E 用 Despite the fact that 加完整子句。","in spite of 需有 of，B 單獨用 even 不能連這兩個子句。"],
  "110-en-40": ["not until 有一般句、倒裝句和強調句","A：didn't begin… until…；B：Not until 開頭使主句倒裝為 did he begin；E：It was not until… that…。","C 缺完整結構，D 把強調句的 that 誤換成倒裝，兩種句型不能混用。"],
  "111-ge-1": ["扶養比看幼年、老年與壯年三組人口","扶養比＝(幼年＋老年)÷壯年。圖中甲的壯年占比最大，需扶養的兩組合計占比最小。","三角圖只有比例，不能判定總人口、壽命或移入移出率。"],
  "111-ge-2": ["印度季風氣候可分雨季、涼季與炎熱季","3～5 月在雨季到來前，日照強；6～9 月西南季風帶來水氣，雲量多。","冬季以東北風為主，1～2 月不吹西南季風，故選甲與乙。"],
  "111-ge-3": ["地形雨是含水氣的風被地形抬升","甲在喜馬拉雅山面向印度平原的一側，季風帶來的水氣沿山坡上升，冷卻後降雨。","選 B，圖中風沿山坡向上且雨落在迎風面。"],
  "111-ge-4": ["折線適合比較同一資料隨時間變化","歷年三級產業就業比例有時間順序，連成曲線可看出各產業的升降。","單一時點的族裔比例可用圓餅或長條圖，空間分布適合地圖。"],
  "111-ge-5": ["距離一條線一定範圍，選環域分析","將斷層兩側各延伸 50 公尺，可畫出帶狀的限制區。","這個指定距離內的區域是緩衝區，GIS 功能稱環域分析。"],
  "111-ge-6": ["西歐冬季有北大西洋暖流調節","暖流把低緯海水的熱量帶向西歐沿海，讓同緯度下冬季比許多其他地區暖。","西風有助海洋影響往陸地送，選項中直接對應正偏差的是暖流。"],
  "111-ge-7": ["比較季風強弱先看季節氣壓差","臺灣所在的東亞低緯季風區，冬季受強大的亞洲大陸冷高壓影響，東北風較強。","依標準答案選 B，指向臺灣的緯度與季風區位置；北回歸線本身不是風變強的直接原因。"],
  "111-ge-8": ["人口總成長包括自然增加與社會增加","自然增加率＝人口成長率−(移入率−移出率)。例如丁為 4.3−(4.1−7.2)＝7.4‰。","甲、乙各為 9‰，丙為 16‰，所以丁最低。"],
  "111-ge-9": ["判斷能否通視，連起兩點看中間有沒有高地","將甲乙連成一線，甲到乙這個方向沒有阻斷視線的更高山脊。","其餘指定方向會被圖中凸起的地形阻隔，依等高線判讀選 A。"],
  "111-ge-10": ["河谷的等高線尖端指向高處","線在兩條支流各向上游彎入，匯流處附近合看常像 M，所以 A。","山脊彎折尖端反而朝較低處；等高線即使被圖框截斷，沿地表延伸仍可閉合。"],
  "111-ge-11": ["同產品廠商合併屬水平整合","波音與麥道在相同產業層級，合併能將客戶、產能和市場份額集中。","主要目的符合擴大市場占有率；縱向整合才是把上下游串起來。"],
  "111-ge-12": ["偏遠產地的困難是資訊與通路","偏遠村鎮交通不便，也不容易取得市場需求與價格消息。","架網路改善資訊與銷售，並沒有增加農地或勞動力。選乙、丙。"],
  "111-ge-13": ["海埔地通常在淺海潮間帶","麥寮沿海原有泥沙淤積的潮埔，填海造陸後才成為大面積廠地。","海蝕平臺是波浪侵蝕的岩面，與這種填築前的地貌不同。"],
  "111-ge-14": ["石化廠選址受污染及環境負擔影響","石化廠的廢水、排放與環境風險使地方反對，選址才在多處之間爭議。","題目重點是污染問題，不是單憑冬季風勢或地價判斷。"],
  "111-ge-15": ["灌溉規模擴大可能使水資源超量使用","依原解選地下水位下降，可理解為盆地供水有限，灌溉擴張使取水量高於補注。","「只灌不排」也常有鹽分累積風險，所以不能據此說鹽鹼化會減緩。"],
  "111-ge-16": ["作物兼畜牧可用流程圖找兩支生產","題目有小麥與綿羊，要找作物和牧草流向市場或牲畜，牲畜再供市場的圖。","圖乙同時顯示作物、人工牧草與牲畜的經營關係，符合混合農業。"],
  "111-ge-17": ["機械化單一作物有環境與經濟代價","大規模單種作物會減少田間物種多樣性。大量生產可降低價格，使小農更難競爭。","因此乙、丙正確；美國高度商業化農業不必然依賴海外技術，也沒有一律改成酪農。"],
  "111-ge-18": ["由經緯線與海陸輪廓辨認南非西南部","圖中甲近南緯 35°、非洲西南岸，屬開普敦一帶的地中海型氣候。","南半球冬季受西風影響，雨較多；夏季乾燥。七月是當地冬季。"],
  "111-ge-19": ["地下暗渠利用山麓地下水","暗渠避開日曬、減少蒸發，竪井便利通風和維修，低滲透地層可減少漏水。","源頭在較高的山麓含水層，並非河口三角洲，所以 D 是不正確選項。"],
  "111-ge-20": ["馬緯度附近的副熱帶高壓讓氣流下沉","下沉空氣不易形成厚雲、降雨，杜拜在這一乾燥帶附近。","杜拜就在海岸邊，缺雨不能用距海遙遠解釋。"],
  "111-ge-21": ["沙漠沿岸都市缺乏廣布的沼澤水網","杜拜可見荒漠、海岸和灌溉栽種的棗椰。","在乾燥環境中很少形成大範圍密布的天然沼澤水道，因此排除 C。"],
  "111-ge-22": ["澳洲長期隔離，有利於獨特生物保存、演化","海洋阻隔限制與其他大陸物種交換，澳洲保有許多特有物種與有袋類。","乾燥氣候與岩漠還和氣壓、地形有關，孤立最直接對應生物差異。"],
  "111-ge-23": ["比較的是每位農業勞動者的產量","題目給農業人口占比低、產出高，分母是勞動人數。","這指單位勞力生產力高，不能由這兩個數字求出每公頃產量。"],
  "111-ge-24": ["歐洲西岸向南逐漸接近地中海型氣候","歐洲西岸北段海洋性較強，雨較常全年分布；南段夏乾冬雨更顯著。","因此從北到南，冬雨在全年降雨中的占比增加。"],
  "111-ge-25": ["安地斯高地都市兼具資源和氣候條件","部分都市因殖民採礦發展；在熱帶或低緯，高地又比低地涼爽，適合居住。","因此採礦和涼爽環境兩項同時符合，選甲、乙。"],
  "111-ge-26": ["規模經濟使平均每單位成本下降","丙圖直接畫出總產量增加、單位成本下降。甲圖的總成本仍增加，但越增越慢，由原點出發看平均成本也會下降。","依原解為甲、丙。讀圖要先確認縱軸是總成本還是單位成本，才能解釋同樣的下降趨勢。"],
  "111-ge-27": ["依各市場需求安排生產，可少備貨並減少過量","短週期產品先觀察需求，再分地出貨，較不用大量堆在倉庫，降低庫存費。","少量多樣也能避免大量生產卻賣不掉，故選甲、丙。"],
  "111-ge-28": ["OPEC 依石油輸出利益結盟","丁是石油輸出國組織，成員來自不同洲，合作基礎是石油政策。","NAFTA、歐盟與 RCEP 都更明顯以特定區域為主。"],
  "111-ge-29": ["從圖辨認成員跨東亞及大洋洲的經濟協定","丙是 RCEP，包括東協、中日韓、澳洲和紐西蘭，人口合計龐大。","題目要求人口與 GDP 規模同時比，依原題所據資料，選 RCEP。"],
  "111-ge-30": ["褶曲與擠壓造山最直接改變地形","板塊交界的擠壓使岩層彎曲、地表隆起，形成高聳山脈。","高溫、降雨與颱風主要由氣候條件造成，不是褶曲的直接結果。"],
  "111-ge-31": ["乾旱環境的房屋重視通風降溫與隔熱","風塔引風；少雨適合平頂；厚土石牆隔熱；小窗可減少日曬和風沙。","選 A、C、D、E。架高房屋常應對淹水、潮濕或凍土。"],
  "111-ge-32": ["歐洲的水氣來自鄰近海洋，並可深入陸地","大西洋深入海陸相間的區域；西風帶可輸送水氣。主要東西向山脈對從西方入陸的水氣阻隔相對較小。","題目配對是山脈走向和海陸分布，故 B、D。"],
  "111-ge-33": ["群聚產生共同客源與共享設施才是聚集經濟","工業區可共享設施與供應網絡，資訊商圈和夜市讓顧客一次接觸許多商家。","B、D、E 有同地群聚效益。單一連鎖門市和大型商店的效益也可能來自各自規模，不能單憑此就判為群聚。"],
  "111-ge-34": ["饑荒要同時看生產、人口與分配","乾旱能使農作失收；人口成長太快使人均糧食壓力變大，糧食生產或分配失衡也會使部分地區缺糧。","A、B、E。不能把全球暖化或自然資源耗用一概歸因於貧窮或開發中國家。"],
  "111-ge-35": ["高山森林線以上的植被受風與土壤條件限制","中央山脈高處風強、坡度陡、土層淺，較難讓高大樹木定根生長。","依題選 B、C、E，低溫也是一般理解高山植被的重要條件。"],
  "111-ge-36": ["地圖比例尺的分母越小，越能畫細節","等高距要考量地勢，地圖越大比例尺通常越詳細，選用比例尺也取決於欲呈現範圍。","選 B、D、E。影印縮放時，圖示比例尺隨圖一同比例變動；數字和文字標示不會自動改換。"],
  "111-ge-37": ["水庫攔水也攔住上游泥沙","下游得到的泥沙少，三角洲可能被海浪侵蝕後退。放流量減少也可能削弱稀釋和自淨。","蓄水改變附近水分、景觀和生態，故 A、D、E。下游淡水減少時河口鹽度反可能上升。"],
  "111-ge-38": ["赤道熱帶雨林全年高溫","不同植物在林冠、林下等高度形成垂直分層；近赤道的全年溫差小，故 A、D。","熱帶暴雨常淋洗土壤，養分多在生物體，不能直接說土壤肥沃。"],
  "111-ge-39": ["輪耕靠休耕使地力逐步恢復","輪流使用各區，其他區留一段時間讓植被與地力恢復，所以 B。人口壓力擴大時休耕期可能被縮短，因此 A。","依原解也選 E，原題以傳統低投入輪耕的技術條件描述；制度本身有適應當地生態的功能。"],
  "111-ge-40": ["熱帶雨林常見午後對流雨","強烈地面加熱使濕空氣快速上升，雨勢可強，但常集中在小範圍且時間短。","因此 B、D、E。氣旋雨並不是題中濕熱林區的典型日常降雨。"],
  "111-hi-1": ["以漢字筆談要找有漢文傳統的地方","越南知識階層過去曾用漢字與文言文，即使越語和日語不同，也能以書寫互通。","其餘地區沒有題中描述的廣泛漢文傳統。"],
  "111-hi-2": ["1937 年是日治皇民化的重要年代","「神國日本」「南方玄關」表明殖民者要臺灣配合戰時擴張並強化對日本的認同。","因此空格是培養皇民精神，和自治或民族自決的方向不同。"],
  "111-hi-3": ["第三羅馬論以東正教的承繼為基礎","拜占庭原是東正教重鎮；君士坦丁堡陷落後，莫斯科自許為正統信仰的中心。","把羅馬、拜占庭、莫斯科連成一線的是宗教傳播與教派認同。"],
  "111-hi-4": ["談自耕農、地主與租佃關係，指土地改革","政策想減輕耕作者負擔，同時以補償或制度調整處理地主利益，避免階級衝突。","因此要選土地改革；工業升級沒有直接處理土地與農民的關係。"],
  "111-hi-5": ["日耳曼同胞和併吞奧地利指納粹德國","1938 年希特勒推動德奧合併，以同族為號召，並施加軍事壓力。","演說把奧地利稱為同胞，這是辨識德國領袖的關鍵。"],
  "111-hi-6": ["煉鐵作坊證明聚落具有生產金屬器能力","作坊或煉鐵遺留顯示居民已能加工、製造金屬。","外來銅錢只表示交換，陶器紋飾與農業也不能直接證明煉鐵。"],
  "111-hi-7": ["在法國等地的華工墓園可連到第一次世界大戰","一戰期間協約國招募大批華工赴歐支援運輸、修築與後勤，不少人在異地過世。","地點是歐洲西線附近，不是主要在東亞交戰的清法或英法聯軍。"],
  "111-hi-8": ["找同一組史料共同記錄的對象","《東番記》和《番社采風圖》都可用來看早期臺灣原住民族社會，題中並列的第三種史料也可互證。","主題應放在生活與風俗，不能只憑其中一件來推貿易。"],
  "111-hi-9": ["日治後期的國語家庭政策獎勵日語使用","家中使用日語，可得到「國語家庭」資格並在就學、物資等方面取得優待。","「國語」在日治這裡指日語；題中提物資不足也提示戰時。"],
  "111-hi-10": ["古巴飛彈危機是冷戰對峙","蘇聯在古巴部署飛彈，美國視為近距離威脅；雙方在核武壓力下談判。","根本背景是美蘇陣營與意識形態競爭。"],
  "111-hi-11": ["希臘風格佛像來自希臘文化向東傳播","亞歷山大東征後，西北印度等地與希臘化世界有長期接觸。","佛教造像後來吸收波浪髮、深目、高鼻等雕刻特色，常連到犍陀羅藝術。"],
  "111-hi-12": ["開港後的領事館和海關常見英國人","清末臺灣港口開放通商後，英商及英籍海關人員活動頻繁。","淡水、安平、打狗和 1860 年後的通商制度是辨認英國的線索。"],
  "111-hi-13": ["被德、蘇瓜分且 1989 年走向非共政府的是波蘭","波蘭在一戰後恢復獨立，1939 年遭德國與蘇聯入侵瓜分。","二戰後進入蘇聯勢力範圍，1989 年團結工會參與政治轉型，符合題文。"],
  "111-hi-14": ["民教衝突與排外行動連到義和團","義和團排斥外國勢力並攻擊教民，列強以保護使館、僑民等為由出兵。","1900 年八國聯軍最符合這個導因。"],
  "111-hi-15": ["從題目限定的「清代北部」找地名","雞籠是今日基隆，和淡水同在臺灣北部，適合補進原史料的地點對照。","安平與打狗位於南部，水紗連多指中部山區。"],
  "111-hi-16": ["同鄉商人的共同據點是會館等組織","落腳、接洽、互助及維護交易利益，都是明清商幫和會館的功能。","題目問大量擴張的時期，與明清跨區商業發展相符。"],
  "111-hi-17": ["大圓頂、馬賽克與改為清真寺指聖索菲亞","這座建築原是拜占庭的大教堂，1453 年君士坦丁堡被奧斯曼攻取後改作清真寺。","位置在今日土耳其伊斯坦堡。題中的「博物館」指其歷史上曾作博物館的階段。"],
  "111-hi-18": ["黃河、運河與繁華市街指北宋汴京","汴京即今開封，靠水運取得物資，商業繁榮。","金攻入都城造成靖康之變、北宋滅亡，符合敘述後半段。"],
  "111-hi-19": ["清朝用髮式與文字管控加強統治","薙髮留辮可作服從政權的標誌，文字獄以文字或思想罪名查辦。","廠衛和廷杖更常用來辨認明代政治。"],
  "111-hi-20": ["青山王祭的線索是迎神驅瘟","移民從故鄉請靈安尊王來，希望平息瘟疫，後建廟祭祀。","這與臺灣王爺信仰的驅瘟功能接近。媽祖更常連到航海守護。"],
  "111-hi-21": ["退出澎湖改往臺灣，反映當時兩地管轄不同","明軍要求荷蘭拆城離開在其管轄下的澎湖，福建官員談妥荷蘭轉去臺灣。","題目據此判斷，當時臺灣不在明帝國實際統治範圍。"],
  "111-hi-22": ["勘合是驗證官方認可貿易的憑證","已指定港口、航路和入貢規則，並限制民間出海，符合明代朝貢貿易與海禁。","入貢、賞賜等詞表示交易由官方禮制安排。"],
  "111-hi-23": ["美國國土安全部和九一一後的反恐重組有關","2001 年九一一攻擊後，美國整合多個安全相關機構，建立國土安全部。","珍珠港在二戰時，古巴飛彈危機在冷戰，兩者都早於此部門。"],
  "111-hi-24": ["多次革命、帝國與共和國輪替指法國","19 世紀法國經歷拿破崙帝國、王政復辟、革命、第二帝國及共和政體。","「兩個帝國」與「三個共和國」比首都起義更能辨認國家。"],
  "111-hi-25": ["日治官營移民村要找日本移民政策","吉野、豐田等村有神社、日式學校及成套公共設施，是為安置移臺的日本移民規劃。","解決日本人口壓力及拓殖需求可解釋這些設置。"],
  "111-hi-26": ["15 世紀後期要找控制東地中海通路的政權","東方胡椒進入歐洲前需經亞洲與東地中海的交易網，威尼斯商人再從中轉運。","鄂圖曼土耳其掌控這一帶的重要路線，因此選 D。"],
  "111-hi-27": ["泉廈郊反映與福建沿海商貿","郊是舊時商人團體。臺灣中部大港對泉州、廈門往來頻繁，輸入衣料、器物等生活所需。","當時臺灣常輸出米、糖等農產，題目問進口的大宗，一般日用品最合。"],
  "111-hi-28": ["二戰削弱歐洲的海外市場控制","歐洲戰後要重建，美國的資本、產業與貿易力量相對增強，擴大海外市場。","題文所說的是大規模戰後的經濟勢力變化，依原解選第二次世界大戰。"],
  "111-hi-29": ["鄭氏靠原有的海商網絡取得財力","鄭氏在臺灣仍與日本和東南亞等地進行海上貿易，收入可支持軍政。","屯墾也供應糧食，但題問支撐與清抗衡的主要資源，選海外貿易。"],
  "111-hi-30": ["名教和個體自由的調和是魏晉思想線索","「自我逍遙」接近老莊與玄學，「人倫秩序」連到儒家的名教。","兩者都被關心，是魏晉士人對自然與名教的典型討論。"],
  "111-hi-31": ["羅斯福新政可用救濟、復興、改革來記","公共工程創造工作，失業救濟緩解生活壓力，商業及金融管制用於復興和改革。","穩定貨幣與物價也屬經濟穩定措施，選 A、B、C、E；新政不是採行法西斯主義。"],
  "111-hi-32": ["先期移墾社會的文教資源不足","設學有限、生活以墾殖為重，加上民變與械鬥，可能使科考準備較難，因此選 A、B、E。","題幹已說清治初期設有參試途徑；開山撫番是較後期政策。"],
  "111-hi-33": ["安史之亂後唐朝國力下降但未立即滅亡","江南生產、運河供應與茶稅更重要；藩鎮戍邊與權力增加，貿易也有朝海運發展的趨勢。","選 A、C、D、E。安史之亂在 8 世紀，唐朝到 907 年才滅亡。"],
  "111-hi-34": ["題目把財政動員與戰時經濟準備合看","認購國債和增加儲蓄能直接籌資；擴軍需產線、拓展南方貿易與投資產業也納入題目所指的戰備經濟。","校方答案為 A、B、C、D。E 較符合早期以農產品供應日本的政策框架。"],
  "111-hi-35": ["國內陣營對抗又有外部介入，可按地區判讀","西班牙內戰、中國國共內戰、朝鮮戰爭和越南戰爭皆有境外勢力參與。","題目年份有些位於戰事進行間，不一定是開戰年；1971 年的蘇聯沒有相應內戰。"],
  "111-hi-36": ["定居社會逐漸形成在地認同","跨祖籍共同信仰增加，慎終追遠改以本地開臺祖為重點，分類械鬥頻率逐步下降，故 A、C、D。","「不再有重大民變」太絕對，心向原鄉、希望歸葬大陸也不代表在地扎根。"],
  "111-hi-37": ["戰後東南亞排華有經濟和冷戰兩層背景","華人部分在商業上較具優勢，引起利益競爭；各國政府也擔心共產勢力擴張。","因此選 B、C。華人並非在每國都占人口多數。"],
  "111-hi-38": ["中國道教吸收多種在地思想與信仰","老莊提供思想語彙，方術、陰陽五行、民間巫術則影響修煉與儀式。","儒家倫常也影響道教倫理和社會實踐，依題意五項皆可。"],
  "111-hi-39": ["八世紀伊斯蘭政權與十五世紀收復運動指伊比利","羅馬衰落後西哥德勢力入主，後有伊斯蘭政權；1492 年格拉納達陷落，是收復運動末期的重要事件。","這條時序落在西班牙與葡萄牙所在的伊比利半島。"],
  "111-hi-40": ["西方七藝包含語文及數理兩組領域","文法、修辭、辯證為一組，算術、幾何、音樂、天文為另一組。古典希臘、希臘化及羅馬的自由教育是來源。","正式七藝體系在後世逐步成形，文藝復興承續。依題意選 A、B、C、E，印加不屬此教育傳統。"],
  "111-mb-1": ["矩陣加減要對照相同位置","用結果矩陣減已知矩陣，得 a＝−1、b＝2、c＝1、d＝2。","ab＋cd＝−1×2＋1×2＝0。"],
  "111-mb-2": ["投影到 yz 平面時令 x＝0","最短垂線平行於 x 軸，原來的 y、z 坐標都保留。","P=(12,4,1) 的投影為 (0,4,1)。"],
  "111-mb-3": ["根號差可用共軛因式化簡","1/(√(n＋1)−√n)＝√(n＋1)＋√n，因兩平方數相差 1。","n 越大和越大，D 的 √2022＋√2021 最大。"],
  "111-mb-4": ["絕對值不等式以中點向兩側量","離 2022 最多 111，左右端點是 1911 和 2133，都可取。","整數個數是右端減左端再加 1，得 223。"],
  "111-mb-5": ["極坐標的角度差是兩條半徑的夾角","111°−21°＝90°，從原點到 A、B 的長度為 4、5。","畢氏定理給 AB＝√(4²＋5²)＝√41。"],
  "111-mb-6": ["知道兩邊和夾角用餘弦定理","AC²＝10²＋20²−2×10×20×cos120°。","cos120°＝−1/2，所以 AC²＝700，AC＝10√7。"],
  "111-mb-7": ["標準差看分布離平均多遠","A 的資料依序相差 10，距平均 30 的偏差有 −20、−10、0、10、20。","其他選項的偏差幅度最多 2，甚至全部為零，因此 A 的標準差最大。"],
  "111-mb-8": ["完全落在正斜率直線時，相關係數為 1","檢查後四點 (1,3)、(2,5)、(4,9)、(10,21)，都滿足 y＝2x＋1。","只要移除 (0,10) 就保留這四點，得到最大的 r＝1。"],
  "111-mb-9": ["要讓小組少，先用每組最多人數估計","8 組至多 8×4＝32 人，裝不下 33 人，至少要 9 組。","6 組各 4 人、3 組各 3 人合計 33 人，因此 9 組能達成。"],
  "111-mb-10": ["選兩位值日生不分先後","先挑第 1 人有 10 種，再挑第 2 人有 9 種，但甲乙與乙甲是同組。","10×9÷2＝45 種。"],
  "111-mb-11": ["固定奶奶的位置後，再排列其餘人","前排正中已指定，剩下 6 人要各自坐或站到 6 個不同的位置。","位置排列共有 6!＝720 種。"],
  "111-mb-12": ["用六個不同數字任意排列有 6! 種密碼","0 可出現在第一位，密碼共有 720 組。輸入三組互異，因此錯一次就少一組可試。","三次均錯的機率為 (719/720)(718/719)(717/718)＝717/720。"],
  "111-mb-13": ["一次除式的餘式定理","除以 x＋1 時餘式是 f(−1)，因商乘 x＋1 的部分會變成零。","f(−1)＝−1＋111＋4.1＝114.1。"],
  "111-mb-14": ["配方找最低點，再比較左右端","f(x)＝(x＋1)²＋1，頂點 x＝−1 在範圍內，所以 m＝1。","x＝−5 離 −1 較遠，平方為 16，M＝17，故 M−m＝16。"],
  "111-mb-15": ["對數的底數與真數有條件","底數必須正且不等於 1，真數必須大於 0。A、B、C 分別踩到這些限制。","D 底數 10、真數 1 都合法，值是 0。"],
  "111-mb-16": ["對數相減變除法，指數可提到對數前","log111−log3＝log37；log8＝3log2。","因此加上 (2/3)log8 等於加上 2log2，答案是 2log2＋log37。"],
  "111-mb-17": ["矩陣乘法是左列乘右欄後相加","左上 3×3＋2×1＝11，右上 3×2＋2×(−1)＝4。","左下 1×3＋(−1)×1＝2，右下 1×2＋(−1)²＝3。"],
  "111-mb-18": ["扇形面積可由弧長直接計算","弧長 ℓ＝rθ，面積為 r²θ/2，把 θ 換成 ℓ/r。","面積＝rℓ/2＝8×2π÷2＝8π。"],
  "111-mb-19": ["走正方體表面的最短路可展成平面","相鄰面展開後，對角頂點分居長方形兩端。邊長 3，故所需長方形兩邊是 6 和 3。","最短長度是對角線 √(6²＋3²)＝3√5；穿過立體內的直線不是可走的表面路線。"],
  "111-mb-20": ["找遞迴數列可以先代入前幾項","a₁＝1/2，之後為 2/3、3/4。若前一項是 (n−1)/n，代入 1/(2−aₙ₋₁) 得 n/(n＋1)。","因此 a₁₁₀＝110/111。原題問 a₁₁₀，選項都寫 a₁₁₁，依公告一律給分。"],
  "111-mb-21": ["等差數列的和＝項數×首末項平均","從 1 加到 111，共 111 項，首末平均為 (1＋111)/2＝56。","答案是 111×56＝6216。"],
  "111-mb-22": ["底數在 0 與 1 之間，指數越大函數越小","x≤1，所以最大的可取 x 為 1。","在 x＝1 時取得最小值 (1/2)¹＝1/2。"],
  "111-mb-23": ["往返數手指每 8 次重複","從大拇指走到小指再回來，9 與 1 落在同一指，形成長度 8 的循環。","111＝8×13＋7，和第 7 次落在同一指，即中指。"],
  "111-mb-24": ["看橢圓與兩坐標軸的交點","圖形中心在原點，x 截距為 ±5，y 截距為 ±4。","代 x＝±5、y＝0 和 x＝0、y＝±4，得到 x²/25＋y²/16＝1。"],
  "111-mb-25": ["用中線、振幅和週期辨認正弦圖","圖的最大值 2、最小值 0，代表中線 y＝1、振幅 1。","相鄰兩峰相差約 π，對應 sin2x 的週期 π，所以是 sin2x＋1。"],
  "111-mb-26": ["同色的燈隔一個完整循環才重複","入口是黃燈，下一盞綠燈在 10 公尺。七種顏色循環，每次綠燈相隔 70 公尺。","第七次綠燈在 10＋6×70＝430 公尺。"],
  "111-mb-27": ["期望值是各獎金乘各機率後相加","兩硬幣等可能結果為正正、正反、反正、反反。兩正 1/4，一正 1/2，兩反 1/4。","平均獎金＝0×1/4＋100×1/2＋300×1/4＝125 元。"],
  "111-mb-28": ["獨立事件全部發生的機率相乘","每球命中為 0.9，三球都中就是 0.9³。","0.9³＝0.729，約七成。"],
  "111-mb-29": ["檢查 111 是否出現在等差數列","第 n 格放 1＋3(n−1)＝3n−2 粒。令 3n−2＝111，得 n＝113/3。","這不是整數，故沒有一格剛好放 111 粒。"],
  "111-mb-30": ["把機器判成 A 的車分為兩種","想像 100 輛車，10 輛是 A，其中約 9 輛被判 A；90 輛是 B，約 9 輛會誤判成 A。","已知被判成 A，只在這 18 輛中算，真正是 A 的有 9 輛，機率 0.5。"],
  "111-mb-31": ["原點到 (x,y) 的斜率為 y/x","B 的 y 負、x 正；E 的 y 正、x 負，兩者的斜率都是負數。","A、C 的分子分母同號；D 的 x＝0，是垂直線，斜率未定義。"],
  "111-mb-32": ["圓心、面積與直線距離分開檢查","圓心 (3,4)，半徑 √2022，故面積 2022π。圓心到 y＝x 的距離 1/√2 小於半徑，有兩個交點。","x＝1 距圓心僅 2，並非相切；y＝4＋√2022 剛好距半徑，相切。所以 B、C、E。"],
  "111-mb-33": ["用已分解的三次式看零點和正負","零點是 0、111、2022，皆為整數。110 時後兩因式同負，函數為正；2021 時恰一因式為負，所以 A、C 正確。","正首項係數的三次函數向兩端無界，沒有全域最大或最小；對稱中心 x 也不是 111。"],
  "111-mb-34": ["向量垂直就看內積是否為零","u·v＝3×2＋6×(−1)＝0，所以 B 正確。各項乘 −2 得 (−6,−12)，故 D 正確。","長度是 √(9＋36)＝3√5，E 正確。內積是數值，不是坐標。"],
  "111-mb-35": ["平行四邊形的兩條對角線互相平分","可把 A、B、C 任一點當未知點的對角，令兩條對角的坐標和相同。","A＋B−C＝(−12,8)，B＋C−A＝(14,−34)，A＋C−B＝(20,22)。所以 B、D、E。"],
  "111-mb-36": ["先標斜邊、對邊和鄰邊","C 是直角，所以 AB 是長度 10 的斜邊；對 A 來說，BC 是對邊，AC 是鄰邊。","BC＝10sin22°，且 22°＜45° 使鄰邊較長，故 A、C。tan22° 應為 BC/AC。"],
  "111-mb-37": ["特殊角要連同象限記憶","cos0＝1，sin(π/3)＝√3/2，故 A、B 正確。","cos(2π/3)＝−1/2，tan(3π/4)＝−1，tanπ＝0。"],
  "111-mb-38": ["緯線周長會因緯度增加而縮短","赤道是 2π×16＝32π。緯度 ±60° 的緯線半徑是 16cos60°＝8，因此周長 16π，C、E 正確。","本題 B 按校方採計的完整經線圈理解，周長 32π；單一從北極到南極的經線弧則為半圈。"],
  "111-mb-39": ["看指數圖右半邊的高低和增減","A、B 在右側遞增，底數都大於 1；x＝1 時 B 比 A 高，故 b＞a。C 遞減但其底數仍為正。","所有正底數在 x＝0 時值皆為 1，所以 A、D 正確。"],
  "111-mb-40": ["三視圖需把同方向前後重疊的方塊算成同一格","前視從左到右看最高堆疊是 3、2、1 格，符合 A；右視將不同欄重疊，得到 3 格和 1 格的兩排，符合 C。","上視只看地面哪些格子被占用。背排有左、中兩格，前排有中、右兩格，對應 E。"],
  "111-ch-1": ["比對讀音的聲、韻、調","「囹」和「伶」都讀 ㄌㄧㄥˊ。囹圄指牢獄，伶可指表演者。","綮／紊、妣／比、沮／殂在題中讀音各不同。"],
  "111-ch-2": ["用字要符合固定詞形","D 的「各行其是」是各自認為自己的做法正確；「無所適從」是無法知道該依從哪方。","A 應為出類拔萃、穩操勝券；B 應為別出心裁、膾炙人口；C 是徇私舞弊、軒然大波。"],
  "111-ch-3": ["同字代成白話再比較","B 的兩個「固」都指「本來、原本」。一處說書法本就難看透，另一處說臺灣原本是海上荒島。","A 是假如沒有／暗中；C 是不久／已經；D 是終究／士兵。"],
  "111-ch-4": ["用文章出處和景象填空","〈蒹葭〉出自《詩經》。蒹葭是水邊植物，水湄就是水岸。","「潺湲」寫水流的樣子，能接「秋水」；「躑躅」是徘徊或停滯。"],
  "111-ch-5": ["辨認眾口造成的錯誤印象","眾口鑠金與三人成虎都能說明很多人反覆說一件事，足以讓人誤信、混淆真相。","以鄰為壑是把禍害推給別人，春蚓秋蛇則形容字寫得彎曲難看。"],
  "111-ch-6": ["謙遜用語通常降低自己的姿態","B 的寡人、C 的愚、D 的竊都用來謙稱或委婉表達。","A 用「豎子」斥責別人，沒有降低自己的姿態。"],
  "111-ch-7": ["先拼好轉折，再接句尾","乙的「雖然」和甲的「也」連起來：即使審美較弱也會驚奇。","丁以「但」轉到住在當地的人，丙再接「除了……以外」和末句的感受，順序乙甲丁丙。"],
  "111-ch-8": ["題辭要配合使用對象和場合","桃灼呈祥源於桃花盛開的婚嫁意象，適合結婚賀詞。","杏壇指教育，醫界用杏林；椿庭指父親；甘棠遺愛常用於稱頌或追念有德政者。"],
  "111-ch-9": ["述補結構的後字補充動作結果","「閱畢」先是閱讀，畢補充說明讀完了，和「砌成」的砌、成關係相同。","看見動詞後可追問「做得怎樣／是否完成」；能回答的詞往往是補語。"],
  "111-ch-10": ["借代是用相關事物替代本名","五十弦可代樂器或樂聲，祝融可代火；這些都能試著改回所指的事物。","A 的松柏與雞鳴用來比喻逆境中的節操，重點是相似情境，因此依原解選 A。"],
  "111-ch-11": ["三言二拍是明代白話短篇小說","三言由馮夢龍輯編，二拍由凌濛初編著，都是白話短篇代表。","「水三西金」是章回長篇；清末譴責小說著重揭露社會問題，不能歸成現代主義小說。"],
  "111-ch-12": ["由比喻找共同道理","跟善人或不善人相處，會像長久待在有香味或臭味的地方，慢慢受環境影響。","「是以」是所以，接君子要慎選相處對象，正好把前面的比喻收束。"],
  "111-ch-13": ["詞和曲都源於配樂歌唱","《東坡樂府》是詞集，《東籬樂府》是散曲集，兩者書名都能見到「樂府」。","具體字數、押韻和平仄依詞牌與曲牌而定，不能一概套用律詩規則。"],
  "111-ch-14": ["先秦哲理散文常以寓言說理","《韓非子》運用故事闡明法、術、勢等政治思想，符合 A。","《春秋》用語簡短；《詩經》也含祭祀樂歌；楚辭有長短句與「兮」等特色，並非多用四言。"],
  "111-ch-15": ["用年代與關鍵典故辨認人物","B 的逐荷、國姓明指鄭成功，A 的兒孫投降寫鄭氏後代，D 的鯨魚意象也和鄭成功的吟詠相聯。","C 出自蘇軾〈虞姬墓〉，寫項羽敗局中不相負的人；「鄭君」不是鄭成功。"],
  "111-ch-16": ["小說改寫可用事件定位人物","滄州、陸虞候、誤入節堂、發配都指向《水滸傳》中的林沖。","詩中兩種外貌描寫都落在同一位「好漢」身上，選 D。"],
  "111-ch-17": ["禍福可以互相轉化","逆境雖苦，可能讓人日後更能感恩；富裕順遂也可能使人難承受挫折。","老子說禍福相倚、相伏，最能說明這種表面處境與實際結果的變化。"],
  "111-ch-18": ["袁弘道重視作品出自本色","弟弟的詩即使有瑕疵，只要是真情與獨造之語，作者仍喜歡。","相反地，即使看起來工整，若是粉飾模仿前人，作者仍感到可惜。C 同時抓到這個評價標準。"],
  "111-ch-19": ["身體受挫仍可成就創作","貝多芬、米爾頓雖失去聽覺或視覺，仍能完成作品。","A 同樣列出左丘失明與孫子受刑後著書，焦點都是苦難沒有阻斷創作。"],
  "111-ch-20": ["化用題要一組一組找變形過的意象","詩中的月與驚鳥對應 A；空山、石邊青苔對應 B；澗邊、花開花落可連到 C。","全詩沒有送別後掩柴門、問王孫明年歸不歸的主線，因此未化用 D。"],
  "111-ch-21": ["蕭統是昭明太子","南朝梁的蕭統組織編選文學作品，這本詩文總集因他得名《昭明文選》。","《世說新語》偏重人物言行傳聞。看見編者蕭統，比只看「古代總集」更容易定位。"],
  "111-ch-22": ["學習要完成最後一步","射百次有一發不中，走千里差一步沒到，都不能算完整達成。","這兩個比喻特別強調做到最後，最接近善始善終。"],
  "111-ch-23": ["分辨記遊散文、議論文與應用文","〈鹿港乘桴記〉記遊並描寫鹿港風物，不宜和自序一起概括為應用文，所以 B 最不恰當。","〈勸和論〉勸族群和睦，偏議論；〈畫菊自序〉是女性作者以駢文寫的自序。"],
  "111-ch-24": ["前後七子屬秦漢復古路線","其代表主張是文章取法秦漢、詩歌取法盛唐，因此 B 正確。","「義理、考據、詞章」常連到桐城派；公安派重性靈。唐宋派是明代取法唐宋古文的群體。"],
  "111-ch-25": ["武侯祠與羽扇綸巾指諸葛亮","南陽躬耕、扶持蜀漢，加上西蜀靈祠，三條線索指向諸葛亮。","A 的杏壇是孔子；B 的酒和籬下偏陶淵明；C 的〈原道〉與吏部指韓愈。"],
  "111-ch-26": ["不能毀掉達成目標所需的根本條件","孟子說想天下無敵卻不行仁，好比手拿燙物卻不肯用水降溫。","C 說砍樹根卻求枝葉茂盛、堵源頭卻求水流長，同樣指出手段與目標相反。"],
  "111-ch-27": ["「為某人言」的為是對、向","「石簀數為余言」是石簀多次對我說；「不足為外人道」是不用對外人講。","A 的為指是或在於，B、D 出現在表示被動的「為……所……」結構。"],
  "111-ch-28": ["分清季節、月色與一日中的時刻","開頭先以春天、月色寫西湖最盛。由兩條線索合看，D 的春天月夜最符合題意。","朝煙夕嵐是限於一天之中對不同時刻的描寫，沒有取代全段開頭的判斷。"],
  "111-ch-29": ["逆旅是旅舍，過客是暫時經過的人","「光陰者，百代之過客也」以過客比喻時光匆匆流過世世代代，B 翻譯正確。","A 把逆旅誤解為逆境。D 的大塊是大自然，文章在這裡指美好文采般的景象。"],
  "111-ch-30": ["「浮生若夢，為歡幾何」感嘆生命短促","人生像夢，能歡聚的時光有限，因此值得把握春景、與親人夜宴。","「天倫」及篇名的「從弟」顯示是親族相聚；秉燭夜遊不是為追求刺激。"],
  "111-en-1": ["firecrackers 是鞭炮","春節等慶典常燃放鞭炮，後文的失明、受傷呼應爆炸意外。","murmurs 是低語，sculptures 是雕塑，manufacturers 是製造商。"],
  "111-en-2": ["suppress 是壓制","前半句說獨裁者靠言論自由掌權，後半句轉折成掌權後壓制別人的言論。","resume 是恢復，acknowledge 是承認，nominate 是提名。"],
  "111-en-3": ["illegal 是違法的","冒用他人的個人資訊屬身分竊用，後半句的 criminal act 就是明確提示。","desirable 表值得追求，reasonable 表合理，兩者皆不符語意。"],
  "111-en-4": ["beauty contest 是選美比賽","Emma 參賽並獲得小姐頭銜，可由 took part in 和 won the title 推知。","kidney、lobster、shadow 分別是腎臟、龍蝦、影子。"],
  "111-en-5": ["deteriorate into 是惡化成","原本理性的討論變成爭吵，方向是由好到壞。","innovate 是創新，fortify 是強化，contemplate 是沉思。"],
  "111-en-6": ["national anthem 是國歌","動詞 played 表示閉幕式會播放或演奏音樂，向奧運的發源地希臘致意。","resort 是度假地，tariff 是關稅，wreath 是花環。"],
  "111-en-7": ["descend 是下降","戲演完時布幕降下，故 curtain descended 可理解為落幕。","grumble 是抱怨，humiliate 是羞辱，migrate 是移動或遷徙。"],
  "111-en-8": ["analyze 是分析","Javier 生氣時先坐下，想想怒氣底下的感受，藉此冷靜。","embarrass、horrify、wrinkle 分別是使尷尬、使驚恐、使起皺。"],
  "111-en-9": ["versatile 是多才多藝的","後面列出壘球、足球、地板曲棍球等多種擅長的運動。","excel in 是擅長於；trivial 是微不足道，cowardly 是怯懦。"],
  "111-en-10": ["put off 是拖延","until tomorrow 和 do today 形成對照，句意是今天能做就別拖到明天。","call off 是取消，take off 可指起飛，turn off 是關掉。"],
  "111-en-11": ["check in 是報到","他想在起飛前兩小時到機場，做的是辦理登機報到。","give up 是放棄，get off 是下車，burst out 是突然發出聲音或做出動作。"],
  "111-en-12": ["cost an arm and a leg 是非常昂貴","後面說許多人負擔不起學費，提示價格高。","make ends meet 是勉強維持收支，rack one's brain 是絞盡腦汁。"],
  "111-en-13": ["on cloud nine 是欣喜若狂","他原本找不到工作而沮喪，finally received a job offer 讓情緒轉好。","down in the dumps、in a blue funk 都偏低落；hot under the collar 是生氣。"],
  "111-en-14": ["read between the lines 是讀出言外之意","女友沒有明說不高興，Liam 從信件字裡行間推知。","keep one's chin up 是振作；get on one's nerves 是惹人心煩。"],
  "111-en-15": ["ring a bell 表似曾相識","聽到飯店名稱覺得熟悉，但想不起在哪讀過，正好符合 rang a bell。","take a rain check 是改天再接受邀請，cry for the moon 是追求不切實際的事。"],
  "111-en-16": ["as if 是彷彿","他對 Hazel 呼來喝去，彷彿她是奴隸。were 在此帶有非事實的假設語氣。","since、because 可表示原因，不符合這裡的比較。"],
  "111-en-17": ["find it＋形容詞＋to V","it 先占受詞位置，真正被判斷為不可能的是後面的 to lose weight。","套回 find it impossible to… 即「覺得做某事不可能」。"],
  "111-en-18": ["過去進行式表示當時正在做","停電是突然發生的事；Charlotte 洗澡是當時已在進行的動作。","用 was taking a shower 搭配過去式 went out。"],
  "111-en-19": ["when 後可省略與主句相同的主詞和 be","Malala 是獎項的接受者，完整寫法是 when she was given the award。","省略 she was，留下 given，仍保有被動意思。"],
  "111-en-20": ["where 修飾表示地點的先行詞","cafeteria 是地點；在那裡可以享用不同早餐。where 等於 in which。","which 或 that 單獨放進去，無法表達「在餐廳裡」。"],
  "111-en-21": ["動名詞片語可以作主詞","指引提出一個預防方法，空格後是 is one of…；因此 washing your hands 整組作主詞。","加 by 會成方法介系詞片語，無法單獨擔任這裡的主詞。"],
  "111-en-22": ["all we have to do is＋原形動詞","「我們要做的就是……」是常用句型。題目已給 learn 原形，可搭 all we have to do。","constantly 是副詞；the task is 之後一般用 to learn。"],
  "111-en-23": ["Only by 放在句首，主要子句倒裝","Only by helping others 是「唯有透過幫助人」。後面用 will you learn。","簡單還原可寫 You will learn… only by helping others。"],
  "111-en-24": ["owing to＝由於","Alora 全程坐著，是因為之前受過傷。Owing to 後面接名詞片語 the previous injuries。","B 是完整句，只有逗號不能直接連主句；C、D 也缺乏適當的連接。"],
  "111-en-25": ["the＋比較級，the＋比較級","朋友越多，聚會與禮物花的錢就越多。前後兩邊都要以 the more 開頭。","這裡的 the 表達「越……就越……」，不用另外再加 if。"],
  "111-en-26": ["主旨要能包住定義、目的和做法","文章先定義 NVC，接著說同理和合作，再介紹模型的部分要素。","C 是完整的「介紹」。文章沒有把年代沿革或流行程度當重點。"],
  "111-en-27": ["用 OFNR 的字首推未知項","文中已列 Observations、Feelings。前文又談表達需要與提出請求。","所以 N 是 Needs，R 是 Requests，合起來正好是 OFNR。"],
  "111-en-28": ["感受用情緒名稱表達","frustrated 是感到挫折，描述說話者當下的心理感受。","betrayed、ignored、unimportant 比較像在描述他人怎樣對待自己、或怎樣看自己。"],
  "111-en-29": ["先陳述可觀察事實，再往下談","文中用具體發生的言行對照給人貼標籤，說明 observation without evaluation 的做法。","判斷、道德評價和籠統定性正好與這個做法相反。"],
  "111-en-30": ["提出請求前，要能接受對方拒絕","文章說對方可以說 no，只有真心的 yes 才是想要的回應。","所以 NVC 無法保證特定結果；它不以操弄或迫使他人為目標。"],
  "111-en-31": ["表達致力於可用 dedicated、devoted 或 devotion","was dedicated to、was devoted to、showed devotion to 後面都能接 helping。","decided to 和 determined to 在此用法須接原形 help，不能直接接 helping。"],
  "111-en-32": ["成員組成陪審團：以成員作主詞","made up、constituted 都可表示這些人組成陪審團。comprised 在此可理解為構成。","校方接受 BDE 或 BE。consisted of 要以整體作主詞，成員放在 of 後。"],
  "111-en-33": ["表示目的的 to 後接原形","in order to improve 和 so as to improve 都合用。","with a view to、with an eye to 的 to 是介系詞，若接動詞須用 improving；for the purpose of 也接 V-ing。"],
  "111-en-34": ["逗號內可用關係子句或同位語","which was used by… 補充說明 Latin。the language used by… 則用同位語，兩者都合文法。","逗號後的非限定關係子句不用 that；it was 會另開完整句而缺連接。"],
  "111-en-35": ["被視為可用 viewed、regarded、referred to、looked on","B、C、D、E 都能和後面的 as the father of modern physics 搭配。","thought 要用 thought of as，題目 A 沒有 of。"],
  "111-en-36": ["看分手和愛上別人誰先發生","B 用 Hardly had… when…；D 用 No sooner had… than…。兩者都先分手，後愛上別人。","其他選項顛倒先後。記得 hardly 配 when，no sooner 配 than。"],
  "111-en-37": ["not only… but also… 要平行","A 的 spent、borrowed 都是過去式動詞。D 將 Not only 放句首，才改成 did Ava spend。","but 後的子句維持 she also borrowed，不需要再倒裝。"],
  "111-en-38": ["間接問句保持主詞在動詞前","A 的 There is no telling 和 B 以 when 子句作主詞，都能表達無從知道。","when an emergency will occur 是正常語序。C、D 把 will 放在主詞前，成了直接問句語序。"],
  "111-en-39": ["whether 子句可直接作主詞或放到句末","C 以 Whether you win or lose… 作主詞；D 用 It 當形式主詞，再把 whether 子句放後面。","兩句都說輸贏是運氣問題。either 或 no matter 在此不能直接取代名詞性 whether 子句。"],
  "111-en-40": ["用完整主詞表示「那些……的人」","He who、Whoever、Those who 都能構成主詞，B、C、D 成立。","Those who 是複數，配 look、are；Whoever 在此作單數。A 的 Who 單獨出現不合這個泛指句型。"],
  "112-hg-1": ["把公民權辯論放回奴隸制度的時代","題幹出現選舉辯論、白人公民權、黑人與原住民族，對應 19 世紀中葉美國圍繞奴隸制度與種族權利的政治爭議。","先用年代和對象定位。題中的說法反映當時的排斥立場，不能當成美國制度的普遍原則。"],
  "112-hg-2": ["觀察學者替哪一方的決策辯護","題幹肯定製造洪水可拖延日軍，讓中國軍隊經武漢撤退並重組，指的是抗日戰爭中的花園口決堤。","決策由國民政府主導，文中著重它的戰略理由，所以立場較接近 A。洪水另造成嚴重民間災難。"],
  "112-hg-3": ["珍珠港遇襲後美國針對日裔居民採取拘禁政策","1941 年珍珠港遇襲，美國對日參戰，後以軍事需要為由強制遷移並收容許多日裔居民。","題幹提示事件直接引起美國反日情緒及戰時命令，對應 D。甲午或日俄戰爭發生時沒有這個配套背景。"],
  "112-hg-4": ["分開判斷古代共用文字和殖民時期的共用語言","古代東亞各地口語不同，但許多知識階層都曾用漢字書寫。第一空是漢字。","1930 年代日本的勢力涵蓋臺灣、朝鮮和中國東北部分地區，日語成為其統治與部分社會往來使用的語言。"],
  "112-hg-5": ["文獻作者要符合年代和用語","1920 年正值日治時期，「蕃地」等是殖民官員常用的分類詞，敘述也像從統治者觀點記錄疫情。","田健治郎當時任臺灣總督。馬偕已於 1901 年去世；其他人的年代或身分較不合文書視角。"],
  "112-hg-6": ["教宗任免主教與廢黜皇帝的主張是在擴張教權","題幹把任免主教的權力限定給教宗，還聲稱能廢黜皇帝，可看出他主張教權高於世俗君權。","因此是要確立羅馬教會的崇高地位。這種主張本身也會讓教宗與皇帝產生衝突。"],
  "112-hg-7": ["從地方變成中央，要找中央政府何時搬來","1945 年日本投降使臺灣政權轉換，1949 年國共內戰後中華民國中央政府遷臺，才符合題目的『中央政府所在地』。","韓戰影響後來局勢，但不是中央政府遷臺的直接原因。"],
  "112-hg-8": ["題幹問從中古逐步轉向近代的早期轉折","文藝復興強調人的價值、古典學習與新的學術、藝術觀察方式，常被視為歐洲由中古轉向近代的重要分期。","啟蒙運動也強調理性，但出現較晚。題目用『逐漸』和『初步』提示較早的轉折。"],
  "112-hg-9": ["清廷宮廷畫的寫實風格可聯想到西洋傳教士","乾隆宮廷的耶穌會士畫家，如郎世寧，常結合西洋透視和光影與中國宮廷繪畫。","馬匹的體態、細節與立體效果是題幹線索。士紳畫偏文人表現，並非此處的主要指向。"],
  "112-hg-10": ["臺灣話文論與左翼文化運動的時代交會","臺灣話文論主張以臺灣話作為現代書寫工具。題目又加入無產階級訴求與殖民政府取締，對應日治時期 1930 年代。","1870 年代尚在清治，1960 年代已是戰後；需同時核對語言主張與統治背景。"],
  "112-hg-11": ["用世紀判定中原人口的大規模南遷","永嘉之禍在西晉末年，311 年洛陽陷落，北方士族與居民大批南渡，影響江東。","安史之亂在 8 世紀，靖康之禍在 12 世紀，八國聯軍在 1900 年，均不合題目的 4 世紀。"],
  "112-hg-12": ["1938 年的反猶暴力指向納粹德國","1938 年 11 月納粹德國及其支配地區爆發大規模反猶襲擊，又稱水晶之夜。題目的政權是希特勒領導的納粹政權。","人物被拿來作宣傳，判斷政權要扣住 1938 年、德意志與反猶迫害。"],
  "112-hg-13": ["區分南移與『沿海商業城市成為重心』","鴉片戰爭後，通商口岸開放，上海等沿海城市因外貿、金融與近代工商業發展而成為經濟中心。","宋元的經濟南移主要描述江南經濟地位上升，還不等同於題幹說的沿海商業城市取代農業重心。"],
  "112-hg-14": ["從錄用不同族群推回平等原則","奧米亞王朝較以阿拉伯人為統治核心，阿拔斯王朝擴大任用波斯人、土耳其人等。","用人不只看是否阿拉伯出身，對應題目要找的一律平等。一神信仰和先知概念不直接回答用人的問題。"],
  "112-hg-15": ["『因信稱義』是馬丁・路德宗教改革的辨識詞","因信稱義指人因信仰而得稱為義，並非靠購買贖罪券。此主張與路德的改革最直接相關。","羅耀拉是耶穌會的重要創立者，培根與經驗研究有關，薄伽丘則是文藝復興文學家。"],
  "112-hg-16": ["圖幅相同時，畫的實地範圍越小，比例尺越大","校園範圍小於一個行政區或整個捷運路網，所以同樣大的圖能放大呈現更多校園細節。","例如 1：1,000 比 1：100,000 大，因圖上同樣長度對應的實地距離較短。"],
  "112-hg-17": ["辨認產業群聚與聚集經濟的關係","題中說產業鏈、人才和知識在同一區域集中互動，這種企業與相關機構集中於一地的現象是產業群聚，校方答案為 C。","A 的聚集經濟指群聚帶來的成本降低、人才共享等效益。題幹寫『經濟效益』也容易讓人想到 A，兩個名詞可用『集中現象』與『集中後的好處』來區別。"],
  "112-hg-18": ["將各地早上換成同一個時間基準","東京位於較東側，當地開市換算成世界時間通常最早，倫敦次之，紐約最晚。","也可用大致時差記憶：東京 UTC+9，倫敦約 UTC+0，紐約約 UTC−5，季節調鐘不會改變這題的先後。"],
  "112-hg-19": ["人口金字塔能看當期結構，趨勢需要多期資料","圖形底部較窄、中高齡層較寬，表示少子化、年齡結構向中高齡集中。","公布答案為 A，但題圖只有一個時間點，無法單憑這張圖確認扶養比『持續』遞減。D 的銀髮需求可由高齡結構合理推想；考試計分仍依公布答案。"],
  "112-hg-20": ["跨國河流上游興建水壩會影響下游","水力發電常涉及攔水與調節放流。如果同一河流流過多國，上游的設施會改變下游可用水量和季節流量。","風、太陽能不直接改變跨境河水分配，因此本題選水力發電。"],
  "112-hg-21": ["人口與產業向新都市集中是都市化的表現","公務機關先遷入，相關產業與人口跟著集中，促使當地由非都市地區走向都市化，所以選 A。","都市成長常強調原有都市的人口或經濟規模增加；都市更新則是整建既有市區。"],
  "112-hg-22": ["飲食禁忌可用來辨識區域文化","伊斯蘭飲食規範不食豬肉。阿拉伯聯合大公國的主流信仰是伊斯蘭教，餐飲因此常調整肉類使用。","各地皆可能有清真餐廳。題目強調的是全國普遍的飲食習慣，因此 D 最符合。"],
  "112-hg-23": ["季風會隨季節改變方向，可安排往返航期","帆船向一個方向出航後，等季節更替、風向反轉再回航。鄭和船隊在東南亞與印度洋利用的是季風。","海陸風主要是日夜循環，尺度與遠洋往返需求不同。"],
  "112-hg-24": ["用地塹、斷層湖和雪山辨認東非","非洲高地上有大裂谷、火山與斷層湖，是東非地形的線索。即使接近赤道，高山也可能積雪。","圖上乙在非洲東側，對應東非裂谷與吉力馬扎羅山一帶。"],
  "112-hg-25": ["環域分析能找出指定距離內的範圍","把活動斷層或溪流當成一條線，向左右各畫固定距離，就得到一條不能開發的帶狀區。","GIS 將這種指定距離建區的功能稱為環域分析。若再與地籍圖比對，才會另用疊圖。"],
  "112-hg-26": ["林木生長要先看有沒有足夠水分","紐西蘭受海洋影響，許多地方較濕潤，生長條件有利林業；澳洲大片內陸乾燥，並非面積大就能有較高的林業出口比重。","因此本題用降水和林木生長來解釋紐西蘭的表現。"],
  "112-hg-27": ["海蝕平臺離開現今海面後可形成海階","波浪先在接近海面處侵蝕出平坦岩面。若陸地抬升或相對海面下降，平臺離水抬高，便留下海階。","V 型谷變成谷灣反映海水進入河谷，屬沉水現象。"],
  "112-hg-28": ["鮮菜運輸速度會影響可服務的市場","中山高速公路通車後，卡車可更快把彰化、雲林蔬菜運往臺北，降低損耗，使較遠的產地也能專業生產。","題目特別說『距離甚遠』，要優先找能縮短運輸時間的因素。"],
  "112-hg-29": ["多地傳統融成一個地方節慶是文化合成","題幹同時列原住民傳說、非洲文化和多個歐洲節慶元素，最後共同形成巴西地方的奔牛節慶。","焦點是不同文化交流後形成新形式，因此選多元文化的合成。"],
  "112-hg-30": ["先定位出發點，再沿順時針方向排出海岸","由南方澳順時針先向南：當地沙頸岬接著是東部斷層海岸，繞到南端可見珊瑚礁海岸。","再往西部可見離水洲潟，最後經北部、東北部沉水谷灣回到宜蘭，依序為戊甲乙丙丁。"],
  "112-hg-31": ["賦稅由實物為主逐漸轉向用錢、用銀","兩稅法以資產和田地等為基礎，用貨幣計算稅額，實際仍可有錢物兼納；明代一條鞭法將多項賦役合併折銀。","清代攤丁入地把丁銀納入田賦，因此 C、D、E 符合貨幣化的方向。"],
  "112-hg-32": ["材料題找作者說法，以理解立場","作者同情纏足女孩，主張外力取代政府後發布禁令，並將外部強權的介入視為正當，因此選 B、C、E。","A 說肯定清廷，與文中批評清廷無力相反。D 則把立場改成抵抗西方，亦與材料不符。"],
  "112-hg-33": ["義大利與德意志在 19 世紀由分立走向統一","義大利王國在 1861 年成立，1870 年取得羅馬後完成主要統一；德意志帝國於 1871 年成立。","題目抓的是 1870 年代初完成統一的時間，並以民族主義動員為共同背景，選 B、C。"],
  "112-hg-34": ["荷蘭在臺南建立據點，西班牙從北臺灣進入","17 世紀上半，西班牙曾據有基隆和淡水一帶，荷蘭勢力主要在臺灣南部。","1642 年荷蘭逐出西班牙，使南北主要殖民據點歸同一勢力，選西班牙與荷蘭。"],
  "112-hg-35": ["先分別找三國的殖民經驗，再取共同點","印尼曾受荷蘭殖民，越南曾受法國殖民，印度曾受英國殖民。三地都經歷民族獨立運動，故選 A、E。","印度、越南的主流信仰和印尼不同；三國也沒有共同成為日本殖民地。"],
  "112-hg-36": ["極冷冬季、短夏與少量降水指向西伯利亞的副極地氣候","圖中冬季氣溫接近 −45°C、夏季短暫轉暖，對應西伯利亞常見的針葉林帶。森林地區可見酸性灰化土，選 B、C、E。","凍土地區可見架高建築，減少屋內熱量傳到地基，故 D 亦符合。A 的溫帶大陸性範疇沒有指到原題所要的副極地特徵。"],
  "112-hg-37": ["出口競爭力可以從關稅和生產地著手","簽訂自由貿易協定可降低雙方交易障礙；赴當地設廠則可貼近市場並符合適用的在地生產規則。","所以選 C、D。調高臺灣的進口關稅無法直接減少臺灣商品進入東協的障礙。"],
  "112-hg-38": ["印度河中游偏乾可從季風強弱及氣壓帶推理","此區在夏季濕潤季風的邊緣或末端，水氣輸送較少；也在副熱帶高壓可能影響的乾燥地帶。","因此選 D、E。此地在內陸一些，但重點是季風水氣能否到達和下沉氣流，並非沿海涼流。"],
  "112-hg-39": ["每像素覆蓋地面越小，空間解析度越高","2 公尺網格比 20 公尺網格細，可辨認更小的地物，因此 B 正確。","固定同地面面積，兩方向的像素數各是 20÷2＝10 倍，總像素數是 100 倍。E 按單波段、相同比特數等條件理解。"],
  "112-hg-40": ["自然增加率與總人口是兩種不同的量","死亡率先下降，出生率仍高，兩者的差值先變大；後來出生率也下降，差值變小，對應圖甲。人口把每年的增加量累積起來，會先快速上升再趨緩，對應圖戊。","校方答案為 A、E。丙的死亡率單看下降方向也呈現轉型的一部分，甲和戊則直接呈現這兩個人口變化結果。"],
  "112-mb-1": ["平行直線的斜率一樣","原直線寫成 y＝x＋2，斜率是 1。過 (3,1) 的平行線可設為 y＝x＋b。","代入 1＝3＋b 得 b＝−2，整理成 x−y−2＝0。"],
  "112-mb-2": ["正切給對邊與鄰邊的比","把對邊、鄰邊分別設為 5、12，畢氏定理給斜邊 √(5²＋12²)＝13。","正弦是對邊÷斜邊，所以 sinθ＝5/13。"],
  "112-mb-3": ["先分成老師與學生，再將兩條路相加","師生比 1：7，因此隨機抽到老師為 1/8，學生為 7/8。老師使用 A 牌的機率是 80%，學生是 40%。","全部使用 A 牌的機率為 (1/8)×0.8＋(7/8)×0.4＝0.45，也就是 45%。"],
  "112-mb-4": ["函數的輸入改為 x−h，圖形向右移 h","原本在 x＝0 時 cos x＝1。新函數要讓 x−π/3＝0，改在 x＝π/3 時取同一個峰值。","峰值的 x 坐標增加 π/3，整張圖都往右移 π/3。"],
  "112-mb-5": ["因式定理：x＋2 是因式就有 f(−2)＝0","代入 x＝−2，兩個括號分別是 2＋2a 和 4a＋4。","乘積為 0 代表至少一個括號為零。兩個方程都解出 a＝−1。"],
  "112-mb-6": ["先找四個零點，再看乘積正負","零點依序是 −3、−2、1、2。每跨過一個零點，正負號切換。從 x＞2 的四因式全正開始，乘積在 (−3,−2) 與 (1,2) 為負。","題目是小於或等於零，四個端點也算。這兩段之間沒有其他整數，所以共有 4 個。"],
  "112-mb-7": ["即使抽兩張不放回，兩次的平均可相加","每個抽取位置都有同樣的金額分布。單張平均獎金為 (15×100＋4×500＋1×1000)÷20＝225 元。","兩張的總金額期望值是 225＋225＝450 元，不必假設兩次抽取相互獨立。"],
  "112-mb-8": ["觀察矩陣乘法中右上角的變化","把兩個形如第一列 (1,s)、第二列 (0,1) 的矩陣相乘，右上角會把各自的數值相加。","每多乘一次 A，右上角就加 2。A⁴ 的右上角是 2×4＝8。"],
  "112-mb-9": ["將內積看成一個向量在另一個方向上的分量","設正六邊形邊長為 1，把 AB 看成向右。A、B、C、D、E、F 順著六邊形前進，每轉一次方向差 60°。","從 A 出發，AB、AC、AD、AF 的向右分量依序是 1、1＋1/2、1＋1/2−1/2、−1/2。與 AB 的內積最大的是 AC。"],
  "112-mb-10": ["空間兩點距離用三個坐標差","B−A 的分量為 (−a,−2a,−a)，因此 AB²＝a²＋4a²＋a²＝6a²。","題給 AB＝3√2，平方得 6a²＝18。a＞0，所以 a＝√3。"],
  "112-mb-11": ["垂直向量的平方長度可直接相加","u 和 −v 也垂直，因此 |u−v|²＝|u|²＋|v|²。從坐標 (9,−8) 得左側為 81＋64＝145。","145＝144＋|v|²，因此 |v|²＝1，長度為 1。"],
  "112-mb-12": ["開口看二次項係數，交點看判別式","m²＋1 恆正，圖形必向上開口。判別式為 (m＋1)²−4(m²＋1)＝−3m²＋2m−3。","把它寫成 −3(m−1/3)²−8/3 可知永遠小於零，沒有 x 軸交點，整條圖在 x 軸上方，所以選 A。"],
  "112-mb-13": ["圓外的點離圓最近距離＝離圓心距離減半徑","把圓配方得 (x−3)²＋(y−4)²＝25，圓心 (3,4)、半徑 5。A 到圓心的距離為 √(5²＋12²)＝13。","沿圓心指向 A 的直線，最近的圓周點離 A 為 13−5＝8。"],
  "112-mb-14": ["把兩層根號合成兩數和的平方","(3＋√10)²＝9＋10＋6√10＝19＋6√10，所以原數等於 3＋√10。","3＜√10＜4，故原數介於 6 和 7，整數部分是 6。"],
  "112-mb-15": ["等比數列連續三項一組，每組之和也按比例變化","第 4～6 項各是第 1～3 項對應項的 r³ 倍，故 r³＝−40/5＝−8。","第 7～9 項之和為 (−40)×(−8)＝320。前三組相加 5−40＋320＝285。"],
  "112-mb-16": ["把相鄰限制改成一般的選位置問題","設充電站車廂編號為 i＜j＜k，且 j−i、k−j 都至少 2。改用 i、j−1、k−2 後，三個編號只需嚴格遞增。","新編號都在 1 到 10，任選三個後將後兩個分別加回 1、2，就對回唯一一種配置，所以有 C(10,3) 種。"],
  "112-mb-17": ["兩球同色的機率可換算成配對數","共有 C(9,2)＝36 對。兩黃占 1/6，所以黃球有 6 種配法，C(4,2)＝6。","兩藍占 1/12，所以藍球有 3 種配法，C(3,2)＝3。紅球剩 9−4−3＝2。"],
  "112-mb-18": ["科學記號的係數必在 1 到 10 之間","把 −12.34 寫成 −13＋0.66。原數是 10^−12.34＝10^0.66×10^−13。","10^0.66 約為 4.57，所以題目的指數 a＝−13。"],
  "112-mb-19": ["用指數把對數還原成原數","題給 a＝log2、b＝log3，因此 10ᵃ＝2、10ᵇ＝3。","10^(3b−a＋1)＝(10ᵇ)³×10÷10ᵃ＝27×10÷2＝135。"],
  "112-mb-20": ["換底後比較分子與分母","log₄9＝(2log3)/(2log2)，以 √2 為底的那項上下同除 2 也相同；1−log5＝log(10/5)＝log2。","B 的 log₂₀30＝(1＋log3)/(1＋log2)。因 log3＞log2＞0，分子分母同加 1 會使比值更接近 1，因此不同。"],
  "112-mb-21": ["等差數列的對稱三項，平均就是中間項","a₁＋a₂＋a₃＝51，因此 a₂＝17。a₆＝7 比 a₂ 少 10，四次變化共 −10，所以公差是 −2.5。","依次可算得 a₈＝2、a₉＝−0.5。從第 9 項開始出現負數。"],
  "112-mb-22": ["條件機率先縮小分母：只看恰三次正面的擲法","五次中挑出三次正面有 C(5,3)＝10 種等可能結果。若頭兩次都是正面，最後三次只剩一次正面。","符合的有 C(3,1)＝3 種，機率為 3/10。"],
  "112-mb-23": ["先算戴眼鏡的男女各占全校多少","每 100 人有 60 男、40 女。戴眼鏡的男生為 60×0.6＝36 人，女生為 40×0.4＝16 人。","已知戴眼鏡，只在 52 人中比較，男生占 36/52＝9/13。"],
  "112-mb-24": ["沿經線的弧長＝地球半徑×緯度差的弧度","弧長是 πr/3，除以 r 得角度 π/3，也就是 60°。","北極在北緯 90°，往南退 60° 是北緯 30°。經度不影響沿同一經線到北極的距離。"],
  "112-mb-25": ["將各選項轉成第一象限的正弦","A 是 sin1，B 是 sin(π/2−1)。因 1＞π/4，所以 π/2−1＜1，B 小於 A。","C、D 都等於 √3/2＝sin(π/3)。又 1＜π/3，正弦在這段遞增，所以 B 最小。"],
  "112-mb-26": ["矩陣乘上兩欄，等於各欄分開乘","左矩陣第一欄 (2,4) 是 (1,2) 的 2 倍，乘 A 後為 (10,12)。第二欄 (6,8) 是 (3,4) 的 2 倍，乘 A 後為 (14,16)。","把結果四個元素相加，得 10＋12＋14＋16＝52。"],
  "112-mb-27": ["先用 P 的兩個分量找 θ 的範圍","θ 以 360° 為一圈。P 在第二象限，sin(θ＋45°)＜0 使 135°＜θ＜315°。sin 2θ＞0 使 θ 落在 (0°,90°) 或 (180°,270°)。","交集為 (180°,270°)。此時 cosθ、sinθ 都是負值，Q 在第三象限。"],
  "112-mb-28": ["已知兩邊和夾角，用餘弦定理","所求 BC 是角 A 的對邊。BC²＝5²＋8²−2×5×8×cos60°。","cos60°＝1/2，得 BC²＝25＋64−40＝49，所以 BC＝7。"],
  "112-mb-29": ["資料筆數相同，可比較各對數字差平方和","三個數的變異數等於三個兩兩差平方的總和除以 9。刪掉 1、2、3、6 時，剩下的三個數各自算一遍。","四種差平方總和依序為 26、38、42、6。最大是 42，對應刪掉 3 後的 1、2、6。"],
  "112-mb-30": ["直圓柱截面可用切割方向判斷","水平切可得圓，沿軸方向貫穿可得長方形；角度適當的斜切可得橢圓。","拋物線是特定方式切圓錐所得，直圓柱不會切出拋物線，故選 D。"],
  "112-mb-31": ["全稱命題要驗條件或找反例","A 左右同加 c，大小不變。D 的左式減右式等於 [(a−b)²＋(b−c)²＋(c−a)²]/2，必不小於零。","B 若 c 為負不等號反向；C 沒限制 a、b 為非負；E 可取 a＝√2、b＝−√2，和與積是有理數，但 a、b 都不是。"],
  "112-mb-32": ["接續求斜率、截距和面積","改寫 y＝(3/4)x＋3，斜率 3/4、y 截距 3，令 y＝0 得 x 截距 −4。故 C 正確，直角三角形面積 4×3÷2＝6，所以 D 正確。","E 若成立，原點和 (−3,4) 的中點 (−1.5,2) 應在直線上。代入 3x−4y＋12 得 −0.5，不在線上。"],
  "112-mb-33": ["矩陣乘法通常不能交換順序","A 的 AB 是 3×3，BA 是 2×2，尺寸不同。D 的單位矩陣 I 與 A 可交換，故能用二項式展開。E 的 AB＝I 表示方陣 A、B 互為反方陣。","B 可用零矩陣反駁，能交換不代表可逆。C 展開為 A²−AB＋BA−B²，只有 AB＝BA 時中間項才會消去。"],
  "112-mb-34": ["用組合意義與二項式檢查 C(8,3)","A 直接是 C(8,3)；B 選 5 人等於決定哪 3 人不選；C 依第 8 人選或不選分為 C(7,2)＋C(7,3)。","E 按所選三人中的最大編號 3～8 分組，較小二人的選法合計 C(2,2)＋…＋C(7,2)。D 的 b⁵ 帶負號，係數是 −C(8,3)。"],
  "112-mb-35": ["從 10ˣ＝8 讀出 x＝log8＝3log2","A 的 100ˣ＝(10ˣ)²＝64。x≈3×0.3010＝0.903，所以 E 的 0.8＜x＜1 正確。","B 的 0.1ˣ＝1/8。C 中 0＜x＜1 時 √x＞x，故 10^√x＞8；D 把 3 倍誤寫成三次方。"],
  "112-mb-36": ["相關係數衡量線性關係，與正向尺度變換無關","A 的 r 介於 −1 和 1；D 的平移與乘正數不影響標準化偏差；E 兩組分別標準化後，相關係數也相同。","B 的迴歸斜率還受兩組標準差比值影響。C 若直線水平或垂直，其中一變量恆定，相關係數未定義，所以原敘述不一定成立。"],
  "112-mb-37": ["將 sinθ−cosθ 平方，可求兩者乘積","1/9＝1−2sinθcosθ，故乘積 4/9，B 正確。再用立方差，得 (1/3)(1＋4/9)＝13/27，D 正確。","差為正，所以 θ＞45°。和的平方是 1＋8/9＝17/9，和不是 5/3。若正切是 9/8，正弦差餘弦會是 1/√145，也不合。"],
  "112-mb-38": ["利用除式選擇好算的變數","B 全係數和為 f(1)＝0。C 用餘式定理，得 f(−1)＝16。D 令 t＝x＋1，則 f＝(t−2)⁴；除以 t² 時，只留下常數 16 與一次項 −32t，因為其餘項都能被 t² 整除。","將 t 換回 x＋1，得 D 的餘式 −32x−16。A 的 x² 係數是 6；E 的餘式由 R(1)＝0、R(−1)＝16，解得 −8x＋8。"],
  "112-mb-39": ["等差看相鄰差，等比看相鄰比","A 對等差各項加 3、乘 3，仍有固定公差。E 若平方後也是等差，平方序列的二次差分 2d² 必須為零，因此原公差 d＝0。","B 對等比加常數不一定保留公比。C、D 可取 aₙ＝n、bₙ＝2ⁿ，乘起來是 2、8、24……，差和比都不固定。"],
  "112-mb-40": ["先算三條邊向量，再做內積與投影","AB=(7,1)、AC=(2,6)、BC=(−5,5)，所以 A 正確，B 的 AB·BC 實為 −30。三個頂點的內角內積依次為 20、30、20，皆為正，故 C 也對。","AB 在 AC 上的投影是 (20/40)AC＝(1,3)，E 正確。高的平方是 |AB|²−|(1,3)|²＝50−10＝40，不是 30。"],
  "112-en-1": ["permission＝許可","No trespassing 是禁止擅入。私人場所只有獲得所有人許可才能進去，所以用 without the owner's permission。","passion 是熱情，network 是網路或人脈，evidence 是證據。"],
  "112-en-2": ["occasion＝場合","必須穿得正式、不能穿拖鞋，表示有一個正式場合。on this formal occasion 可理解為在這個場合。","portion 是一份，identity 是身分，appeal 是吸引力或呼籲。"],
  "112-en-3": ["noble＝高尚的","後面說她捐錢給慈善團體，without expecting anything in return 是不求回報，因此是在讚揚品格。","brutal 是殘酷的，jealous 是嫉妒的，curious 是好奇的。"],
  "112-en-4": ["sacred＝神聖的","後一句說牛在宗教活動中受到敬重，religious 是可直接定位的線索。","naive 是天真的，courageous 是勇敢的，anxious 是焦慮的。"],
  "112-en-5": ["be exposed to＝暴露在……之下","sunburned 是曬傷，scorching sun 是炙熱陽光。沒擦防曬又長時間曝曬，就容易曬傷。","infected 指受到感染，hesitate 指猶豫，reside 指居住。"],
  "112-en-6": ["nominate＝提名、推舉","學生獲推舉擔任學生會主席，後面說他會負責校慶。用被動式 was nominated。","常見寫法還有 nominate someone for a position 或 nominate someone as chairperson。其餘動詞無提名之意。"],
  "112-en-7": ["loneliness＝孤獨感","John 覺得自己在家像外人，和手足難以聊天，這些線索都指向孤單。","a sense of loneliness 是孤獨感；delight、achievement、direction 分別是喜悅、成就和方向。"],
  "112-en-8": ["furious＝非常生氣的","老師得知學生逃課又在校內抽菸，空格需要表示強烈的生氣。","plural 是複數的，ideal 是理想的，attractive 是吸引人的。"],
  "112-en-9": ["prevent A from V-ing＝阻止 A 做某事","學校採取措施的目的，是不讓可疑人士進入校園。題目已給 from entering，與 prevent 正好搭配。","mention 是提及，guide 是引導，harvest 是收割。"],
  "112-en-10": ["as a result of＝由於","航班取消是結果，大雪是原因，空格後面正好放名詞片語 the heavy snowstorm。","regardless of 表不論；according to 表根據；in addition to 表此外。"],
  "112-en-11": ["turn down＝拒絕","作家想專心寫小說，所以拒絕了許多演講邀請。turn down an invitation 是常見搭配。","step down 是卸任職務，calm down 是冷靜，bring down 可指降低或推翻。"],
  "112-en-12": ["prior to＝在……之前","後一句有 pre-discussion，表示主管希望在正式會議之前先談。","senior to、junior to 描述年資、職位或年齡；inferior to 表品質或地位較低。"],
  "112-en-13": ["jump to conclusions＝太快下結論","還沒有掌握全貌就作判斷，對應 D。題目裡加了 the，平時可記常用寫法 jump to conclusions。","bridge the gap 是縮小差距，strike a balance 是取得平衡，cost an arm and a leg 是價格非常昂貴。"],
  "112-en-14": ["end up with＝最後得到某個結果","Though 指原本以為結婚多年會維持婚姻，最後卻離婚。離婚是事情的結果。","come up with 是想出，keep track of 是持續追蹤，run out of 是用完。"],
  "112-en-15": ["get in the way of＝妨礙","工作量大、工時長會影響家庭生活。題目已在空格後放 of，因此填 get in the way。","come to power 是掌權，make a fortune 是賺大錢，catch a glimpse of 是瞥見。"],
  "112-en-16": ["become used to＋名詞＝逐漸習慣","太空人剛到新環境時，身體努力適應。try to 後接原形 become，再接 used to the new environment。","若用 accustom，常見寫法是 accustom oneself to…；trying to getting 的動詞形式不合。"],
  "112-en-17": ["情緒造成的狀態可用過去分詞","主詞 I 被恐懼嚇得動不了，故用 Paralyzed with horror，後面緊接說不出話。","可還原為 Because I was paralyzed with horror。Paralyzing 偏向描述主動使別人動不了。"],
  "112-en-18": ["數量詞＋of whom 補述前面的人","先行詞是朋友，選 all of whom，意思是「他們都」。該片語當 give 的主詞。","which 多指物；some of them 若直接開新句，前面只有逗號，缺少連接。"],
  "112-en-19": ["even though＝儘管","即使有哈佛法律學位，仍被律所拒絕，兩件事形成讓步。even though 後可接 he had… 的完整子句。","only if 是只有在……才；as though 是好像。even 單獨不能在這裡連接子句。"],
  "112-en-20": ["rather than＝而不做另一件事","兩個偏好比較是玩娃娃和運動。題目已寫 play sports（原形），可由 rather than 連接。","instead of、despite 若後接動作，通常要用 V-ing。rather than play sports 符合原題。"],
  "112-en-21": ["形容詞＋as＋主詞＋動詞＝儘管","Short as he was 可還原成 Although he was short。身高不占優勢，仍拿下最有價值球員，符合讓步語意。","C 的 he is 和題意中的過去敘述不搭，D 不能把 Short 用這種方式移到 although 前。"],
  "112-en-22": ["Such was＋名詞＋that 子句","fury 是憤怒。Such was his fury that… 表他氣憤到帶領抗議。把名詞放回一般語序相當於 His fury was such that…。","若用 so furious，倒裝須是 So furious was he that…，A 的語序不符。"],
  "112-en-23": ["對過去的肯定推測用 must have＋過去分詞","錢包已遺失，因此推測之前一定被偷。用 must have been stolen，been stolen 標明被動。","must be 指現在的情況；can’t have been 表示過去不可能發生。"],
  "112-en-24": ["whether A or not＝不管是否 A","Whether you believe it or not 是「不管你信不信」。後面陳述說話者親眼看見車禍。","no matter 須再接適當的疑問詞；whatever、however 不能直接和題目的 or not 構成這個固定用法。"],
  "112-en-25": ["despite the fact that 可接完整子句","it was raining 有主詞和動詞。句意是儘管下雨，仍要露營，因此用 Despite the fact that。","In spite of、In case of 後通常接名詞片語。For fear that 雖可接子句，但意思是唯恐。"],
  "112-en-26": ["主旨須同時容納生態旅遊的利與弊","文章先寫保育資金、教育與地方發展，接著談遊客過多造成棲地及經濟問題，最後要求平衡。","B 的 double-edged sword 是雙面刃，能涵蓋全文。A、D 都只談到一面。"],
  "112-en-27": ["反向題要分辨文中有無這個行動","文中說生態旅遊可以教育遊客，也能籌募保育資金，但沒有說遊客會自己撿垃圾。","C 把未提到的行動加進去，所以符合題目所問的 FALSE。"],
  "112-en-28": ["用代名詞前面的名詞定位","their 指 rare habitats（罕見的棲地），occupants 是居住者。前後文主要在談野生動植物。","所以在此是住在棲地中的動物，並非導遊或種植作物的人。"],
  "112-en-29": ["從內容判斷文章可能放在哪裡","文章介紹一種旅遊型態、對地方的利弊與規劃考量，適合要做旅遊規劃的讀者。","因此 C 的旅遊規劃論壇最貼切。時尚雜誌、航海日誌、政治社論都與主題較遠。"],
  "112-en-30": ["同時提出支持與批評，語氣較中立","作者一方面說有教育和保育資金的好處，一方面指出管理不佳會造成損害，最後要求平衡。","這是 neutral（中立），不等於 indifferent（漠不關心）。"],
  "112-en-31": ["address / deal with / cope with 都可接需處理的議題","address the issue 可指著手處理或提出討論；deal with 是處理；cope with 是應付。依標準答案選 A、B、E。","come about 是發生，通常沒有直接受詞；conduct 多用於進行研究、會議等。"],
  "112-en-32": ["因果方向要看主詞是原因或結果","司機粗心是原因，事故是結果。lead to、cause、result in、bring about 都可從原因接到結果，選 A、B、C、E。","stem from 要把結果當主詞，from 後才放起因，所以 D 的方向反了。"],
  "112-en-33": ["把某事視為優先事項：see / regard / view＋受詞＋as","A、B、C 都能表示把外表吸引人視為優先事項。公告更正後也接受 E 的 deem。","D 的 think 若要表達相近意思，常寫 think of A as B。使用 deem 時，也可直接寫 deem A a priority。"],
  "112-en-34": ["偶遇常用 come across / encounter / bump into","句意是昨天偶然遇到幼稚園朋友，變化太大而差點認不出。依更正答案選 A、B、E。","focus on 是專注；acquaint 表使認識，常見寫法是 acquaint oneself with…，不能直接用來說偶遇某人。"],
  "112-en-35": ["舉例表示包含，可用 including 或 inclusive of","後面的斜角巷和九又四分之三月臺是前文的虛構場景實例，所以 C、D 都可。","included 常放在被包含項目之後，例如 the platform included；excluded 表排除，意思相反。"],
  "112-en-36": ["be composed of / be made up of＝由……組成","陪審團是整體，各行各業的人是成員，主詞 the jury 可接 B、E 的被動形式。","consist of 用主動形式 The jury consists of…。make up for 則是彌補，和 make up 不同。"],
  "112-en-37": ["與當前事實相反的假設用 were 與 would","If I were the manager, I would recruit… 表現在假設自己是經理，A 正確。","省掉 if，可將 were 放到主詞前成 Were I the manager…，C 也正確。結果子句應維持 would。"],
  "112-en-38": ["『一……就……』有三種正確表法","A 用 No sooner had… than…；C 用 as soon as；D 用 the moment。三句都有鈴先響、學生立刻衝去的順序。","B 的 had rushed 表示到鈴響時已經衝去。E 的 since 是自從，沒有直接表達鈴聲一響就出發。"],
  "112-en-39": ["過去分詞片語可以交代主詞的狀態或原因","Fascinated with… 和 Enchanted with… 都指 John 被日出吸引，接著他為美景出發，選 A、E。","B 變成 John 主動吸引日出；although 和 despite 會把關係改為『儘管』。"],
  "112-en-40": ["to someone’s delight / joy＝令某人高興的是","C 的 To my parents’ delight 和 D 的 Much to my parents’ joy 都能帶出父母高興。meet expectations、live up to expectations 都是符合期待。","A 用讓步式且 meet 少了單數詞尾。E 的 fails to meet 表沒達到，語意相反。"],
  "112-ch-1": ["聲音相同要比對聲、韻、調","畛和診都讀 ㄓㄣˇ。「畛域」指範圍、界限，「診斷」是檢查後判斷病情等。","哺／餔是 ㄅㄨˇ／ㄅㄨ，泡／炮是 ㄆㄠˋ／ㄆㄠˊ，挽／腕是 ㄨㄢˇ／ㄨㄢˋ。"],
  "112-ch-2": ["用詞義檢查形近字","「素昧平生」是向來不認識，「蠅頭小利」指微小的利益，「面紅耳赤」可形容激動爭論，B 用字正確。","A 應為「變得索然無味」；C 應為「明辨是非、秉公執法、陟罰臧否」；D 應為「忍辱負重、睚眥必報」。"],
  "112-ch-3": ["同一個文言字先換成白話","C 的兩個「已」都等於「已經」：已經不常見到；回頭看，人已經不見了。","A 的「固」是堅決、本來；B 的「顧」是然而、拜訪；D 的「乃」是於是、竟然。"],
  "112-ch-4": ["成語的本意要和場景配合","「八面玲瓏」可形容處世圓融、能妥善應對各方，和 A 的語境相合。","「浮光掠影」指觀察不深入；「狐死首丘」指思念故鄉；「風行草偃」指在上者的作風影響下民。"],
  "112-ch-5": ["先找搭得上的動詞，再讀整句語氣","舌頭會「舔」，先留下 C、D。發光的小片子隨著背部抽動，看起來像在「抽搐」。","甕接住落下的水滴，水聲像在「彈唱」一家人的辛酸。三空依次為舔、彈唱、抽搐。"],
  "112-ch-6": ["排序先鎖定不能拆開的語句","甲說「我羨慕」，戊接著重複「羨慕」並補上原因；丙的「眼看」必須接丁的「要打斷」。","快被打斷時，蜘蛛在乙接過雨絲，最後自然接「繼續織了下去」。順序是甲戊丙丁乙。"],
  "112-ch-7": ["用學派的核心詞辨認","甲討論正名實，是名家。乙強調節用、儉約，是墨家。","丙用君臣、父子、夫婦、長幼的倫理規範說明秩序，對應儒家。"],
  "112-ch-8": ["曲可分散曲與劇曲","散曲可清唱，常見形式是小令與套數。劇曲用於演戲，除了曲文，也有科介、賓白等。","新樂府倡導者以白居易、元稹為代表；韓愈、柳宗元主要連到古文運動。宋詞豪放派可先記蘇軾、辛棄疾。"],
  "112-ch-9": ["書信用語取決於收信人的身分","袁宏道和袁中道是兄弟，書信末尾可用「頓首」表敬意，符合 C。","「膝前」常用於父母等長輩，「大啟」多用於平輩，「高足」是稱別人的優秀弟子，不能把蘇軾弟弟蘇轍如此稱呼。"],
  "112-ch-10": ["分開出現的詞句可兩兩配對理解","題句的清風配耳聽、明月配眼見。A 也可分讀成「不懂句讀就向老師求教，疑惑未解卻不向老師求教」。","前兩分句和後兩分句要逐一對應，這種交錯列出、分承理解的寫法和題例相同。"],
  "112-ch-11": ["假設句可補回「如果……就……」","C 可翻成「如果不能成功討賊復興，就請治我的罪」，先提出可能情形，再說後果。","B 是敘述松柏與雞鳴在環境中的表現，並沒有提出未定的假設再接處置。"],
  "112-ch-12": ["看說話者是否用謙辭自我降低","A 有「敢以煩執事」，C 有「竊慕、敢藉」，D 用「駑鈍」形容自己才能不足。","B 的「豎子」是責罵他人不值得商量，語氣強烈，不是自謙，符合題目找未使用者。"],
  "112-ch-13": ["悲秋重點在秋景是否引發傷感","A 的「堪題、偏宜」稱賞紅葉與黃菊，寫的是可欣賞的秋景。","B 有孤客，C 有獨自與沉思，D 明寫衰殘與愁，三種秋景都承載悲意。"],
  "112-ch-14": ["臨危仍能從容是雅量","有人起火時連鞋都來不及拿；王子敬卻神色如常，慢慢喚人扶他出去。","比較的是意外發生時的氣度和鎮定，不在於說話或發脾氣，因此歸入〈雅量〉。"],
  "112-ch-15": ["抓住唐代、有意創作兩個線索","文中以唐人的敘事宛轉、文辭華美，對照六朝粗略記載異事，並說唐人開始有意創作小說。","這是唐傳奇的典型發展，話本和章回小說主要是後來的類型。"],
  "112-ch-16": ["從上下文找共同為一家人的觀念","前文反覆說大家同為良民、同為鄉鄰，勸人別因籍貫不同而爭鬥。","「四海皆兄弟」能接上這層意思，也讓下句「況共處一隅」更有說服力。"],
  "112-ch-17": ["逐一辨認景物描寫對象","「涸為鹽場」直接點明鹽田。「甃」與磚瓦砌築有關，「長隄」寫鹽田的長堤，所以 C 符合。","「有亭翼然」形容亭子的樣子；「去來如龍」寫舟船往來；海水比成笠、白銀、琉璃，是寫海景。"],
  "112-ch-18": ["找樂器演奏的線索","B 的「歌吹」包含歌唱與吹奏，可以聽見樂器；「為風」形容聲音充滿遊人之間。","A 只說吟誦歌唱；C 說雖無絲竹管絃；D 說非絲非竹，都不能據此判定有樂器。"],
  "112-ch-19": ["從燈火與時節辨認節日","題詩同時寫城隍附近燈火、人群與春光，符合元宵賞燈。D 寫滿街燈燭，景象相同。","盂蘭是中元，桂香和分外明月指中秋，雄黃酒和五毒則指端午。"],
  "112-ch-20": ["從地標與時間詞定位場景","「島都」和「圓環」指向當時的臺北；詩寫臺北商販在熱鬧街巷做生意。","「徹宵」和燈光指夜間，並非正中午。「圓環」是地點，不能當甜甜圈。"],
  "112-ch-21": ["找文中有無『如何挑選』的說明","揉葉、加熱寫製程；酒色花香寫茶湯；輸出又受海外稱讚，寫到經濟價值。","雖提杯、瓶等盛茶容器，詩裡沒有交代怎樣挑選茶具，所以選 B。"],
  "112-ch-22": ["還原被擬人化的家電","打開有燈、關上有嗡嗡聲，裡面冷而能保存食物，線索一起指向冰箱。","D 的金屬外殼、內冷、防腐也指冰箱；A、B、C 分別可聯想火車、電燈、電風扇。"],
  "112-ch-23": ["寫作靈感可從親身見聞取得","詩人認為關起門硬想不如外出行路。旅途中的山水、風雨讓他真正有詩可寫。","C 強調從實地經驗學習，和詩中「征行自有詩」最接近。"],
  "112-ch-24": ["比對人物、原因和思念的對象","原詩寫女子替遠征的丈夫搗衣，盼戰事早結束。B 寫女子夢中想去遼西見遠方的人，連鳥聲都怕把夢驚醒。","兩首都借具體動作寫征戰下的思念。送朋友出使或思念兄弟雖也含離情，題材不同。"],
  "112-ch-25": ["乘舟象徵仕途或理想受挫後的退隱","孔子說道無法推行，便想乘筏遠去。A 先說人生不稱意，再說散髮乘扁舟，也有離開失意處境的意思。","B 憾無舟渡，偏向有心入仕卻缺機會；C 是宴飲，D 是漁人探路。"],
  "112-ch-26": ["把鏡頭從朝代興亡移到百姓身上","原曲指出政權興亡都讓人民受苦。D 提到戰火、將軍與「生民塗炭」，集中在民眾承受的代價。","A、B 偏重懷古，C 著重個人對功名富貴的感慨。"],
  "112-ch-27": ["詠蟬以蟬的處境映照詩人","「高難飽」既寫蟬在高樹上難以飽足，也比喻詩人自守清高而生活困窘、仕途不順。","下文的薄宦、舉家清繼續寫官小與生活清貧，讓人看出蟬是自況。"],
  "112-ch-28": ["托物言志：借物的選擇表達自己的原則","C 把菊花寫成寧可留在枝頭抱香而死，也不願被北風吹落。詩人借菊表明守節的志向。","B 用泰山接納土壤來說明廣納人才，主要在勸說，沒有用泰山自比。"],
  "112-ch-29": ["用誇張描寫笙簫與歌聲的盛況","「吹斷」與「歌遍徹」寫聲音悠長、遍及宮殿，烘托宴飲歌舞熱鬧，故選 B。","「休放燭光紅」是不要點紅燭，想踏月而行，D 說挑燈夜去正好相反。"],
  "112-ch-30": ["李煜前期詞常寫宮廷生活與人物情態","D 從晚妝、口中香氣與清歌描畫女子，與原詞的晨妝、宮廷歌舞氣氛相近。","A、B 寫故國與江山離別，歌詠亡國後的愁緒；C 的「閒夢遠」也是在夢中追想舊日南國。"],
  "113-hg-1": ["澳門—長崎是葡萄牙在東亞的重要航線","讀題先圈兩個港口。葡萄牙以澳門為據點，把中國絲貨等運往日本，再帶回白銀。","荷蘭後來在長崎也有貿易據點，但題目問的是早期主導澳門到長崎這條路線的國家，選 17 世紀初的葡萄牙。"],
  "113-hg-2": ["開業限制直接影響漢醫能否接續","日治總督府建立以西醫為主的醫療制度，限制漢醫可取得執業資格的途徑，後繼人員因此減少。","甲午戰後割臺是政權轉變的背景；直接使傳統漢醫沒落的是執業制度，故選 D。"],
  "113-hg-3": ["把江南糧運到首都叫漕運","京杭大運河連接南北，可把江南大量糧食運往北京等地，也是官民通行的路線。","絲路以跨區貿易為主。永濟渠是較早的運河段與水路系統，題目描述的是連接江南和京師的整體路線。"],
  "113-hg-4": ["琉球船民遇害與日本併吞琉球的時序","1871 年琉球船民漂到臺灣後遇害。日本在 1872 年將琉球改為琉球藩，1874 年又以遇害事件為由出兵臺灣。","1879 年廢藩置沖繩縣。題目把 1871–1874 年的相關事件合稱牡丹社事件，所以選 C。注意改藩早於 1874 年出兵。"],
  "113-hg-5": ["戰時動員與奉仕是日治後期的線索","女學生為士兵送行、做物資與服務工作，顯示戰爭時期把學校及學生編入動員。","皇民化運動屬日治後期。內地延長主義是較早的施政方向，不能只看到日式教育就選它。"],
  "113-hg-6": ["由神明的稱謂理解民間形象","『夫人、天妃、天后』借用傳統女性尊稱，民間『媽祖婆』又以親近的女性長輩稱呼神明。","考題選 A，重點是女神慈愛、庇護的形象。冊封屬敬稱，並不表示神明具有皇室血緣。"],
  "113-hg-7": ["用最早的移民背景辨認國家","題目從英格蘭殖民者起頭，後面又列愛爾蘭、義大利、德國等歐洲移民，和美國移民歷史相符。","墨西哥早期深受西班牙殖民，巴西深受葡萄牙殖民，海地的殖民史則與法國密切相關。"],
  "113-hg-8": ["東北的清政權與東南的鄭氏","來自中國東北的是滿洲建立的清政權；東南海商家族指鄭氏。1683 年清軍擊敗鄭氏，隔年設臺灣府。","1683、1684 年都落在 1601–1700 年，也就是 17 世紀。"],
  "113-hg-9": ["朝鮮在 19 世紀末廢除科舉","題目描述受鄰國壓力而改革，符合朝鮮 1894 年甲午改革，當時日本勢力介入，科舉亦被廢除。","中國正式廢科舉是在 1905 年，已是 20 世紀初。"],
  "113-hg-10": ["宋明理學強調綱常、忠貞與節義","題目說虞姬的形象由感情上的殉情，轉為對丈夫守貞、對君王盡忠的殉節。","這些倫理要求與宋明理學影響下的綱常觀念最吻合。"],
  "113-hg-11": ["文藝復興重新重視希臘、羅馬典籍","拉丁文是讀古羅馬詩人魏吉爾作品的工具。文法學校教授古典語文，反映人文主義下的古典教育。","吳爾芙是 20 世紀作家，題目問她筆下的英格蘭時代，不能拿作者年代答題。"],
  "113-hg-12": ["戰後改推國語，造成書寫語言轉換","作家先在日治臺灣接受日文教育，政權移交後，新政府推廣以華語為主的國語政策，使他需要改變使用的語言。","1930、40 年代的皇民化反而加強日語。題目問的是戰後 1940、50 年代。"],
  "113-hg-13": ["越南的殖民經驗與羅馬字","越南的國語字以拉丁字母書寫，早期由傳教士發展，法國殖民政府後來推廣使用。","題目問將這種文字宣稱為殖民功績的國家，選法國。1945 年的官方採用與早期文字發展是不同階段。"],
  "113-hg-14": ["大規模引進西方制度是明治維新的特徵","題幹列舉軍事、科學、教育制度一起改造，官員還到海外考察。明治政府希望以這些改革追上西方。","鎖國幕府限制對外往來，與題中的主動引進、出訪和通商很不同。"],
  "113-hg-15": ["冷戰的反共氛圍滲入大眾媒體","『莫斯科』『共產黨員』『進到你客廳』反映美國對蘇聯與共產主義影響的高度警惕。","好萊塢、電視、廣播成為審查或抵制對象，是冷戰期間美蘇對立下的文化現象。"],
  "113-hg-16": ["東亞季風區可先抓共同風向與季節","冬季多從大陸吹向海，夏季多從海洋吹向陸，三地的季風方向相近。三地夏天也都較炎熱。","降水量和全年溫差受海陸距離、地勢等影響差異較大，故選丙、丁。"],
  "113-hg-17": ["大比例尺能看清小範圍細節","大比例尺通常搭配較小的等高距，可呈現細節，甲正確。相同大小紙張，小比例尺涵蓋較廣，丁正確。","燈柱位置與鄉鎮內單一學校的受損調查都需要較詳細的圖，乙和丙不合。"],
  "113-hg-18": ["臺灣降雨多，缺水要看平均分配和可利用量","人口密、下雨集中在部分季節與地區、坡陡流急使水很快入海，都會讓可用水量受限。","題目問『並非』。河流坡降小、年降水量少不符合臺灣整體特徵，所以選丙、戊。"],
  "113-hg-19": ["什葉派主要分布區可先記伊朗","伊朗人口以什葉派穆斯林為主，所以選伊朗高原。","阿拉伯半島與土耳其等許多地區主要為遜尼派。題目問主要分布，並不要求區域只存在一個教派。"],
  "113-hg-20": ["擴散是都市活動延伸到周邊","通勤月票降低跨縣市交通成本，讓居住與通勤範圍由雙北伸展到基隆、桃園。","題幹強調服務及生活圈向外延伸，因此屬擴散。若強調周邊的人才與資源被吸往核心，才接近反吸。"],
  "113-hg-21": ["暖流使北歐部分沿岸冬季較暖","看圖，甲在斯堪地那維亞西側沿岸，己在冰島。兩地接近北大西洋暖流水域。","暖流把較暖的海水及熱量帶往高緯度，在冬季對鄰近海岸有增溫作用，故選洋流。"],
  "113-hg-22": ["迎風、背風會讓鄰近地方雨量差很多","甲在斯堪地那維亞山脈西側。潮濕西風吹上迎風坡，抬升冷卻後多降雨。","乙在較背風的一側，降水較少。這題同時需要地形向背與盛行風向，所以選甲、丁。"],
  "113-hg-23": ["伊比利半島西北部受大西洋調節","面向大西洋，潮濕海風帶來較充足降雨，且海水調節氣溫，使年溫差較小。","西北部較符合溫帶海洋性氣候。半島其他許多地區是地中海型，但不能以全半島一概而論。"],
  "113-hg-24": ["風向以風吹來的地方命名","從印度洋西側往東航向麻六甲，需要由西南吹向東北的風，故甲是西南季風。","冬季風向轉為東北季風，可供回程。『等待風向改變』也是季風會隨季節反轉的線索。"],
  "113-hg-25": ["地中海型氣候夏乾冬雨，坡地多見葡萄與橄欖","藍白建築、鄰近西亞與古文明指向希臘一帶，山地多，夏季少雨，不利某些糧食作物，甲正確。","坡地適種葡萄及橄欖，可加工為酒和油，丙正確。乙寫成夏雨，丁寫地勢平坦，皆與此區不合。"],
  "113-hg-26": ["用兩側水域辨認海峽","紅海南端通往亞丁灣的通道是曼達布海峽，位在葉門與非洲之角之間。","荷莫茲海峽通往波斯灣，直布羅陀海峽接地中海和大西洋。先認海峽所連接的水域，再選答案。"],
  "113-hg-27": ["吳哥窟最初是印度教寺廟","柬埔寨的吳哥窟最初為供奉印度教神祇而建，後來也成為佛教場所。","題目問其主要的建築、起源宗教文化，選印度教。今天柬埔寨的主要信仰不能直接套回建造年代。"],
  "113-hg-28": ["氣候圖的關鍵是高溫月降雨是否反而少","圖上 6–8 月的溫度高，月雨量偏低。11 月、12 月等較冷的月份降雨較多。","夏乾、冬雨是地中海型氣候的辨識重點。"],
  "113-hg-29": ["地形剖面用地名與南北方向定位","圖上由南到北，依序看到地中海、波河、阿爾卑斯山、多瑙河及斯堪地那維亞山脈。","跨過這些地形需要從義大利附近沿中歐北上，大致對應東經 10°。50°N 是東西向緯線。"],
  "113-hg-30": ["風帶隨季節移動，形成莽原的乾濕季","巴西高原夏季受間熱帶輻合區及上升氣流影響，較多對流降雨。","冬季受副熱帶高壓及下沉氣流影響，條件較乾，故依序是間熱帶輻合區、副熱帶高壓帶。"],
  "113-hg-31": ["把直接導火線與殖民治理背景分開","三案的日期都在日治時期，殖民當局的治理與山林開發損及原住民族權益。依官方答案選 B、C、D，D 可理解為樟腦等資源開發的背景。","三案並非都在阿美族居住區，也早於戰時徵調出兵。其中七腳川事件另有勞役、薪資等直接導火線。"],
  "113-hg-32": ["政府主導遷徙要有政策推動","明治政府開發北海道、清廷推動雲貴地區屯墾、日治政府推動原住民族移住，分別對應 A、C、D。","吳沙入蘭墾殖以民間活動為主；雲南回民外遷要從動亂與避難理解。"],
  "113-hg-33": ["看該時該地是否受日本控制","1920 年代朝鮮、1930 年代臺灣、1940 年代滿洲國均在日本支配範圍內，可能用神社傳播天皇信仰。","1860 年代菲律賓仍在西班牙殖民時期，1880 年代印度受英國統治，因此選 C、D、E。"],
  "113-hg-34": ["分辨跨洋勞動遷移與各地農業人口","南美甘蔗與北美棉花園的非洲人遭奴役；東南亞橡膠園有華工，夏威夷甘蔗園有朝鮮移民勞工，對應 A、B、D、E。","C 的阿利安人與題目所指時期的跨區種植園勞動移民不吻合。"],
  "113-hg-35": ["明清集中皇權的三種制度","明太祖廢宰相，清代以密摺讓皇帝直接掌握資訊，軍機處使重要政務可由皇帝集中決策，故選 B、C、E。","三省六部在隋唐發展成熟，編戶齊民遠早於明清，不合題目年代。"],
  "113-hg-36": ["孟加拉的水患由降雨、風暴與地形共同影響","西南季風帶來雨季的大量降雨，孟加拉灣熱帶氣旋也可能帶來暴雨與風暴潮。","低平三角洲排水慢、易淹水，三個因素對應 A、C、D。"],
  "113-hg-37": ["商品圈若小於商閾，客源可能不足","商品圈是可吸引顧客的範圍，商閾表示維持營運需達到的最低市場規模。逐家將商品圈與商閾相比。","B 為 40＜45，D 為 35＜40，E 為 25＜30。A、C 的實際範圍大於門檻。"],
  "113-hg-38": ["三角貿易分三段逐一比對","非洲到美洲運送被奴役者；歐洲到非洲運送軍火等商品；美洲到歐洲則輸出原料、貴金屬等。","所以 A、B、C 正確。紡織品多屬歐洲貨品，棉花、蔗糖是美洲出口的代表。"],
  "113-hg-39": ["把大西洋三角貿易沿順時針環流讀一圈","從非洲西岸向美洲可借北赤道洋流；由美洲往歐洲可沿墨西哥灣流及北大西洋暖流。","再經加那利洋流沿非洲西北岸南下，故選 B、C、D、E。本吉拉洋流在南大西洋。"],
  "113-hg-40": ["人口自然增加率＝出生率減死亡率","圖中甲是死亡率，乙是出生率。第二階段乙仍高，甲先明顯下降，於是人口快速增加，選 A。","第三階段甲已偏低，乙開始快速下降，主導人口成長減緩，選 E。丙是總人口，反映累積結果。"],
  "113-mb-1": ["巢狀根號可試著配成平方","14±8√3＝(2√2±√6)²，因為 8＋6＝14，且 2×2√2×√6＝8√3。","2√2＞√6，所以兩個根號分別化為 2√2＋√6、2√2−√6，相加是 4√2。"],
  "113-mb-2": ["取對數把指數 n 拉到前面","三邊取常用對數，得到 2≤n(log3−log2)≤log500。代入 log3−log2≈0.1761，log500＝3−log2≈2.699。","相除得約 11.36≤n≤15.33，因此 n 為 12、13、14、15，共 4 個。"],
  "113-mb-3": ["三點共線時斜率相同","前兩點的斜率是 (log3−log2)/(3−2)＝log(3/2)。從第一點到第三點，x 增加 4。","因此 log a＝log2＋4log(3/2)，a＝2(3/2)⁴＝81/8。"],
  "113-mb-4": ["同一個夾角連用兩次餘弦定理","在 △ABC 中，cos B＝(7²＋8²−5²)/(2×7×8)＝11/14。D 在 BC 上，所以 ∠ABD 也是角 B。","在 △ABD 中，AD²＝7²＋6²−2×7×6×11/14＝19，所以 AD＝√19。"],
  "113-mb-5": ["對角矩陣的平方只需把對角元素平方","A² 的對角為 a²、b²。若等於單位矩陣，兩個位置都必須等於 1。","a、b 都各可取 1 或 −1，所以有 2×2＝4 個矩陣。"],
  "113-mb-6": ["平行平面共用法向量","本題官方送分。依代數上的帶正負截距解讀，設 E 為 2x＋y−3z＝d；三個截距是 d/2、d、−d/3，相加為 14 得 d＝12。","兩平面的距離是 |15−12|/√(2²＋1²＋(−3)²)＝3/√14。解題練習可用此法，作答仍依公告一律給分。"],
  "113-mb-7": ["完全平方數的每個質因數次方都是偶數","1、4、9 本身為平方數；2 與 8 的奇次質因數同為 2，把它們配其中一個平方數有三組；三個平方數全取另有一組。","剩下能讓奇次質因數成對的是 2、3、6 與 3、6、8。5、7 各找不到配對，總共 6 組。"],
  "113-mb-8": ["用 AB 的兩列等式各自解一欄","第一欄滿足 a＋2c＝2、3a＋4c＝0，解得 a＝−4、c＝3。第二欄滿足 b＋2d＝0、3b＋4d＝2，解得 b＝2、d＝−1。","四數相加 −4＋3＋2−1＝0。"],
  "113-mb-9": ["係數的範圍會等比例放大平行四邊形","AB、AC 張成的平行四邊形面積是 △ABC 的兩倍，即 8。r 的區間長 3，s 的區間長 2。","P 的區域由兩方向分別放大 3 與 2，面積 8×3×2＝48。"],
  "113-mb-10": ["總和為偶數時，奇數個數必為偶數","1 至 15 有 7 個偶數、8 個奇數。全選偶數有 C(7,3)＝35 種。","選兩個奇數和一個偶數有 C(8,2)×7＝196 種，共 231。"],
  "113-mb-11": ["恆正表示整條拋物線都在 x 軸上方","a＝−1 開口向下；a＝0 時代 x＝0 得 −1；a＝1 時式子為 (x＋1)²，在 x＝−1 等於零。","a＝2 時，2x²＋3x＋3＝2(x＋3/4)²＋15/8，對所有實數都大於零。"],
  "113-mb-12": ["抽三球不放回且只問顏色組合","總共 9 球取 3 球，有 C(9,3)＝84 種等可能組合。三球異色必須白、紅、黃各一。","合格組合為 2×4×3＝24 種，機率 24/84＝2/7。"],
  "113-mb-13": ["把兩條邊向量分解成沿摺線和垂直摺線","在 B 點，BA、BC 都與 BD 夾 45°。若邊長取 1，兩者沿 BD 的分量長都為 1/√2。","垂直 BD 的兩個分量也各長 1/√2，夾角依題意取 60°。內積為 1/2＋(1/2)cos60°＝3/4，即 cosθ。"],
  "113-mb-14": ["驗出陽性的人包含真陽性與偽陽性","以 1000 人想像，60 人患病，約 60×0.9＝54 人驗出陽性；940 人未患病，約 940×0.05＝47 人也驗出陽性。","在陽性的 101 人中，患病者是 54 人，所以條件機率為 54/101。"],
  "113-mb-15": ["切線垂直於通過切點的半徑","圓心 (−2,1) 到切點 (1,0) 的斜率為 −1/3，切線斜率為 3。過切點得到 y＝3x−3。","x 截距為 1，y 截距為 −3，三角形兩直角邊長 1、3，面積為 3/2。"],
  "113-mb-16": ["把限制式與所求式的分量配成相同順序","本題官方送分。令 w＝2z，則 x²＋y²＋w²＝6，而所求為 (2,−1,1)·(x,y,w)−3。","兩個向量長都為 √6，因此內積最多為 6；取 (x,y,w)＝(2,−1,1) 可達到，最大值 3。"],
  "113-mb-17": ["找分母與分子的和固定的一組","數列按分子＋分母＝2、3、4……分組，每組分子依序從 1 開始。7/13 在總和 20 的組，是該組第 7 項。","前面組別有 1＋2＋…＋18＝171 項，加 7 得第 178 項。"],
  "113-mb-18": ["統一寫成第一象限的正弦才能比大小","cos(π/5)＝sin(3π/10)；sin 2＝sin(π−2)。π/6、3π/10、1、π−2 約為 0.524、0.942、1、1.142。","這些角都在 0 到 π/2，正弦隨角度增大，因此 sin 2 最大。"],
  "113-mb-19": ["用二項式定理辨認展開式","各項是 C(20,k)×3ᵏ，因此總和為 (1＋3)²⁰＝2⁴⁰。","log(2⁴⁰)≈40×0.3010＝12.04，在 12 和 13 之間，所以數落在 10¹² 到 10¹³ 之間，共 13 位。"],
  "113-mb-20": ["根號表示與固定點的空間距離","本題官方送分。根號內為點 (x,y,z) 與 (−5,1,−3) 各坐標的差平方和。最小值是固定點到平面的垂直距離。","將固定點代進 x−2y＋2z−5 得 −18，再除以法向量長 √(1＋4＋4)＝3，距離為 6。"],
  "113-mb-21": ["等差數列對稱的兩項平均是中間項","a₂＋a₁₀＝2a₆，b₂＋b₁₀＝2b₆。前 11 項也以第 6 項為中間，所以 S₁₁＝11a₆、T₁₁＝11b₆。","所求比為 S₁₁/T₁₁＝(7×11＋3)/(2×11＋5)＝80/27。"],
  "113-mb-22": ["把兩個向量寫成坐標後展開內積","取 P=(x,y)，PA·PB＝x²＋y²−4√3x−4y＝4−(4√3,4)·(x,y)。","固定向量長 8，OP 長 2。兩者反向可讓內積最小為 −16，故所求最大為 4＋16＝20。"],
  "113-mb-23": ["兩種倍增速度相除，就得到每小時的比值","初始數量相同，過 t 小時後比值 B/A＝4ᵗ/2ᵗ＝2ᵗ。","512＝2⁹，因此 t＝9 小時。"],
  "113-mb-24": ["比較函數值找最大值","本題官方送分。依題給函數，f(2)＝64，且 64−f(t)＝(t−2)²(t＋4)。","t≥0 時右側非負，並且只有 t＝2 時等於零，因此依式計算是第 2 日達最大。"],
  "113-mb-25": ["圓柱的平面截面由切割方向決定","水平切可得圓，通過中軸的直切可得長方形，適當斜切可得橢圓。通過圓柱中心時，兩半可等體積。","平面切單一圓柱側面沒有雙曲線的兩支形狀，因此選 C。"],
  "113-mb-26": ["將三條彼此垂直的稜當作三個坐標軸","以 D 為原點取 A=(2,0,0)、B=(0,4,0)、C=(0,0,4)。AD 與 BD 垂直，CD 又垂直底面。","P=(1,0,0)，Q=(0,2,2)。PQ＝√(1²＋2²＋2²)＝3。"],
  "113-mb-27": ["三人中恰有二人命中，分誰沒中","丙沒中是 0.6×0.7×0.5＝0.21；乙沒中是 0.6×0.3×0.5＝0.09。","甲沒中是 0.4×0.7×0.5＝0.14，三種互斥結果相加為 0.44。"],
  "113-mb-28": ["立方差可用 x²＋y² 和 xy","依題 x²＋y²＝12，xy＝√(36−20)＝4。x＞y，所以 x−y＝√(12−8)＝2。","x³−y³＝(x−y)(x²＋xy＋y²)＝2(12＋4)＝32。"],
  "113-mb-29": ["用象限決定三角函數的符號","tan 140°＝−tan 40°，sin 230°＝−sin 50°＝−cos 40°。","因 40° 在第一象限，cos 40°＝1/√(1＋tan²40°)＝1/√(1＋k²)，再補上負號。"],
  "113-mb-30": ["緯圈半徑＝地球半徑×cos 緯度","北緯 30° 的緯圈半徑為 6370×cos30°＝3185√3 公里。","題目問直徑，要再乘 2，得到 6370√3 公里。"],
  "113-mb-31": ["兩條半徑方向相差 90°","極坐標給 OA＝2、OB＝4，角度相差 220°−130°＝90°，所以 △AOB 以 O 為直角。","AB＝√(2²＋4²)＝2√5。直角三角形斜邊中點距三頂點等遠，OC＝AB/2＝√5。"],
  "113-mb-32": ["用對稱中心找配對零點和正負","中心 (2,0) 是零點，f(0)＝0 的對稱零點在 x＝4。因此 f(x)＝a·x(x−2)(x−4)。f(−3)＞0 迫使 a＜0。","逐一看三因式的符號，f(−2)、f(3) 為正，f(4)＝0，其餘為負，所以只有 2 個。"],
  "113-mb-33": ["把圓心平移到原點再逐欄數格點","令 u＝x−3、v＝y＋4，條件變成 u²＋v²≤5 與 u＋v≤1。u 只可能為 −2、−1、0、1、2。","五欄可取的 v 分別為 −1～1、−2～2、−2～1、−2～0、−1。格點數 3＋5＋4＋3＋1＝16。"],
  "113-mb-34": ["河邊那一側不用繩，只有三邊計入","設垂直河岸的一邊長 x，另一種邊長 20−2x，面積 S＝x(20−2x)。","配成 S＝50−2(x−5)²，x＝5 時取得最大面積 50。"],
  "113-mb-35": ["兩歪斜線的距離沿共同垂線量","本題官方送分。設正立方體邊長 s。正四面體的邊是立方體面對角線，所以 s√2＝2，s＝√2。","依坐標圖，AB、CD 的中點分別是 (s/2,0,s/2)、(s/2,s,s/2)，連線沿 y 軸，垂直兩邊。所求為 s＝√2，原選項無此值。"],
  "113-mb-36": ["迴歸直線通過兩科平均組成的點","斜率為 rσᵧ/σₓ＝0.8×5/10＝0.4。國文從平均 65 增至 70，多 5 分。","預測英文從平均 70 增加 0.4×5＝2，得到 72 分。"],
  "113-mb-37": ["把已知兩個向量相加或相減來找矩陣的兩欄","兩式相加得 A(2,0)=(0,2)，第二式減第一式得 A(0,2)=(−2,0)。因此 A(e₁)=(0,1)，A(e₂)=(−1,0)。","A 使向量逆時針轉 90°，A³ 等於逆時針轉 270°，矩陣第一列 (0,1)、第二列 (−1,0)。"],
  "113-mb-38": ["把長方體的相鄰表面展開，再在平面走直線","從對角頂點 A 到 G，有三種本質不同的長方形寬長，分別是 (4＋3,2)、(4＋2,3)、(3＋2,4)。","對角線長為 √53、√45、√41，最短是 √41。"],
  "113-mb-39": ["正三角形的外接圓半徑可求邊長","A 在圓上且 OA＝√(3²＋4²)＝5，所以外接圓半徑為 5。正弦定理給邊長＝2×5×sin60°＝5√3。","面積＝(√3/4)(5√3)²＝75√3/4。"],
  "113-mb-40": ["相關係數比較偏差是否同向變動","逐欄算國文偏差 x−64、英文偏差 y−70。偏差乘積相加是 216，兩組偏差平方和分別是 144、576。","r＝216/√(144×576)＝216/(12×24)＝0.75。"],
  "113-en-1": ["aspect＝方面、面向","句子說，在全球化的世界，有效溝通需要了解一個社會的文化面向。cultural aspect 是常見搭配。","adoption 是採用或收養，landmark 是地標，sample 是樣本。"],
  "113-en-2": ["reflect＝反映","建築細節讓人看出古文明的文化傳承和價值觀，所以用 reflect。","afford 是負擔得起，insert 是插入，shelter 是庇護。"],
  "113-en-3": ["financial difficulties＝財務困難","醫療支出突然增加或失業，直接影響家裡的金錢收支，因此選 financial。","flexible 是有彈性的，distinct 是不同的，doubtful 是可疑或不確定的。"],
  "113-en-4": ["social status＝社會地位","職業、教育、家庭背景都可能影響人在社會中的地位。把 social 和 status 一起記。","quantity 是數量，prosperity 是繁榮，evidence 是證據。"],
  "113-en-5": ["distinguish between A and B＝分辨 A 與 B","A 是可靠資訊，B 是假新聞。看到 between… and…，可先想是否在比較兩者。","violate 是違反，rescue 是救援，project 可指投射或預測。"],
  "113-en-6": ["proper＝適當的","運動表現和健康需要合適的飲食。maintain a proper diet 是維持適當飲食。","apparent 是明顯的，literary 是文學的，immediate 是立即的。"],
  "113-en-7": ["excessive＝過度的","都市人口持續增加，住房和公共建設面臨過大的需求。excessive demands 指需求超出一般可負荷的程度。","innovative 是創新的，relative 是相對的，liberal 可指自由開放的。"],
  "113-en-8": ["symbol of＝……的象徵","畫作用看得見的畫面呈現藝術家內心看不見的掙扎，因此是 a symbol of his or her struggle。","sacrifice 是犧牲，column 是柱或專欄，agriculture 是農業。"],
  "113-en-9": ["religious＝宗教的","believers 是信徒，blessings 是祝福或庇佑，兩個線索指向宗教儀式。","efficient 是有效率的，brutal 是殘酷的，innocent 是無辜的。"],
  "113-en-10": ["suffer from＝受……所苦","後文說爸爸必須用止痛藥，因此他受嚴重背痛所苦。單數主詞 my dad 用 suffers。","attend to 是照料或處理，put out 可指撲滅，take over 是接管。"],
  "113-en-11": ["along with＝和……一起","老師與校長都認為學生應被停學。逗號中的 along with the school principal 補充另一個人。","above all 是最重要的是，on the whole 是整體而言，on average 是平均來說。"],
  "113-en-12": ["be faced with＝面臨","Gary 同時錄取兩所名校，得選其中一所，因而面臨難作的決定。a dilemma 是兩難。","envious of 是羨慕，suspicious of 是懷疑，charged with 可指被控告。"],
  "113-en-13": ["pose a threat to＝對……構成威脅","句子描述碳排放大量增加對環境的影響，後文又提到氣候變遷，因此搭配 poses a threat to。","pay attention to 是留意，catch a glimpse of 是瞥見，take a stand 是表明立場。"],
  "113-en-14": ["be addicted to＝對……上癮","每天花好幾小時滑社群媒體，描寫的是難以停止的使用習慣。addicted to 後可接 smartphones 或使用手機的動作。","associated with 僅表示有關，destined for 是注定前往，startled by 是被……嚇到。"],
  "113-en-15": ["be composed of＝由……組成","氮、氧及二氧化碳是大氣的組成成分，因此用 is composed of。","consist of 也有同義，但直接寫 The atmosphere consists of…，不能加 is 成為 is consisted of。"],
  "113-en-16": ["even if＝即使","空格後 you keep asking 是完整子句。句意是即使你整天要求，我仍不讓你獨自夜間外出。","in spite of 後接名詞片語；since 表原因；only if 表必要條件。"],
  "113-en-17": ["require that ＋ 主詞 ＋ 原形動詞","require 在這裡表示要求，因此 that 子句用原形。作業是『被』繳交，所以用 be submitted。","只寫 submitted 會缺少被動助動詞；submit 則變成作業主動繳交。"],
  "113-en-18": ["English-speaking＝說英語的","空格要用一個形容詞修飾 country。用 English-speaking country 表示以英語溝通的國家。","spoken English 指的是英語口語，本身是名詞片語。"],
  "113-en-19": ["whichever＋名詞＝任何一個你選的……","題目允許從圖書館選一本偏好的書，所以 whichever book you prefer 可當 choose 的受詞。","whether 是是否，wherever 是無論何處，no matter 須再接疑問詞。"],
  "113-en-20": ["with＋受詞＋形容詞表示當時的狀態","門在離開時一直是開著的，後句小偷容易進入正好印證。the door open 裡的 open 是形容詞。","opening 或 being opened 著重正在打開的動作，與遺留的狀態不同。"],
  "113-en-21": ["Having＋過去分詞表示先完成的經歷","兩人先一起經歷起伏，現在才成為理想伴侶。因此用 Having experienced，時間順序是過去經驗在前。","experienced 在這裡需要主動、能帶受詞 many ups and downs。"],
  "113-en-22": ["were to＋原形可假設未來很難發生的情況","山海消失後才答應結婚，是說話者明知幾乎不會發生的假設。if 子句用 were to disappear。","主句 would marry 與此假設搭配。had disappeared 通常是假設過去已發生的事。"],
  "113-en-23": ["is estimated to be＋過去分詞","七成的地表被水覆蓋，語意是被動：is covered by water。估計句型用 is estimated to…，合起來成 to be covered。","另一種寫法是 It is estimated that…，若保留地表當主詞，就用題目的不定詞寫法。"],
  "113-en-24": ["Only when 放句首，主要子句會倒裝","太陽落下以後夜行動物才出現。Only when the sun sets 放句首，後面才有 do the animals emerge 的倒裝。","when 子句仍保持 the sun sets 的順序。If only 比較常用來表達但願。"],
  "113-en-25": ["疑問詞＋to＋原形＝簡化的間接問句","Jessie 想知道假期要去哪，所以是 wondered where to go。around the corner 表示節日快到了。","when to do 缺受詞；題目也沒提供可供選擇的遊戲讓 which to play 取得意義。"],
  "113-en-26": ["主旨需涵蓋音樂與戰時情緒兩條線","文章先說音樂普及，接著說政府用它激發愛國心、爭取支持，最後擴展到政治運動。","B 涵蓋主要內容。文章沒有說音樂曲風的變化引起社會革命。"],
  "113-en-27": ["細節題回到政府使用音樂的段落","第二段直接列出 pride、patriotism，政府用音樂鼓動民眾，詞譜圖像也增加宣傳效果。","D 正好對應這兩個字；作曲家其實有合作寫歌，與 B 相反。"],
  "113-en-28": ["把好幾種情緒反應合成合理推論","文中說戰時音樂能讓人興奮、願意幫忙，也可能讓不支持戰爭的人感到內疚。","由此可推知音樂能影響甚至操弄情緒。作者描述效果，沒有判斷它不道德。"],
  "113-en-29": ["saturate 的核心是浸透、遍及","後面說 reached into all of its corners，換成白話就是流行音樂深入社會每個角落。","四個選項中 A influence 最接近『廣泛影響』，實際字義比單純的 influence 更強。"],
  "113-en-30": ["用文章明示主題回答","一戰時，美國用音樂鼓舞民眾並爭取支持，第二段直接用 patriotism 表示愛國情感。","題目問符合文章敘述的歌詞主題，所以選 Patriotism。"],
  "113-en-31": ["give rise to 與 result in 都表示導致","酒駕是原因，致命交通事故是結果。C、E 都能接結果。","arise from 的方向相反，主詞是結果，from 後面放原因。"],
  "113-en-32": ["conduct a project / carry out a project＝執行計畫","spend time doing something 表花時間做某事。conducting 和 carrying out 都能接科學計畫。","surrender to 是向……投降，impose on 是強加於，語意不合。"],
  "113-en-33": ["紀念或致敬的三種片語","in memory of、in honor of、in remembrance of 都可表示為了紀念或致敬。題句描述泰姬瑪哈陵的建造用意。","in need of 表需要；in search of 表尋找。"],
  "113-en-34": ["be worth V-ing / be worthy of being V-ed","worth watching 是值得看；worthy of being watched 也可表示值得被觀看。兩個句型對應 B、D。","worthless 是沒有價值；單獨 worth 缺後面內容。"],
  "113-en-35": ["遵守法律的三種表達","comply with the law、abide by the law、obey the law 都是守法。","obey 直接接受詞，comply、abide 在這個用法分別要接 with、by。"],
  "113-en-36": ["the＋比較級，the＋比較級","B、C、D 都有前後兩個比較結構：越追求名聲與權力，就越不快樂或越不滿足。","unhappier、less content、less happy 都能表達快樂減少。A 和 E 的前半句沒有正確的比較句型。"],
  "113-en-37": ["despite＋名詞；although＋完整子句","A 用 despite the bad weather；E 用 although the weather is bad。兩句都接活動仍照常舉行。","B 的 having bad weather 容易錯接到主詞 Scout activities；D 的 If only 表但願，並非讓步。"],
  "113-en-38": ["用名詞、形容詞或動名詞表達無法預測","B 用 It’s uncertain whether… 表是否成功仍不確定；D 用 remains unpredictable 說成功與否不可預測。","E 的 There is no predicting whether… 也是慣用句。A 的 There can’t be predicted 缺合適的主詞。"],
  "113-en-39": ["與過去事實相反的假設","A 用 If it had not been for… 搭配 might have made…，表示過去實際有這項建議。","C 用 Without your advice 省去 if 子句，主句仍用 might have made 回推過去結果。"],
  "113-en-40": ["區分預防目的和表達擔心的片語","A 的 to avoid 與 E 的 for fear of 表明目的是避免或擔心意外，for fear of 後可接名詞片語。","原卷也接受 C 的 in case of。它常譯為『以防／若發生……』，自己寫明確的預防目的時用 to avoid 最清楚。D 的 for fear that 後須有完整子句。"],
  "113-ch-1": ["聲、韻、調都要相同","卓與踔都讀 ㄓㄨㄛˊ；「踔厲風發」形容精神振奮、意氣昂揚。","垣／坦是 ㄩㄢˊ／ㄊㄢˇ，滲／摻是 ㄕㄣˋ／ㄔㄢ，陟／涉是 ㄓˋ／ㄕㄜˋ。"],
  "113-ch-2": ["從詞義還原正字","「如臨深淵，如履薄冰」是好像面對深水、踩在薄冰上，形容小心謹慎。「臨」是面對，「履」是踩踏。","A 是「風雨如晦」，B 是「以蠡測海」，D 是「不務正業」。"],
  "113-ch-3": ["把同一個字換成白話比較","D 的「固」都可換成「本來」：本來就難以看透；生在我之前，本來就比我先懂得道理。","A 的因分別有趁著、因為之意；B 的誠是誠心、實在；C 的為是替、向。"],
  "113-ch-4": ["層遞要看同一件事如何逐步加深","梅子由七成落到三成，女子的話也從等待好日子變成盼望現在就來，時間更急迫。","A 的數量變少、語氣變急，兩條線一起推進。B 將泰山、河海與王者並列類比。"],
  "113-ch-5": ["從結句捕捉對功名的態度","「古今將相」最後只剩荒墳，意思是地位再高也留不住。A 說富貴無憑，追逐它又耽誤時光，態度相近。","B、D 有借機上進或施展抱負的意思；C 寫躬耕生活，沒有直接評論功名。"],
  "113-ch-6": ["成語中相同的字也可能有不同意思","「筆酣墨飽」形容筆墨充盈、筆力酣暢；「鸞翔鳳翥」用鳥振翅高飛譬喻書法筆勢飛動。兩者都可形容書法。","滄海一粟是渺小；日就月將是日積月累而有進步；箕踞是伸腿而坐，並非正襟危坐。"],
  "113-ch-7": ["「所以」可表示原因或方法","題句問這酒為何變酸而賣不掉。「先漢所以興隆」也問為何興盛，原因是親近賢臣、遠離小人。","A、C 偏向「用來……的方式或憑藉」，試著改成「之所以」，只有 B 符合題句。"],
  "113-ch-8": ["《詩經》作者多不可考","《詩經》收有不同時代與場合的歌詩，包含民間歌謠、朝廷樂歌、宗廟祭歌，作者身分不全相同。","因此 B 的「皆為文人士大夫，故多可考」不正確。漢代四家詩中完整流傳至今的是毛詩。"],
  "113-ch-9": ["被動句的「於」可翻成「被」","「孟德困於周郎」說曹操受到周瑜圍困，動作施加者是周瑜，符合被動。「孟德」是曹操的字。","「於天地」「於晉」「於秦」在其他選項表示所在、對象或來源。"],
  "113-ch-10": ["記體散文的主旨要看結尾","〈醉翁亭記〉從山水、遊人與宴飲，寫到太守以百姓的快樂為快樂，重心是與民同樂。","〈桃花源記〉隨漁人遭遇敘寫；〈岳陽樓記〉從景物轉入憂樂志趣，不屬滕子京的傳記。"],
  "113-ch-11": ["輓詞要配合亡者身分","「桃李」比喻老師教出的學生，「興悲」寫學生哀悼師長，因此「桃李興悲」適合史可法敬輓恩師。","「貨殖」與商業有關。「坤儀」「蘭摧蕙折」傳統上多見於女輓。"],
  "113-ch-12": ["先找重複句型，再找承接的比喻","首句談自暴，乙以相同句型接上自棄。接著甲、丙依次解釋什麼是自暴和自棄。","最後丁以仁為安宅、以義為正路，末句才有可承接的「安宅」「正路」。順序是乙甲丙丁。"],
  "113-ch-13": ["空格要延續是非顛倒的例子","前文把輕薄的蟬翼視為重、把千鈞視為輕；後文又讓讒人得勢、賢士埋沒。","黃鐘是珍貴的樂鐘，瓦釜是粗陋的陶鍋。丟棄黃鐘卻讓瓦鍋作響，是同一種價值顛倒。"],
  "113-ch-14": ["道家強調順自然、功成不居","「生而不有，為而不恃，功成而弗居」是《老子》式的觀點：有所成就仍不占有、不自恃。","C 的捕魚段出自《孟子》，D 是《論語》教人孝悌仁愛，也屬儒家。"],
  "113-ch-15": ["人物動機要回到文中證據","范增勸項羽對付劉邦，重點是他看見劉邦與昔日不同，認為劉邦志向大、日後會威脅項羽。","A 所說的對范增無禮和安排內奸不是范增起殺機的原文明示原因。其餘三項都合乎該文的勸說或行動。"],
  "113-ch-16": ["菊花意象是秋天與金黃","D 的九月、百花凋落後盛開、滿城如穿黃金甲，是黃巢詠菊的線索。","A、B 是荷花與水面景象；C 的疏影和暗香指梅花。"],
  "113-ch-17": ["分辨作者是否認同孟嘗君得士","甲直接把孟嘗君為相數十年平安歸功於馮諼的計謀，故 D 正確。","乙的「豈足以言得士」明顯是質疑。王安石說「若真得一士，應能制秦」是假設，不是在說已經做到。"],
  "113-ch-18": ["用文類和故事內容雙重判斷","〈虬髯客傳〉是唐傳奇，〈勞山道士〉是《聊齋誌異》的故事，兩篇都是文言短篇小說。","〈漁父〉不屬律賦，〈勸和論〉是勸民和解的文章；〈散戲〉寫戲班，科舉悲劇屬〈孔乙己〉。"],
  "113-ch-19": ["由近到遠要看景物尺度擴張","先是岸邊細草、近旁船桅，再看廣闊平野、天上星月與大江。視線從身邊移到遠方，選 B。","A 從千山萬徑縮向一艘孤舟，方向相反。"],
  "113-ch-20": ["按時代辨認晚唐詞與宋代流派","晚唐、五代的代表詞作多走柔婉細麗一路，例如花間詞的風格。豪放詞風在宋代才由蘇軾等人拓展。","所以誤將晚唐寫成已有『豪放派』大量創作的丙項不正確。"],
  "113-ch-21": ["鄉愁題要找想念的對象","詩用相隔三十年的兩次望月，讓滿月聯想到滿杯鄉色酒和滿懷鄉愁。","C 的征人因蘆管聲一起遠望家鄉，同樣把思鄉連到一個具體景象。"],
  "113-ch-22": ["超然物外要看觀察方式是否轉變","D 將水月與天地分別從『變』和『不變』兩面看，從生命有限轉向物我無盡，表現放寬眼界後的豁達。","A 主要寫月影可愛；B 寫林木；C 甚至寫賞月者希望被人看見。"],
  "113-ch-23": ["用人生轉折辨認魯迅","魯迅曾赴日學醫，後轉向文學，希望從思想與社會層面發聲。〈狂人日記〉等作品與新文化運動時期密切相關。","『棄醫從文』是最有辨識力的關鍵詞。"],
  "113-ch-24": ["用白與塵埃的對立讀立場","屈原用皓皓之白比喻自身清白，用塵埃比喻世俗污染。他寧可赴水，也不願犧牲志節。","這種價值選擇叫擇善固執。通權達變和和光同塵反較接近漁父勸他的處世態度。"],
  "113-ch-25": ["大同理想重點是各年齡層都受照顧","題文寫孩童、成人、長者與弱勢各得其所。C 寫孩童自在歌唱、白髮老人愉快出遊，呈現相近的安樂景象。","A 談治理方法，B 談風氣影響，D 談嚴刑威嚇。題目問的是社會生活畫面。"],
  "113-ch-26": ["用形象與動詞互相檢查","長城是固定在山上的建築，用「蹲踞」有厚重感；「無情」接「冷眼」自然。","縱線、橫線交會後形成四個方向，用「平分」合適；後文明說相遇，所以不能用「錯過」。"],
  "113-ch-27": ["讀因果：頑固不改，最後招致後果","顯者聽見告誡後仍『橫如故』，又把食物定量錯估成還能活多年。病後日夜多食，未滿一年即死。","故事用這個反轉告誡作惡者不能拿壽數當保障，對應『自作孽，不可活』。"],
  "113-ch-28": ["反襯讓一個人物的特徵更突出","一邊寫妻子一再勸、方士直說祿數終點，另一邊寫顯者自以為還有多年，仍舊橫行。","外在勸戒越清楚，越突顯顯者的固執，所以選 D。全文大致按事件順序展開。"],
  "113-ch-29": ["將受字換成「接受」檢驗","公儀休『不受』指不接受別人送的魚。A 的三軍『受』號令，是接受命令，同義。","故事的下人是對人低頭，致魚是送魚過來，不能直接套上其他例句的意思。"],
  "113-ch-30": ["拒絕不當利益才能保有原則","公儀休愛吃魚，仍拒絕贈魚，因接受之後容易欠人情、偏離法度甚至失去官位。","A 的『無欲則剛』強調不為私利所牽制，就能守住原則。公儀休不必放棄吃魚，只要用正當方式取得。"],
  "114-mb-1": ["相同次方可以先除底數","6²⁰＝(6²)¹⁰＝36¹⁰。分母 12¹⁰ 與分子有同樣的指數。","(36/12)¹⁰＝3¹⁰，選 D。"],
  "114-mb-2": ["先整理成 y＝mx＋b","3x＋4y＋5＝0 移項後，4y＝−3x−5。","除以 4 得 y＝−(3/4)x−5/4，斜率是 x 的係數 −3/4。"],
  "114-mb-3": ["√3 的偶數次方是整數","第 n 項是 2(√3)^(n−1)。n−1 為偶數時，(√3)²＝3，可以兩個根號一組配對。","前七項中，第 1、3、5、7 項有理，共 4 項。"],
  "114-mb-4": ["每筆資料加相同數值，離散程度維持不變","每人加 15 分，平均、中位數、眾數也都上升 15 分。","每人的新分數減新平均，結果和原來的分數減原平均一樣，因此標準差不變。"],
  "114-mb-5": ["特殊角的三角函數值","sin 30°＝1/2，cos 45°＝√2/2。cos 120°＝−cos 60°＝−1/2。","原式＝1/2＋√2×(√2/2)−(−1/2)＝2。"],
  "114-mb-6": ["找因式先代入相應的零點","C 的 x＋2 為零時 x＝−2。代入 f，得到 −8−4＋16−4＝0。","依因式定理，除以 x＋2 的餘式為 0，所以 x＋2 是因式。"],
  "114-mb-7": ["封閉路徑在每個經過的頂點都要進出成對","圖上各點最多三條邊。不能重複走邊又要回 A，故每一點只能各進、出一次。","把 B、C、D 的造訪順序排一排，共 3!＝6 種，最後一律回 A。"],
  "114-mb-8": ["乘上單位矩陣，矩陣不變","A 的兩欄可直接由題目讀出：第一欄 (2,4,7)，第二欄 (1,0,6)。","乘欄向量 (1,0) 等於第一欄乘 1、第二欄乘 0，因此 a＋b＋c＝2＋4＋7＝13。"],
  "114-mb-9": ["位移＝方向的單位向量乘距離","v=(−6,8)，長度 √(36＋64)＝10。題目要走 10 單位，位移剛好就是 v。","將位移加到原點 A：(2,−7)＋(−6,8)＝(−4,1)。"],
  "114-mb-10": ["恰一人命中分成兩種互斥情形","只有阿明中為 0.75×0.2＝0.15，只有阿添中為 0.25×0.8＝0.20。","相加得到 0.35。直接乘 0.75×0.8 是兩人都中。"],
  "114-mb-11": ["把絕對值不等式換成區間","|x−√15|＜4 等同 √15−4＜x＜√15＋4。因 3＜√15＜4，範圍左端介於 −1 和 0，右端介於 7 和 8。","整數是 0、1、…、7，共 8 個。"],
  "114-mb-12": ["條件機率固定已知第一次的結果","第一次已是反面，後兩次的四種結果為正正、正反、反正、反反，各等可能。","恰好兩個反面，後兩次必須恰一個反面。正反、反正兩種，機率 2/4＝1/2。"],
  "114-mb-13": ["圓心是直徑兩端點的中點","將 A、B 三個坐標各自平均。x=(1−5)/2＝−2，y=(4＋6)/2＝5，z=(7−3)/2＝2。","所以圓心為 (−2,5,2)。"],
  "114-mb-14": ["開口向下的拋物線，離頂點越近，函數值越大","頂點在 x＝−1，原式距頂點的平方乘上負數。候選 x 為 10、7、−3、−5。","離 −1 的距離依序是 11、8、2、4，最短為 2，所以 f(−3) 最大。"],
  "114-mb-15": ["依遞迴式一項一項往下算","a₃＝a₂−2a₁＝2−2＝0，a₄＝a₃−2a₂＝0−4＝−4。","a₅＝a₄−2a₃＝−4−0＝−4。"],
  "114-mb-16": ["擴充正弦定理：邊長÷對角正弦＝2R","角 C＝180°−87°−48°＝45°，它的對邊 AB＝4√2。","外接圓半徑 R＝4√2/(2sin45°)＝4。"],
  "114-mb-17": ["等比數列的各項往後一格都乘同一公比","把 a₃＋a₅ 的每個加項都往後一格成了 a₄＋a₆。設公比 r，則 r×6＝9。","r＝9/6＝3/2。"],
  "114-mb-18": ["直線與圓相切時，圓心到直線的距離等於半徑","配方得 (x−2)²＋y²＝4−k，圓心 (2,0)。到 3x−4y＝0 的距離為 |6|/√(3²＋4²)＝6/5。","令半徑平方 4−k＝36/25，得到 k＝64/25。"],
  "114-mb-19": ["等差數列奇數項總平均等於中間一項","前七項以 a₄ 為中心，首尾對稱的兩項平均也是 a₄。因此 a₄＝14/7＝2。","a₃ 和 a₅ 離中間同樣遠，故 a₃＋a₅＝2a₄＝4。"],
  "114-mb-20": ["用份數理解兩種機率的比","女生機率是男生的 5/8，可把女生當 5 份、男生當 8 份。","總共 13 份，所以選到女生的機率是 5/13。"],
  "114-mb-21": ["先用基本統計量排除錯項","1 到 9 的平均與中位數都是 5，全距是 9−1＝8，所以 A、B、C 都不對。","9×25%＝2.25，依本題採用規則取下一個位置第 3 筆，值為 3。"],
  "114-mb-22": ["平面向量內積是對應分量乘後相加","u·v＝3×5＋2×(−2)。","15−4＝11。結果是一個數，並非坐標對。"],
  "114-mb-23": ["三次函數以三次項的平移中心判斷對稱中心","令 t＝x−2，整理為 f(x)＝3t³−5t−3。t 改成 −t，前三次與一次項合值會變號。","扣掉常數 −3 後以 t＝0 對稱，所以中心是 (2,−3)。"],
  "114-mb-24": ["期望值是每種獎金乘上機率再相加","總球數 3＋5＋12＝20。藍球機率 3/20，紅球 5/20，黑球無獎金。","每抽期望是 2000×3/20＋1000×5/20＝300＋250＝550。"],
  "114-mb-25": ["向量終點減起點，再按分量算","AB=(1−(−2),3−2)=(3,1)，BC=(3−1,−5−3)=(2,−8)。","2AB−3BC=(6,2)−(6,−24)=(0,26)。"],
  "114-mb-26": ["正比例縮放和平移不改變相關係數","國文人人加 5；英文人人乘 10/9，且沒有成績因截頂而改變規則。","相關係數用標準化後的相對差距來算，這兩種正向線性調整不改變標準化值，所以仍為 0.63。"],
  "114-mb-27": ["先看角度 2x 的範圍","x 由 π/6 到 11π/18，2x 就由 π/3 到 11π/9。","sin 在 π/3 到 π/2 上升，過了 π/2 到 11π/9 下降，因此先增後減。"],
  "114-mb-28": ["依男女出席人數各為 1、2、3 分情況","各一人有 3×4＝12；各兩人有 C(3,2)×C(4,2)＝18。","各三人有 C(3,3)×C(4,3)＝4。加總是 34。"],
  "114-mb-29": ["弧長＝半徑×圓心角（弧度）","圓心角＝10/5＝2 弧度。換算約為 2×180°/π≈114.6°。","與選項比較，120° 最接近。"],
  "114-mb-30": ["條件機率公式","P(A|B)＝P(A∩B)/P(B)。這裡分母用作為條件的 B。","所以 P(A∩B)＝(3/4)(3/8)＝9/32。"],
  "114-mb-31": ["指數函數的底數維持一樣才可能靠平移重合","9×3ˣ＝3²×3ˣ＝3^(x＋2)，因此是將 y＝3ˣ 向左平移 2。","9ˣ＝3^(2x)、3^(5x) 是在改橫向尺度；(1/3)ˣ 的增加方向相反。"],
  "114-mb-32": ["原有五個節目的相對順序固定","從七個時間位置挑兩個給新增節目，有 C(7,2)＝21 種。","兩個新節目不同，可互換次序，有 2 種。總數 21×2＝42。"],
  "114-mb-33": ["對數相加相減對應乘除","2b−a＝2log6−log4＝log(6²/4)。","6²/4＝36/4＝9，所以為 log9。"],
  "114-mb-34": ["矩陣等式逐格對應","左下格 5−2b＝7，得到 b＝−1。左上格 a＋4b＝−1，得 a＝3。","右上格 3＋bc＝1，代 b＝−1 得 c＝2。三個數的和是 4。"],
  "114-mb-35": ["代入直線左式，看正負是否相反","令 F(x,y)＝2x−y−2。A=(5,3) 代入為 5，是正值。","選項 A 在直線上，B、D 代入為正，選項 C 的 (−1,−1) 代入為 −3，故在異側。"],
  "114-mb-36": ["因式分解後用零點劃分符號區間","(x−2)(x²−3x−4)＝(x−2)(x−4)(x＋1)，零點為 −1、2、4。","從最右邊往左，符號依序正、負、正、負。取正值區間 −1＜x＜2 或 x＞4。"],
  "114-mb-37": ["先用抽袋機率求白球來源的權重","甲袋被選機率 1/3，抽到白為 6/10，合起來 1/5。乙袋被選 2/3，抽白為 2/5，合起來 4/15。","已知抽白，甲袋機率是 (1/5)/(1/5＋4/15)＝3/7。"],
  "114-mb-38": ["緯圈半徑為赤道半徑乘緯度的餘弦","北緯 60° 的緯圈周長＝120cos60°＝60 公分。兩點經度差 110°−80°＝30°。","沿緯圈走 30° 只占整圈的 1/12，距離＝60/12＝5 公分。"],
  "114-mb-39": ["反方陣等於自身表示 A²＝I","看 A² 左上格 1＋2a＝1，得 a＝0。再看右上格 2＋2b＝0，得 b＝−1。","因此 a＋b＝−1。其餘兩格也可用 a＝0、b＝−1 驗算。"],
  "114-mb-40": ["俯角配合高度求水平距離","OA＝300/tan45°＝300，OB＝300/tan30°＝300√3。正南和正東互相垂直。","AB＝√(300²＋(300√3)²)＝600 公尺。"],
  "114-ch-1": ["易混字音","『惙』和『啜』都讀 ㄔㄨㄛˋ。危惙指病況危急，啜泣是低聲哭泣。","戧金的『戧』為 ㄑㄧㄤˋ，戕為 ㄑㄧㄤ；淬為 ㄘㄨㄟˋ，晬為 ㄗㄨㄟˋ；櫂為 ㄓㄠˋ，糴為 ㄉㄧˊ。"],
  "114-ch-2": ["同音字要靠詞義辨識","C 的完整詞是餽贈、喟然、潰不成軍，分別是贈送、嘆息和軍隊潰散。","其餘選項至少重複一字。滄海與滄桑都用滄，立錐與錐處囊中都用錐，不脛而走和脛骨都用脛。"],
  "114-ch-3": ["文言的『相』可偏指接受動作的一方","兩句的『相』都可以理解為動作有所指向。『相為言』是為我說話，『相賀』是向人祝賀。","A 的一分別為全、視為相同；B 的向分別是先前、偏向；C 的幸分別是寵幸、有幸。"],
  "114-ch-4": ["依詞義檢查形近字","B 的手舞足蹈、晴天霹靂、愀然變色都寫對。『愀然』可表示神色轉為嚴肅或不安。","A 改『拮据』，C 改『蜚聲』，D 改『自視甚高』。"],
  "114-ch-5": ["成語的褒貶和使用時機","野人獻曝是謙稱個人的意見或心意粗淺，與句中受讚賞後仍自謙相符。","天花亂墜常形容說得過於誇張；庸人自擾指自找煩惱；前仆後繼常形容前人倒下、後人接續奮鬥。"],
  "114-ch-6": ["原卷更正為一律給分","公告將原答案 C 更正為送分，所以這題選任何選項都計分。","練習語境時可先看第一空。下文寫謊言、詐欺與背叛，首空用『正視』可以表達願意面對。其餘兩空還需用整段語氣比對。"],
  "114-ch-7": ["七律排序要看對偶與情緒推進","接在首聯後的是落木下、長江來的對偶景象，依序戊、丙。","再來『萬里／百年』對舉，依序甲、丁。結尾由艱難而白髮，接潦倒停酒，故是乙接末句。"],
  "114-ch-8": ["莊子的養生觀","有涯是有限，無涯是無限。莊子先說拿有限生命去追無限知識會有困境。","後面的『保身、全生、盡年』指順著適當的方法保全生命、享盡天年。讀主旨以後段的正面主張為準。"],
  "114-ch-9": ["借代：用有關聯的事物代稱","題目用『絲竹管絃』代音樂。祝融可代火災，布衣可代平民，兵馬可關聯戰事。","A 的松柏、雞鳴用來比喻在逆境仍守節，沒有像其他項目那樣用關聯名詞代替指定對象。"],
  "114-ch-10": ["同一個字可以有不同詞性","『惡惡臭』第一個惡是厭惡，第二個惡修飾臭，意思是難聞。『好好色』也是用動詞接含形容詞的詞語。","所以 D 不屬於後一個相同字當名詞的例子。B 第二個『樂』指快樂，C 的第二個『親、子』指親人、子女。"],
  "114-ch-11": ["明代章回小說以回目組成長篇故事","長篇敘事按卷回分節，選 D。明代四大奇書通常指《三國演義》《水滸傳》《西遊記》《金瓶梅》。","六朝志怪多簡略記異聞；宋代說話底本的代表為話本，常保留白話特色。"],
  "114-ch-12": ["從典故辨認歷史人物","『醉草清平調』指李白奉詔寫《清平調》；『力士』與高力士相關。D 所配李白正確。","『出師未捷』詠諸葛亮，『語不驚人死不休』是杜甫，洙泗和杏壇則指孔子。"],
  "114-ch-13": ["轉折和遞進的連接語不能混用","『雖然』先承認比賽失利，後面應轉折說付出仍有價值，可接『但是』。","『況且』用來再補一個理由，和『雖然』在此不配。"],
  "114-ch-14": ["事實與主觀評價","C 的房貸政策是事件，稱它為『福音』是作者的價值判斷。","辨別時找『可說是、真可惜、太好』等語句，它們常透露看法。"],
  "114-ch-15": ["作者、作品、文類須同時符合","吳晟〈負荷〉與楊牧〈水之湄〉都是新詩，作者與作品符合臺灣文學脈絡。","洪醒夫〈散戲〉、白先勇〈孽子〉是小說。連橫〈臺灣通史序〉不是小說。"],
  "114-ch-16": ["由意象找思念對象","C 的『鄉書』是寄往家鄉的信，『洛陽邊』又指向家鄉方向。","A 想跟朋友再談文，B 為友人送別，D 寫思念遠行的人。對象不同。"],
  "114-ch-17": ["吃飯比喻實際學習","把食物一口口吃下來才會飽，放到門口只給人看並不能充飢。","把比喻換回為學，朱熹批評的正是把該自己做的功課拿去向外炫耀。"],
  "114-ch-18": ["看詞在句中的位置辨詞性","『一個不完的魘夢』中，魘夢可受數量詞『一個』限制，是名詞。","鼓、引逗、冷去分別表動作或狀態發展。"],
  "114-ch-19": ["郗公欣賞不造作的王羲之","其他年輕人可能因選婿而刻意正襟危坐，唯有東床那位若無其事地坦腹而食。","郗公反覺得此人最好，表現出不隨俗見、能從平常行止看人物。"],
  "114-ch-20": ["理想幻滅要找『再也回不去』的線索","漁人曾標記來路，太守派人依標記尋找，最後仍迷路。","桃花源一度被發現，卻不能再回到那裡，暗示理想境界難以在現實重現。"],
  "114-ch-21": ["期望語氣常用『惟、願、請』","『惟君圖之』是希望您考慮此事。燭之武藉此請秦伯重新衡量攻鄭利害。","A、B 多用反問，D 用『若』先設想一種情況。"],
  "114-ch-22": ["經、史、子、集的常見分類","《道德經》屬道家著作，《世說新語》常列小說家類，兩者都可歸入子部。","《孟子》《左傳》《詩經》在經部；《楚辭》《昭明文選》屬集部。"],
  "114-ch-23": ["婉曲用委婉話語暗示本意","『舅奪母志』字面是舅舅改變母親的意志。由《陳情表》上下文可知是母親改嫁。","不直接說明改嫁，而用奪志表達，因此選 A。"],
  "114-ch-24": ["誇飾故意把事物寫到超過實際","鬢髮用『三千丈』寫，遙遠過往用『五千年春夢』寫，明顯把長度與時間推向極端。","B 將人生比成夢，是譬喻。D 的莊周夢蝶、杜鵑託春心使用典故。"],
  "114-ch-25": ["找出跟原文明確相反的一句","首句說不必追問故事是真是假，重點是透過故事觀照自己。","A 說小說重視故事必須屬實，與原文相反，符合題目要找的『最不適當』。"],
  "114-ch-26": ["側面烘托用他人的反應讓主角特色浮現","D 寫拜倒金大班裙下的人多到數不完，藉旁人的反應呈現她的魅力。","A 直接寫外表與聲音，B 直接寫臉，C 也直接比對外貌特點。"],
  "114-ch-27": ["沿用作者對作品類型的區分","第二段把〈桃花源記〉歸入晉人幻設的寓言一路，指重點在寓意，文詞為末。A 最接近這個分類。","文章比較唐傳奇和古文時說當時論者貶傳奇；宋代平話在市井另行興起，不能概括為擅長改寫唐傳奇。"],
  "114-ch-28": ["兼具奇異情節和宛轉敘述","B 寫筷子投入月光後出現美人，先不滿一尺，落地時變得和常人一樣高，奇事分步展開，畫面具體。","A 主述藥和寶劍，C 主述財物忽然消失，D 主要描寫人物登場，B 最符合題目要的組合。"],
  "114-ch-29": ["以原文的反覆試探定位答案","首段說衛鞅試探秦孝公是否有堅定的變法決心，是否真願意推動強國方案。","最後成為最佳拍檔，關鍵是堅定信念，並非形象或保守。"],
  "114-ch-30": ["利出一孔＝國家只留一條獲利途徑","文中說個人想取得爵位、土地與富貴，就必須走國家設計的軍功途徑。","這與（1）由政府控制並引導人民活動較像。（2）主張個人自由競爭，與『只留一個孔道』不合。"],
  "114-hg-1": ["二戰後基督宗教在部落的傳播","『美國提供救濟物資』是戰後年代線索。傳教、醫療、救濟等活動與原住民族許多家庭或部落改信相連。","荷治時期也有傳教，但題中的美援物資與大規模傳教屬二戰後情境。"],
  "114-hg-2": ["霧社事件後的理蕃政策","1930 年霧社事件後，1931 年總督府的新大綱強調同化教化，並透過集中移住管理。","題幹已提示『教化與同化』，因此不能選恢復以軍事征服為主。"],
  "114-hg-3": ["家庭移民與社會秩序","早期單身男性大量來臺，男女比例不均，定居家庭較少。讓妻小同行可減少這類移民社會的失序風險。","女性也可能參與農務，題幹問政策建議的社會背景，重點在穩定移民社會。"],
  "114-hg-4": ["三省的分工也是制衡","中書擬決策、門下審核、尚書執行。單一高官無法兼掌從擬詔到施行的全流程。","因此可降低權臣把持朝政的機會。三省都是中央機關，並非中央和地方的分層。"],
  "114-hg-5": ["戰後臺灣從進口替代轉向出口擴張","1960 年代國內市場有限，已建立的工業需要更多買家，美援也逐步減少。政府鼓勵工業產品出口。","記為『把生產的商品賣到國外』的出口導向。加工出口區是可連記的例子。"],
  "114-hg-6": ["日治時期社會運動有多條路線","日治知識分子投身文化啟蒙、議會請願與勞工農民運動。題幹同時點到文化和階級。","若只說政治改革或只說激進獨立，都省掉題幹已明示的一部分活動。"],
  "114-hg-7": ["士族與士紳的權力來源不同","魏晉士族依門第血統在中央壟斷或長期掌權。後來的士紳常以功名、家族與地方資源參與治理。","B 同時符合兩期特色。A 將科舉和世襲顛倒。"],
  "114-hg-8": ["用太平天國爆發作年代標記","太平天國於 1851 年起事。題幹說該戰爭在它之前，所以找早於 1851 年的選項。","第一次鴉片戰爭在 1840 年代初；英法聯軍、清法戰爭、甲午戰爭都更晚。"],
  "114-hg-9": ["身分轉向居住地是『在地化』","『過客』仍將目光放在祖國，『在地人』則在居住地建立長期生活和政治、社會認同。","C 符合身分轉變。寄捐款、投資祖國是維繫祖籍地關係的例子。"],
  "114-hg-10": ["哥倫布受西班牙王室資助","『熱納亞人、15 世紀末、女王資助』是哥倫布的線索。1492 年西班牙王室支持他跨大西洋遠航。","他本來想向西抵達亞洲，實際到達加勒比海地區。問資助國，選西班牙。"],
  "114-hg-11": ["南丁格爾與克里米亞戰爭","1850 年代克里米亞戰爭中，南丁格爾投入傷兵照護，重視消毒、環境衛生與病房管理。","她的改革與近代護理制度相連。一次世界大戰的年代比她服務該戰的年代晚很多。"],
  "114-hg-12": ["浪漫主義重感情、歷史與想像","題幹欣賞中古的宗教熱情、騎士冒險，符合 19 世紀浪漫主義對中世紀的回望。","啟蒙時代常重視理性與批判。遇到感情、傳說、個人想像，要想到浪漫主義。"],
  "114-hg-13": ["俄國內戰的戰時共產主義","布爾什維克十月革命後，蘇維埃政權在內戰階段強制徵糧，用以維持軍隊和城市供應。","十月革命實際在 1917 年，內戰與戰時共產政策在 1918 年後展開。題目要辨認的是蘇維埃政權。"],
  "114-hg-14": ["米蘭敕令使基督教合法化","西元 313 年後，基督徒可合法信仰，並獲得原先被沒收財產的返還。","合法化與定為國教是不同階段。羅馬帝國將基督教定為國教在後來。"],
  "114-hg-15": ["自然災害影響南北經濟重心","黃河決溢改道，先影響北方農田、道路與人口生活；戰亂與遷移進一步削弱北方。","南方在移民、開發與經濟擴張下相對興起，與中國歷史上經濟重心南移相符。"],
  "114-hg-16": ["由甘蔗判斷熱帶商業性栽培","甘蔗適合溫暖潮濕環境，通常大規模種植，接著製糖加工並進入市場。","從流程圖辨認以經濟作物為主、搭配加工或銷售的模式，符合 A。"],
  "114-hg-17": ["巴西嘉年華辨識國家","嘉年華是巴西著名民俗活動，里約熱內盧尤其有名。移民與非裔文化共同形成巴西多元文化。","金磚五國中的其餘選項也有多元族群，但『嘉年華』是最能縮小範圍的線索。"],
  "114-hg-18": ["由人口金字塔突出位置辨認移工","圖形突出的是勞動年齡層，且性別結構不均，因此最容易想到某性別的成年勞工大量移入。","若是重男輕女影響出生，差異會先出現在底部的嬰幼兒年齡層。"],
  "114-hg-19": ["高齡化階段的三個門檻","65 歲以上占 7% 為高齡化、14% 為高齡、20% 為超高齡。題中的 19.18% 落在 14% 和 20% 間。","題目問『邁向』哪個階段，所以依更正答案選 C，表示正接近超高齡社會的 20% 門檻。"],
  "114-hg-20": ["巴爾幹半島的國家分屬不同區域組織","一些巴爾幹國家加入歐盟，另一些未加入，所以跨境追查可能遇到不同的司法與警務合作機制。","這題依更正答案選 D。題目問加入狀況差異大的地區，要比較同一半島內的多個國家。"],
  "114-hg-21": ["澳洲西部為古老岩地高原","澳洲西部廣大高地以古老結晶岩和乾燥地貌為特色。東部大分水嶺也不能讀成新褶曲高山。","紐西蘭的著名峽灣在南島西南，火山地形則以北島較著名。"],
  "114-hg-22": ["寮國水力發電與跨境售電","寮國臨湄公河，山地與河川落差有利水力發電，電力外售泰國、越南等鄰國。","『東南亞的電池』指這種跨國供電定位。"],
  "114-hg-23": ["建蔽率看占地，容積率看各層樓地板面積合計","A 假設各層同面積，占地 30%≤35%，四層合計 30%×4＝120%，並為住宅用途。","B、D 的占地超過限制。C 面積雖合規，題目給的是住宅區，選項 A 的用途最符合題意。"],
  "114-hg-24": ["同一零件採共同尺寸與接口＝規格化","不同品牌都改用 Type C，重點是插頭形制與接口能互通。依題意最具體的是規格化。","標準化是較廣的概念。專業化指分工，客製化則依個別需求改做。"],
  "114-hg-25": ["殖民邊界常忽略原有族群分布","殖民強權畫出的界線可能切開同一族群，也可能把關係緊張的多個群體包進一國，留下治理難題。","題目問廣泛的結構原因，選與殖民邊界直接相關的 C。"],
  "114-hg-26": ["伯吉斯同心圓的過渡帶","低收入住戶和新移民常進入緊貼中央商業區的過渡帶，原住戶外移，土地使用與居住條件較不穩定。","讀圖時從中心看。這幅圖中心標 5，外面第一圈標 4，所以選 B。"],
  "114-hg-27": ["拉丁美洲裔在美國南部與西南突出","觀察美墨邊境附近的加州、德州、新墨西哥一帶。圖乙在這些區域色階集中。","圖丙高值主要在美國東南部，分布重心不同。"],
  "114-hg-28": ["大西洋三角貿易要順著箭頭讀","甲由非洲到美洲，主要運送被奴役者；乙美洲到歐洲，常載糖等熱帶作物。","丙由歐洲到非洲，運送槍枝等商品，因此順序是奴隸、熱帶作物、槍枝。"],
  "114-hg-29": ["地勢會決定水往哪裡流與積在哪裡","依給定的降水量模擬淹水，需要知道高程、坡度與低窪地形，可用地勢分析。","環域分析主要找指定距離內的範圍；查詢分析是選取符合條件的資料。"],
  "114-hg-30": ["賽普勒斯北部由土耳其支持","賽普勒斯島北部土裔社群在土耳其支持下建立北賽普勒斯政權。南部主要是希裔社群。","題目問北部的支持者，選土耳其。希臘容易與南部的希裔背景混淆。"],
  "114-hg-31": ["1914 年非洲仍獨立的少數國家","衣索比亞抵抗義大利殖民入侵，賴比瑞亞也維持獨立，所以選 A、D。","納米比亞曾屬德國殖民地，塞內加爾屬法國勢力，烏干達受英國控制。"],
  "114-hg-32": ["1857 年印度兵變的宗教導火線","士兵需咬破彈藥包，傳聞潤滑劑有牛油、豬油，分別觸犯印度教與伊斯蘭教禁忌。A、C、E 從政策、導火線與文化差異說明。","事件後英國政府加強直接統治。殖民剝削是背景，但題目強調的直接引爆原因是宗教與文化衝突。"],
  "114-hg-33": ["原住民族復振來自民權運動與政策變化","原住民族權益較受媒體和社會重視，與民權、人權運動及各種政府、國際政策進展相關，選 A、B、D、E。","C 的『各國普遍承認集體自決』範圍過廣，實際進展因國家而異。"],
  "114-hg-34": ["哥倫布大交換分清楚傳播方向","美洲原住民受外來疾病重創，基督宗教和馬牛由歐洲進入美洲，馬鈴薯由美洲傳往歐洲，所以 A、B、C、D 可選。","火雞原產美洲，後來傳到歐洲，E 的方向顛倒。"],
  "114-hg-35": ["文藝復興以人文與新技法重讀古典","義大利率先興起，人物情感更細緻，透視和解剖讓繪畫更自然，選 A、C、E。","文藝復興汲取古希臘、羅馬傳統，也重視素描及構圖，排除 B、D。"],
  "114-hg-36": ["臺灣地名中的地形字","崙可指沙丘等隆起地形，澳常指灣澳，鼻常指突入海中的岬角，因此選 A、B、C。","崎常聯想到坡陡處；坑多指低陷地形，與題中『平原』配對不合。"],
  "114-hg-37": ["剩水區是降水超過蒸發的區域","赤道附近間熱帶輻合促進上升降雨，中高緯有盛行西風及極圈附近的氣旋活動，對應 A、C、D。","位於副熱帶的馬緯度無風帶常有下沉氣流、降水少，是缺水的典型區域。"],
  "114-hg-38": ["由形成機制辨臺灣火山地景","澎湖以基性玄武岩為主，基隆山可由侵入岩理解，大屯及龜山島的岩漿、噴發型態依題目分類為 D、E，故選 A、B、D、E。","小琉球以隆起珊瑚礁石灰岩為主，C 說是寧靜式噴發形成，地質成因不對。"],
  "114-hg-39": ["殖民史與東南亞的宗教分布","菲律賓的天主教傳統與西班牙有關，東帝汶則深受葡萄牙影響，選 B、C。","泰國以佛教較普遍，印尼主要信奉伊斯蘭教，越南的宗教結構則更多元。"],
  "114-hg-40": ["季風影響常帶來夏雨冬乾","高雄、曼谷、孟買都受季風型季節降雨影響，夏半年較多雨，冬季偏乾，選 A、B、E。","洛杉磯屬典型冬雨夏乾的地中海型；倫敦較少出現明顯冬乾。"],
  "114-en-1": ["brief＝短暫的","雲霄飛車到了頂端後就往下衝，中間只有短暫的停頓。a brief pause 是『短暫的停頓』。","tasty 好吃的，local 當地的，mental 心智的。"],
  "114-en-2": ["much to my relief＝令我大大鬆一口氣","父親輕度中風後很快康復，說話者感到寬心，所以選 relief。","injury 傷害、stress 壓力、sweat 汗水，都不符合得知家人康復的心情。"],
  "114-en-3": ["casual＝休閒的、不正式的","原句直接用 or informal 解釋空格。T 恤和牛仔褲屬較不正式的穿搭。","swift 快速的，temporary 暫時的，permanent 永久的。"],
  "114-en-4": ["element＝構成要素","such as 後舉出大團圓、討喜主角、背景音樂，它們都是浪漫喜劇的元素。","leather 皮革，column 柱或專欄，helmet 安全帽。"],
  "114-en-5": ["within walking distance＝步行可達","商店和餐廳離家不遠，走路就能到。distance 是距離。","記為一組固定搭配。tolerance 容忍，conference 會議，evidence 證據。"],
  "114-en-6": ["recognize＝認出","歌手戴面具，聽眾仍能靠獨特嗓音認出他。recognize 可直接接人。","rely 常搭 on，relay 指轉達或接力，reduce 指降低。"],
  "114-en-7": ["analyze＝分析","研究者先細看消費者行為，之後才針對資料提出行銷建議。closely analyzed 是仔細分析。","retain 保有，reject 拒絕，apologize 道歉。"],
  "114-en-8": ["destructive＝破壞力強的","海嘯將船沖上岸，城鎮成了碎屑，這些都是破壞力的表現。","constructive 是有建設性的，imaginative 是有想像力的，sensitive 是敏感的。"],
  "114-en-9": ["transfer money to an account＝把錢匯到帳戶","con artist 是騙子，陌生人的帳戶是款項的去向。transfer 主詞是匯款的人。","vanish 消失，accomplish 完成，convert 轉換性質或形式。"],
  "114-en-10": ["figure out＝想出、弄懂","老闆在經濟危機中想出促銷方法，後半句的 his plan 呼應想出來的方法。","pass away 過世，pull over 靠邊停，calm down 冷靜。"],
  "114-en-11": ["keep track of＝持續留意","父母需要追蹤孩子上網情況，才能確認瀏覽內容適合。","lose control of 是失去控制，come down with 是染上疾病，put up with 是忍受。"],
  "114-en-12": ["draw in＝吸引","景點開幕後持續吸引世界各地遊客。has been 後面接 drawing in，表示動作一直持續。","put off 延後或使反感，take after 長得像，break out 爆發。"],
  "114-en-13": ["on behalf of＝代表","學生會主席以學生會的名義宣布募款活動，因此選 On behalf of。","in addition to 除了……以外，as opposed to 與……相對，by virtue of 憑藉。"],
  "114-en-14": ["in turn＝進而、接著導致","先有景氣衰退，接著影響就業，後者是前者引發的結果。","at random 隨機，at ease 放鬆，in vain 徒勞。"],
  "114-en-15": ["go the extra mile＝比基本要求更努力","想進頂尖大學要參與課外活動又維持成績，這是多付出一點的具體例子。","spill the beans 洩漏祕密，let out a scream 尖叫，beat around the bush 拐彎抹角。"],
  "114-en-16": ["過去完成式 had＋過去分詞","抵達機場是過去事件，班機起飛發生在抵達之前，所以用 had taken off。","現在完成式 has taken off 是站在現在回看，這裡的比較基準是過去的抵達時間。"],
  "114-en-17": ["mustn’t＝禁止","這個停車位置只留給緊急車輛，所以普通車輛不得停。","may 表示許可，wouldn’t 可指不願或假設中不會，都不如 mustn’t 直接表達規定。"],
  "114-en-18": ["recommend doing＝建議做某事","recommended 後面若直接接動作，用 V-ing。句意是建議每天複習單字。","另一種正確構造是 recommend that＋主詞＋原形。此題沒有 that，所以選 reviewing。"],
  "114-en-19": ["介系詞＋whom 指人","把關係句拆回 I spoke to the manager during the meeting。spoke 要用 to 介紹談話對象。","將 to 提到 whom 前，得到 the manager, to whom I spoke。which 通常指物。"],
  "114-en-20": ["thought-provoking＝引人深思的","後面說演講鼓勵學生批判思考，表示演講引發思考。","provoking 有主動引起的意思。整個複合形容詞放在 lecture 前，常用連字號。"],
  "114-en-21": ["過去分詞可補充說明主詞","真正主動詞是 studied。中間的 motivated by… 表示聽到鼓舞的話而受到激勵。","若寫 were motivated，會在同一句放兩個限定動詞，中間卻缺少連接。"],
  "114-en-22": ["leave＋受詞＋形容詞＝使某人處於某狀態","活動取消，使遠道而來的客人感到失望。leave guests disappointed 符合語意與句型。","disappointed 描述人的感受，disappointing 則形容令人失望的事物。"],
  "114-en-23": ["間接問句使用正常語序，也可用疑問詞＋to V","how to get to the gym 是『怎麼到體育館』，可接在 Can you tell me 後面。","A、B 像直接問句般倒裝；C 的 what 已代表要做的事，又加 it 會重複。"],
  "114-en-24": ["數量詞＋of whom 引導補充說明","three sons 有三人，所以可用 all of whom（他們三人都……）。","both 只指兩人。A、D 直接用 them 開新句，但前面只有逗號，缺連接詞或句號。"],
  "114-en-25": ["Seeing 開頭表示主詞看到後的反應","Nina 看見蟑螂跑過桌面，所以尖叫。Seeing 的動作主體和主句的 Nina 一致。","see＋受詞＋原形可表觀察到完整動作，故 seeing the cockroach run 合適。"],
  "114-en-26": ["主旨要涵蓋整篇","文章一路從葡萄品種的起源、交易、種植難題講到其地位和藝術影響。","C 的 trace the historical importance 概括整體。種植和宗教只是其中個別段落。"],
  "114-en-27": ["辨代稱要把指涉對象代回去","the choice of emperors、the precious fruit、this ancient grape variety 都在不同句子指同一種葡萄。","divine abundance 是葡萄所象徵的意義，the distinctive oval shape 只是它的形狀。"],
  "114-en-28": ["細節題找兩條可對照的證據","宴會展示葡萄，說明它是奢侈食材。柱頭、裝飾雕帶上的葡萄圖案，說明它也是藝術題材。","B 把兩點都說到。原文的 grape houses 用來儲藏水果，沒有說主要用於發酵。"],
  "114-en-29": ["command a price＝賣到某個價位","後面以一串葡萄可賣相當於 3,000 美元為例，所以 command 指配得上、能賣得高價。","D deserved 是四項中最接近的。此處不是『下令』，用 fetch a high price 也能理解。"],
  "114-en-30": ["客觀語氣重在描述和舉例","作者以背景、價格、貿易、藝術等內容說明葡萄的地位，整體沒有嘲笑、批判或質疑的立場。","objective 是客觀的；critical、skeptical、humorous 分別是批判、懷疑、幽默。"],
  "114-en-31": ["成立機構可用 found、establish、set up","三者都能直接接 a charity，表示成立慈善機構。found 在這裡是原形，意思是創立。","participate 表示參與，通常接 in；make up 常表示組成、編造或補足，不適合這裡。"],
  "114-en-32": ["表示有關聯可用 be linked to 與 be associated with","題目在描述社群媒體使用與青少年壓力、焦慮程度的關聯，C、E 都自然。","be devoted to 是致力於，be exposed to 是暴露於，be satisfied with 是對……滿意。"],
  "114-en-33": ["讓步介系詞 despite / in spite of＋名詞片語","his lack of experience 是名詞片語，後半句寫即使欠缺經驗，他仍得第一。A、E 都接得上。","although 和 while 此用法通常接有主詞、動詞的子句；unless 意思是除非。"],
  "114-en-34": ["用同義詞辨認揶揄、嘲弄","tease、ridicule、make fun of 都能表示拿政治人物開玩笑，符合觀眾大笑。","forbid 是禁止，take delight in 指以……為樂，未直接表達表演者嘲弄的動作。"],
  "114-en-35": ["三種『由……組成』的句型","委員會由不同領域專家組成，可用 consists of、is composed of、is made up of。","若用主動 make up，主詞應是組成委員會的成員。be capable of 是有能力做某事。"],
  "114-en-36": ["as long as＝只要","A 用 Nothing is impossible，E 用 Anything is possible，正反表達都可以接 as long as you study hard。","hard 在 study hard 是努力地；hardly 是幾乎不。其餘句子有名詞或子句結構問題。"],
  "114-en-37": ["與過去事實相反的假設句","條件用 if＋had＋過去分詞，結果用 wouldn’t have＋過去分詞，所以 D 成立。","B 用 Had I known 倒裝，等於 If I had known。C 改成與現在情況相反的形式，少了過去結果。"],
  "114-en-38": ["so＋副詞＋that 表示『如此……以至於』","A 用 was written 做被動，needed to be rewritten 表示報告需要被重寫。E 用 required a complete rewrite 表達同義結果。","B 變成『我們需要被重寫』，C 誤用主動，D 把語意改成『太草率而無法完全重寫』。"],
  "114-en-39": ["the＋比較級，the＋比較級","B 用 The longer… , the more likely you are to…；E 用 The more time you spend… , the more likely you are to…，都能表達時間越長越可能買。","時間由人 spend，不能寫成 you cost time。more likely 搭配 be likely to＋原形。"],
  "114-en-40": ["no matter how / however＋副詞＋主詞＋動詞","C 的 No matter how hard he tried 與 D 的 However hard he tried 都表示『無論他多努力』。","這是讓步副詞子句，主詞 he 在 tried 前。A 的 did he try 是疑問句倒裝，不適用。"],
  "115-hg-1": ["送王船與王爺信仰","題幹最有辨識力的是『燒王船』，民間藉送王船象徵把瘟疫和災厄送出境，與王爺信仰密切相關。","保生大帝也和醫藥、治病有關，但辨認這種祭典要抓『王船』；媽祖主要與航海守護相關。"],
  "115-hg-2": ["蘇聯末期的戈巴契夫改革","1989 年、國會改革、由一黨專政走向多黨，以及對西方緩和，是蘇聯末期的關鍵線索。","戈巴契夫推動改革與公開化，但經濟困難未立刻解決。鄧小平改革開放的重心在中國的經濟改革。"],
  "115-hg-3": ["以航海路線辨識殖民國","『通過太平洋來到東亞』指向西班牙跨太平洋的航線。西班牙從美洲出發跨洋抵菲律賓，並與他國競逐香料貿易。","葡萄牙的典型路線是繞非洲好望角、經印度洋往東。香料本身四國都有興趣，航線才是關鍵。"],
  "115-hg-4": ["塞爾柱突厥與拜占庭","11 世紀進入巴格達、使哈里發受制，接著擊敗拜占庭並進入小亞細亞，符合塞爾柱突厥。","蒙古軍攻入巴格達發生於 13 世紀。先用世紀排除，再看地點。"],
  "115-hg-5": ["東晉門閥政治","世家大族掌握人脈、財力、文化聲望和軍事資源，東晉司馬氏皇權需要依賴這些大族。","像王氏、謝氏都曾居政治要津。題幹強調的是世家大族長期與皇權制衡。"],
  "115-hg-6": ["第一次臺海危機與中美共同防禦條約","韓戰結束後，東亞進入同盟布局。1954 年中共砲擊金門，臺海情勢升高。","同年中華民國與美國簽訂《中美共同防禦條約》。注意 1954 年砲擊與 1958 年八二三砲戰可分屬不同次危機。"],
  "115-hg-7": ["文藝復興的人文主義","重視個性、人的思想情感和現世生活，是文藝復興人文主義的特色。","題幹特別說仍可接受基督信仰。人文主義重估人的價值，當時許多思想家仍是基督徒。"],
  "115-hg-8": ["臺灣議會設置請願運動","『立法權、預算審查權』描述的是議會。『向日本帝國議會請願』點出爭取臺灣議會的途徑。","臺灣文化協會、臺灣民眾黨是日治時期的團體，但題目所求是具有上述權力的自治機構。"],
  "115-hg-9": ["用美國南北戰爭推算日本史年代","美國南北戰爭在 1865 年結束，戰後重建和日本 1868 年左右展開的明治維新時間相符。","甲午戰爭在 1894 年開打，偷襲珍珠港在 1941 年。把外國事件當作年代尺。"],
  "115-hg-10": ["婦女選舉權運動","紐約州塞尼卡瀑布 1848 年婦女權利大會主張包含婦女選舉權。1848 年屬 19 世紀中葉。","題目問這種運動訴求何時出現。美國憲法第十九條修正案在 1920 年生效，是後來的成果。"],
  "115-hg-11": ["排灣族的家屋與百步蛇紋","板岩家屋加上貴族階序、百步蛇祖靈意象，指向排灣族。","單看板岩屋，也可能聯想到其他族群；將蛇紋和貴族象徵一起比對更可靠。"],
  "115-hg-12": ["由徽章聯想到飛虎隊","辨識原圖的飛虎隊意象。抗日戰爭時，美國志願航空隊曾協助中國迎戰日軍。","北伐是國民政府早期的軍事統一行動，冷戰中的臺海危機則在二戰之後。"],
  "115-hg-13": ["十字軍東征與地中海商業","11 世紀末十字軍東征開始，軍隊和物資需要跨海運送，義大利商人藉勢擴張東地中海商業據點。","威尼斯、熱那亞、比薩是這題的港市線索。亞歷山大東征與布匿戰爭都在古代。"],
  "115-hg-14": ["均田制瓦解後的兩稅法","『戶籍散亂、土地兼併』說明按人丁及授田運作的租庸調制度難以為繼。","唐代改行兩稅法，依資產與土地等課徵，於夏秋分徵。明代一條鞭、清代攤丁入畝都是其他時期的改革。"],
  "115-hg-15": ["德意志帝國的世界政策","『20 世紀初、世界政策』是威廉二世時期德國追求海外勢力、海權和殖民地的線索。","德國海軍擴張使英國感受到威脅。不要只看某國經濟強大，還要辨認政策名稱。"],
  "115-hg-16": ["戰後初期的長官公署","『內地來臺警官』領導、臺籍作基層，配合後續拔擢臺籍，指向 1945 年政權移交後及二二八事件前後。","1940 年代的行政長官公署符合這個時間。1880 年代仍是清治，1920 年代仍是日治。"],
  "115-hg-17": ["二戰後的非殖民化","戰後歐洲殖民列強受到削弱，亞洲、非洲民族獨立運動大增；社會主義陣營亦擴張。","一戰後已有民族自決的訴求，但題幹描寫亞非太平洋廣泛脫離殖民的浪潮，更符合二戰後。"],
  "115-hg-18": ["湖廣地區成為糧食主產地","明代後期湖廣稻米產量提高，形成『湖廣熟，天下足』的說法，能透過運輸供糧。","這裡的湖廣主要對應今天的湖北、湖南。看見『供應全國糧食』要把地名與農業變化連在一起。"],
  "115-hg-19": ["清代中部拓墾與割地換水","張達京在臺中開發水圳，與當地原住民透過割地換水協調分配灌溉，題幹的分水做法指向這一帶。","可連記彰化施世榜與八堡圳、鳳山曹謹與曹公圳、台北郭錫瑠與瑠公圳。"],
  "115-hg-20": ["延邊位在中國東北與朝鮮半島交界一帶","吉林東部鄰近北韓，延邊是朝鮮族自治州，歷史上有朝鮮半島移民，保有朝鮮語和相關文化。","位置與族名兩條線索都指向朝鮮人。"],
  "115-hg-21": ["由地形、降水和板塊判斷能源","紐西蘭山地多，河川落差大，適合水力發電；北島部分地區有火山與地熱資源。","因此合適的組合是水力、地熱。核能不屬再生能源，也不是該國主要電力。"],
  "115-hg-22": ["嬰兒性別比＝每 100 名女嬰對應的男嬰數","高於 110 表示男嬰格外多。題目問的是出生時期，先排除成人遷移或戰爭造成的成年人口差異。","傳統偏好男孩可能影響生育選擇，與這種出生人口差異最直接相關。"],
  "115-hg-23": ["河流向下侵蝕形成峽谷","太魯閣的立霧溪向下切入岩層，留下狹窄谷底和陡峭兩壁。","比較侵蝕與堆積：侵蝕搬走岩石並加深谷地；堆積把沉積物留在原地，通常不會切出深谷。"],
  "115-hg-24": ["出生下降會提高老年人口的比重","一胎化長期壓低出生數，令年輕人口變少，而原有的大批人口逐步變老。","醫療進步與死亡率下降可延長壽命，題目問快速老化最主要的政策性因素，選一胎化。"],
  "115-hg-25": ["人口金字塔從高年齡層讀壽命線索","比較兩圖時看上端。2018 年高年齡層分布較明顯，顯示更多人活到高齡。","所以平均壽命延長。只看某個年齡層寬窄，無法直接斷定移入勞工增加。"],
  "115-hg-26": ["比例尺先把單位統一","32 公里＝32×100,000＝3,200,000 公分。圖上 16 公分對應實際 3,200,000 公分。","兩邊同除 16，得到 1：200,000。"],
  "115-hg-27": ["認雪梨港地標","選 A，留意白色帆狀屋頂。雪梨歌劇院位於雪梨港，是辨識澳洲雪梨常用的地標。","做照片題時先找建築和地形，例如海港、橋梁及地標，再判斷城市。"],
  "115-hg-28": ["由年代與區域判讀經濟事件","題幹同時給『2010 年』、『西班牙』、『財政危機』，符合 2010 年前後的歐洲債務危機。","亞洲金融風暴主要關聯 1997 年亞洲市場，石油危機典型年代是 1970 年代。"],
  "115-hg-29": ["辨認國道 5 號","雪山隧道位於北宜高速公路，其路線是國道 5 號，連接臺北、新北與宜蘭。","看原圖要找國道盾牌上的 5，並用坪林、頭城及雪山隧道交叉確認。"],
  "115-hg-30": ["苗栗公館與客家醃菜","福菜以芥菜醃漬，是臺灣客家常見的傳統食物。苗栗公館有相應的客家聚落與飲食文化。","『福菜、踏鹹菜』是比『苗栗』更直接的線索。"],
  "115-hg-31": ["由季節景觀判斷緯度與氣候","冬季白雪、春花、秋楓，加上夏季可能受颱風影響，四季分明且位於東亞。","北海道冬季明顯有雪；沖繩、香港與峇里島的低海拔地區不具這種雪季。"],
  "115-hg-32": ["都市化也可能由農村推力造成","工作不足、貧窮與土地分配問題，促使居民離開農村而進入大城，都市人口比率因而上升。","都市人口占比是居民住在哪裡的指標，不能直接推成國家富裕。"],
  "115-hg-33": ["新加坡接近赤道，全年高溫、多雨","讀氣候圖先看溫度曲線：月均溫高、全年變化小。再看降水柱：每月有雨，沒有很明顯的乾季。","符合上述熱帶雨林型特徵的是圖 A。"],
  "115-hg-34": ["山地的垂直氣候帶","同一地點隨海拔上升，氣溫逐漸下降。臺灣由海平面到高山有很大高度落差，因而出現多種氣候與林相。","坡度是地面陡緩，海拔高度才是這題的主要控制因素。"],
  "115-hg-35": ["生產流程前後階段由不同公司負責＝垂直分工","晶片設計、晶圓製造及封裝測試是前後不同的生產環節。各公司專注在各自環節，就叫垂直分工。","若一家企業合併控制前後環節，才是垂直整合。水平則指同一階段。"],
  "115-hg-36": ["臺南濕地與黑面琵鷺","黑面琵鷺在臺灣西南沿海的魚塭、潟湖與泥灘度冬。台江國家公園包括臺南曾文溪口等濕地。","玉山以高山生態為主。題目關鍵是渡冬水鳥與沿海國際級濕地。"],
  "115-hg-37": ["相同距離內，氣壓差越大，風力通常越強","四組 A 到 B 都是 1 公里。逐組讀兩點的等壓線數值並看差值，D 的氣壓梯度最大。","不要比較哪組的最高氣壓數字最大。要比較每單位距離的氣壓變化。"],
  "115-hg-38": ["乾燥地區建築常用小窗","沙漠白天日照強，也可能有風沙。小窗可減少進入室內的日照和沙塵。","高腳屋與斜屋頂常見於較濕、較常降雨或有淹水風險的地區。"],
  "115-hg-39": ["火耕煙霧飄散造成霾害","大量燃燒釋出細粒懸浮微粒，隨風到鄰國形成灰霧、降低能見度並損害空氣品質。","沙塵暴主因是沙塵揚起。這題的污染源是火耕煙霧，選霾害。"],
  "115-hg-40": ["五大湖區酪農帶","五大湖附近較涼，生長季短，但都市多、交通便利。生乳等易腐產品需要快速抵達市場，因而利於酪農。","美國中部大平原常連結小麥或畜牧，密西西比河下游則較暖，與題幹線索有別。"],
  "115-mb-1": ["斜率＝往上變多少 ÷ 向右走多少","由 A 到 B，x 增加 5−1＝4，y 變成 2−3＝−1。","斜率是 −1/4。若從 B 算回 A，分子分母要同時換順序，結果一樣。"],
  "115-mb-2": ["一次式除法的餘式定理","2x＋1＝0 時 x＝−1/2。把這個 x 代進 f，商乘除式的部分會變成零。","餘式＝2(−1/2)³＋3(−1/2)²−1＝−1/4＋3/4−1＝−1/2。"],
  "115-mb-3": ["絕對值表示距離","|x＋2|＜4 表示 x＋2 距離零不到 4，所以 −4＜x＋2＜4。","三邊都減 2，得到 −6＜x＜2。嚴格小於，兩個端點都要用小括號。"],
  "115-mb-4": ["圓的標準式","把 x²−4x 配成 (x−2)²−4，y²＋6y 配成 (y＋3)²−9。","整理得到 (x−2)²＋(y＋3)²＝25。比對 (x−h)²＋(y−k)²＝r²，圓心是 (2,−3)。"],
  "115-mb-5": ["兩個銳角互餘，和為 90°","67°＋23°＝90°。在直角三角形，一個銳角的鄰邊是另一角的對邊。","cos 67°＝sin 23°＝x。"],
  "115-mb-6": ["同位置的矩陣元素相減","把 A 移到右邊，B＝2I−A。2I 的兩個對角元素是 2，其他是 0。","第一列是 2−1＝1、0−5＝−5；第二列是 0−2＝−2、2−3＝−1。"],
  "115-mb-7": ["對數相減對應相除","log a−log b＝3.1−1.1＝2，所以 log(a/b)＝2。","常用對數底數是 10，a/b＝10²＝100，因此 a＝100b。"],
  "115-mb-8": ["同底數時比較指數","把 4 寫成 2²，得到 x＝2^0.6，y＝2^0.4。","xy＝2^1，x²＝2^1.2。底數 2 大於 1，指數最大的 x² 數值也最大。"],
  "115-mb-9": ["遞迴式化為等比數列","3aₙ₊₁＋aₙ＝0，所以每往下一項乘 −1/3。","從第 2 項到第 5 項有 3 次乘法。a₅＝(−4/3)(−1/3)³＝4/81。"],
  "115-mb-10": ["列出等可能的數對","從四個數任取兩個，順序無關，共有 4×3÷2＝6 對。","差的絕對值為 2 只有 {1,3} 與 {2,4}，機率是 2/6＝1/3。"],
  "115-mb-11": ["等差數列求項數與總和","從 35 到 100 共增加 65，每天多做 5 下，所以有 13 次增加，包含首日共有 14 天。","平均每天 (35＋100)÷2＝67.5 下，總數 67.5×14＝945。"],
  "115-mb-12": ["配方法找二次式的最小值","x²＋4x＋5＝(x＋2)²＋1。平方最低是零，所以整式最小為 1。","任何實數 x 代入都大於等於 0。"],
  "115-mb-13": ["分數指數與平均數","3^(3/2)＝3√3，3^(5/2)＝9√3，3^(7/2)＝27√3。","三個數加起來再除以 3，得到 (3＋9＋27)√3÷3＝13√3。"],
  "115-mb-14": ["百分位數要找排序位置","資料已排序，共 30 人。30×65%＝19.5，依本題採用的規則取下一個整數位置 20。","第 19 筆是 38，第 20 筆是 40，所以第 65 百分位數是 40。"],
  "115-mb-15": ["同時間內，距離與速度成正比","沿經線往北極走，甲從北緯 20° 到 90°，經過 70° 的圓弧。","甲速度是乙的兩倍，同時到達表示乙只走 35°。向北走 35° 到 90°，出發處是北緯 55°。"],
  "115-mb-16": ["時針轉一圈需 12 小時","晚上 11 點到早上 7 點共 8 小時。時針每小時走 360°÷12＝30°。","共轉 240°，換成弧度是 240÷180×π＝4π/3。"],
  "115-mb-17": ["共線向量要看方向和長度","取向右為正，設 AB＝1 個單位。AC 向右 1＋2＝3 單位，DC 向左 3 單位。","所以 AC＋DC 為零向量。BA 向左，BC 向右，兩者方向相反。"],
  "115-mb-18": ["內積＝對應分量乘積相加","設 A=(0,0)、B=(2,0)、D=(0,2)、C=(2,2)。E 是 CD 中點，所以 E=(1,2)。","AE=(1,2)，DB=(2,−2)，內積＝1×2＋2×(−2)＝−2。"],
  "115-mb-19": ["同主題相鄰，用捆綁法","將防火、防震、防空各當一大組，組的順序有 3!＝6 種。","每組內各自重排，總數為 3!×2!×2!×3!＝144。"],
  "115-mb-20": ["期望值＝金額乘機率再相加","3 枚公正硬幣有 8 種等可能結果。3 正面有 1 種，2 正面有 3 種，其餘 4 種。","平均＝3000×1/8＋1200×3/8＋600×4/8＝1125 元。"],
  "115-mb-21": ["直線垂直於平面，就垂直於過垂足的平面內直線","AE 是長方體的直立邊，垂直底面 EFGH。EG 在底面且經過 E，所以 AE 與 EG 垂直。","AB 和 AC 在同一面，分別是邊與對角線。AB 和 DH 不相交，為歪斜線。"],
  "115-mb-22": ["空間點到軸、到平面的距離","P 到 y 軸最近的點是 (0,−2,0)。差的兩個分量是 x＝3、z＝4，所以 a＝√(3²＋4²)＝5。","yz 平面上的點 x 都等於 0，b＝|3|＝3。總和是 8。"],
  "115-mb-23": ["聯立不等式找三角形面積","整理為 1−x≤y≤x＋1 與 x≤3。兩條斜線交於 (0,1)。","在 x＝3 時，上下交點為 (3,4)、(3,−2)。底長 6，頂點離直線 x＝3 有 3 單位，面積＝6×3÷2＝9。"],
  "115-mb-24": ["矩陣相乘可只算需要的那一欄","左矩陣乘右矩陣的第一欄 (p,r)，結果要是 (1,0)，所以 6p＋5r＝1、4p＋3r＝0。","由第二式得 r＝−4p/3，代入第一式得 −2p/3＝1，故 p＝−3/2。"],
  "115-mb-25": ["餘弦定理和三角形內角和","A 的對邊為 6、鄰邊是 3 和 4，cos A＝(3²＋4²−6²)/(2×3×4)＝−11/24。","B＋C＝180°−A，餘弦正負相反，所以 cos(B＋C)＝11/24。"],
  "115-mb-26": ["兩邊夾角求三角形面積","極坐標第一個數是距離，所以 OA＝4、OB＝3；方向差為 268°−118°＝150°。","面積＝(1/2)×4×3×sin 150°＝6×1/2＝3。"],
  "115-mb-27": ["正弦週期由 x 的係數決定","sin 的角度增加 2π 才繞完一圈。題目把 x 乘以 3，所以 x 只需加 2π/3。","外面的 2 改變高度，＋1 改變上下位置，角度內的 −π/3 改變起點，週期維持 2π/3。"],
  "115-mb-28": ["用垂直斜率與通過的點寫直線","12x＋5y＝0 的斜率是 −12/5，垂直的斜率是 5/12。代 x＝1 到 2x−y＝3 得 y＝−1。","過 (1,−1) 用點斜式 y＋1＝(5/12)(x−1)，整理得到 5x−12y＝17。"],
  "115-mb-29": ["放回抽取時，兩次機率相同","異色有先紅後藍與先藍後紅。紅球機率 2/5，藍球機率 3/5。","兩條路徑互斥，機率相加：(2/5)(3/5)＋(3/5)(2/5)＝12/25＝0.48。"],
  "115-mb-30": ["條件機率先縮小分母","點數和小於 7，依和 2、3、4、5、6 分別有 1、2、3、4、5 種有序結果，共 15 種。","至少一個 3 的是 (3,1)、(1,3)、(3,2)、(2,3)、(3,3)，所以是 5/15＝1/3。"],
  "115-mb-31": ["知道恰一人命中，分母只保留兩種情形","只有甲中是 0.6×0.5＝0.3，只有乙中是 0.4×0.5＝0.2。","已知恰一發命中，條件機率是 0.3/(0.3＋0.2)＝0.6。"],
  "115-mb-32": ["先固定總鳴叫次數，再排列長短","有 n 次鳴叫且 k 次是長音，總長是 n＋k＋(n−1) 秒，所以 k＝16−2n。","0≤k≤n 只允許 (n,k)=(6,4)、(7,2)、(8,0)。選長音位置共有 15＋21＋1＝37 種。"],
  "115-mb-33": ["餘式次數低於除式，且在 x＝1 等於 f(1)","除式 (x−1)² 是二次，所以餘式頂多一次。對稱中心 (1,3) 表示 f(1)＝3。","依序代入 x＝1，A、B、C、D 得 2、4、1、3。只有 3x 合條件。"],
  "115-mb-34": ["拋物線的等高兩點以對稱軸為中線","−3 和 5 對應相同函數值，所以對稱軸在 x＝(−3＋5)/2＝1。頂點在 y＝2x＋3 上，故為 (1,5)。","設 f(x)＝a(x−1)²＋5。代 x＝5 得 16a＋5＝−11，a＝−1。代 x＝0 得 4。"],
  "115-mb-35": ["比較向量長度可比較長度的平方","依序算得 A=(15,30)、B=(−24,12)、C=(30,10)、D=(−3,14)。","平方長度依序為 1125、720、1000、205；最大的是選項 A。"],
  "115-mb-36": ["垂直向量的長度可用畢氏定理","2u 和 v 也垂直。合成向量 (20,15) 的長度是 25，2u 的長度是 24。","|v|²＝25²−24²＝49，所以 |v|＝7。"],
  "115-mb-37": ["矩陣乘法要保留 AB 和 BA","(A＋B)²＝A²＋AB＋BA＋B²。題目給中間兩項等於 2AB，故 AB＝BA。","比較右上格：a−8＝−4−a，得 a＝2。比較左下格：6−b＝b＋12，得 b＝−3。和是 −1。"],
  "115-mb-38": ["等差對數對應原數的等比","設原數的公比為 r。從 162 到 1250 共乘四次，所以 r⁴＝1250/162＝625/81。","625＝5⁴、81＝3⁴，公比 r＝5/3。a＝162×5/3＝270。"],
  "115-mb-39": ["垂徑定理：圓心到弦的垂線通過弦中點","A 到對稱線 x＋y−10＝0 的距離是 |2＋4−10|/√2＝2√2，也就是半條弦長。","用半弦、圓心到弦的距離 4、半徑形成直角三角形，r＝√((2√2)²＋4²)＝2√6。"],
  "115-mb-40": ["分兩種同色結果，分別算剩下白球比例","甲乙皆白的機率是 (4/7)(3/6)＝12/42，皆黑是 (3/7)(2/6)＝6/42。已知同色後，權重分別是 2/3、1/3。","若皆白，餘 2 白 3 黑；若皆黑，餘 4 白 1 黑。剩餘五顆的抽取位置等可能，因此丁抽白為 (2/3)(2/5)＋(1/3)(4/5)＝8/15。"],
  "115-ch-1": ["字音比較","把兩字分開念。『絹』和『狷』都讀 ㄐㄩㄢˋ。","『鄲／憚』是 ㄉㄢ／ㄉㄢˋ，聲調不同。『楫／緝』是 ㄐㄧˊ／ㄑㄧˋ，『槊／溯』是 ㄕㄨㄛˋ／ㄙㄨˋ。"],
  "115-ch-2": ["同音字辨形","依意思把字寫回去。『阿諛』是奉承，『膏腴』指土地肥沃，『須臾』指很短的時間。","諛、腴、臾各不相同。B 後兩個用『闌』，C 有『靡』重複，D 前兩個都寫『梭』。"],
  "115-ch-3": ["一詞多義","先將『早晚』換成『遲早、終究』。成為天子、招致惡果，兩句都表示未來終將發生。","『大方之家』的大方指有學識的人。古詩中的『可憐』可指可愛，『故意』在詩中指老朋友的情意。"],
  "115-ch-4": ["常見錯別字","D 的『纏鬥、強勁、蟬聯』都符合意思。『蟬聯』指連續取得同一名次或頭銜。","A 應寫『一籌莫展』，B 應寫『匪夷所思』，C 應寫『詞不達意』。"],
  "115-ch-5": ["成語看情境","『虎尾春冰』把踩虎尾、踏薄冰並舉，形容處境危險。和後面的『稍一不慎』相扣。","『南轅北轍』表示方向相反，與默契十足不合。『玩歲愒日』指虛度光陰，和及時努力相反。"],
  "115-ch-6": ["詩句中的因果","『寺遠僧來少』可拆成因寺院離得遠，所以來的僧人少；『橋危客過稀』可拆成因橋危險，所以過橋的旅客少。","B 的兩個分句各自都有原因和結果，跟題幹的『草枯／鷹眼疾、雪盡／馬蹄輕』相同。"],
  "115-ch-7": ["律詩排序","先找開頭的時間線。『去年花裏逢君別』接『今日花開又一年』，起筆對照去年和今年。","接著由離別轉到世事與春愁，下一聯並列多病想歸田和百姓流亡之愧。末聯回到朋友將來探望，再以望月寫等待。"],
  "115-ch-8": ["教育類題辭","『桃李』比喻學生，『洙泗』聯想到孔子講學，『杏壇』指教育界，所以甲、丙、己都合用。","『杏林』指醫界，容易跟『杏壇』混淆。『千古』常作哀輓用語，用於退休祝賀不妥。"],
  "115-ch-9": ["文房四寶","找每聯的動作。甲『揮毫』用筆，丙『磨來濃霧』寫磨墨，乙『化石、窺池』指硯石和硯池。","丁『價重洛陽』連到洛陽紙貴。依筆、墨、紙、硯排列為甲丙丁乙。"],
  "115-ch-10": ["反詰與真問","反詰可以改寫成一句肯定或否定的陳述。例如『何患乎無兄弟』等於『不用擔心沒有兄弟』。","A 的『何日去』表達不知道何時能歸鄉，保留時間上的疑問。C 等於『真愉快』，D 等於『晉國沒有滿足的一天』。"],
  "115-ch-11": ["詩歌情境","『髭』是嘴邊的鬍鬚，『撚』是用手指搓捻。詩人寫自己思索詩句時常撚鬍鬚。","末句開玩笑說若一直撚斷，嘴邊就跟老和尚的頭一樣光。重點是寫詩苦思與習慣。"],
  "115-ch-12": ["詠史典故","『丹心、義氣』配合關羽忠義的形象，『春秋』也常用來連結關羽讀《春秋》的典故。","曹操頭疾和關羽手臂的典故指華佗。荔枝配楊貴妃。『明妃』指王昭君。"],
  "115-ch-13": ["功虧一簣","『簣』是一筐土。堆山到只差一筐時停下來，仍然沒有完成。","C 說挖井到很深還沒見水，放棄就仍是廢井。兩句都說做到最後一步才有效。"],
  "115-ch-14": ["抽象道理與例子","先讀主張『人人有不忍人之心』，再找具體情境。看到小孩快掉進井裡，會立刻驚懼同情。","這個例子用來說明人人有惻隱之心。A、B、C 的前後句主要順著事情或觀察經過發展。"],
  "115-ch-15": ["固定疊詞","完整詞形是小心翼翼、神采奕奕、鼎鼎大名、虎視眈眈、結實纍纍。","『奕奕』寫有精神，和下棋的『弈』不同。『纍纍』有連串多數的意思，用來描寫果實。"],
  "115-ch-16": ["比喻親恩","『昊天罔極』說浩大如天空、沒有邊際。『三春暉』以整個春天的陽光比喻母愛。","孩子如受陽光滋養的一寸小草，怎能回報全部恩情？兩句焦點都是父母恩澤之深。"],
  "115-ch-17": ["流水喻時間","『流波不相待』說流水不等人；『繁華及時紅』指出盛開有自己的時節。","兩句合讀有珍惜時光之意。B、C 的流水各自是景物的一部分，沒有這樣的勸勉。"],
  "115-ch-18": ["從景物辨季節","乙的楊柳新綠是春，甲的梅子與芭蕉是初夏，丙的霜楓是秋。","丁的荷葉枯盡、菊花殘而仍抗霜，寫秋末初冬。依序乙甲丙丁。"],
  "115-ch-19": ["中心風尚向外擴散","城裡喜歡高髻，外地梳得更高；城裡喜歡寬眉，外地幾乎畫半個額頭。","『風行草偃』是上行下效，『變本加厲』是模仿者程度更甚，恰好說出兩層。"],
  "115-ch-20": ["由物象判斷詠物","『堅硬的環節』提示竹節，『向天空步步高升』寫竹幹逐節向上長，『綠』是竹的色彩。","B 的攀附動作更接近藤蔓。C 的去舊迎新指節慶爆竹，題意重視可辨認的物象。"],
  "115-ch-21": ["先秦思想關鍵詞","性惡而以禮義改變，是荀子。桂木與漆樹因有用受損，反思無用之用，是莊子。","『兼相愛則治』講兼愛，是墨子的主張。因此是荀子、莊子、墨子。"],
  "115-ch-22": ["唐詩與宋詩風格","先依題幹找日常場景和口語敘事。C 寫高個子讀書，伸懶腰就撞到屋頂，帶有生活趣味。","A 用日暮、江月寫旅愁，B 借月落鳥啼等寫夢醒後的思緒，D 借寒雨送別寄情。"],
  "115-ch-23": ["偏義複詞","把左右兩字拆開看。『不宜異同』說賞罰標準不宜有分別，實際取『異』義。","『圓缺』真涵蓋月亮圓和缺，『冷暖』也涵蓋冷和暖，兩字都有用。"],
  "115-ch-24": ["層遞修辭","先找表示階段的時間詞：開始解牛、三年後、現在。","庖丁起初見整頭牛，三年後能看出結構，最後憑神會而毋須用眼。三步逐層提升；C 的三個做法則平行列舉。"],
  "115-ch-25": ["節慶意象","『登高、插茱萸』是農曆九月九日重陽節的線索。B 將它配為端午，符合題目要找的錯配。","除歲換桃符是春節，牛郎織女相會是七夕乞巧，夜間燈火與魚龍舞是元宵。"],
  "115-ch-26": ["古典小說特色","《老殘遊記》以老殘的所見所聞串連，沿途描寫官場與民間處境，帶出作者對國事與民生的看法。","《儒林外史》重在諷刺科舉與士林。《世說新語》所記以漢末至東晉士人為主，時代早於唐。"],
  "115-ch-27": ["閱讀定位與反向題","先注意問『並非』。第一段寫冰期縮短，意思是結冰的時間變少。","D 說湖泊水面永久凍結，方向相反。垂直遷徙、族群縮減、食物鏈重整都能在原文定位。"],
  "115-ch-28": ["文本敘述與推論","首段說颱風連連、規模愈大。選項 A 的『風災消失』與這條線索直接矛盾。","同一選項即使有對的部分，只要有一個關鍵錯誤，整項就不成立。"],
  "115-ch-29": ["人物前後變化","仲永五歲就能作詩，後來十二三歲已不如從前，七年後和一般人一樣。","『小時了了，大未必佳』就是小時候聰明，長大未必突出，符合故事的發展。"],
  "115-ch-30": ["由末段議論找主旨","『受之天』指天資，『受於人』指後天教育。末段說仲永很有天分，卻缺少後天學習而落入平常。","父親重利是故事原因之一，作者由此談的是後天教育對才能的影響。"],
  "115-en-1": ["grow＝生長","句意是強勁海風吹來，有些植物很難在這片海灘生長。主語 some plants 提示 grow。","blow 是風在吹，cure 是治療，cage 是把東西關進籠子。"],
  "115-en-2": ["confirm a reservation＝確認訂位","Lisa 打給航空公司，目的在確認 flight reservation（航班訂位）。","arrest 是逮捕，resist 是抵抗，commute 是通勤。遇到航空公司和訂位，記 confirm / change / cancel 三種常見搭配。"],
  "115-en-3": ["fierce＝猛烈的","後面說房屋被毀、居民必須撤離，空格要描述暴風雨的強度。fierce storm 是猛烈的暴風雨。","childish 幼稚的，classical 古典的，financial 財務的。"],
  "115-en-4": ["structure＝建築物、構造","前面說 Taipei 101 是高樓，後半句仍把它放在許多壯觀的建物中比較。","one of the most + 形容詞 + 複數名詞，表示『最……的其中之一』。structures 指這些建物。"],
  "115-en-5": ["abnormal＝不正常的","never happened in the past、extreme heat、excessive rain 都是異常天候的線索。","standard 是標準的，意思相反。flexible 是有彈性的，cognitive 是認知的。"],
  "115-en-6": ["worship＝敬拜","churches、temples、mosques 都是宗教活動場所，prayer 是祈禱。","gather to worship 是聚集來禮拜。preserve 保存，prohibit 禁止，exclude 排除。"],
  "115-en-7": ["travel agency＝旅行社","後文說提供機票和飯店套裝優惠，指辦理旅行的機構。","tutor 是家教，rumor 是謠言，legacy 是留下的遺產或影響。"],
  "115-en-8": ["concentration＝濃度","high concentration of sugar 指飲料內含糖濃度高，接著說每天喝不健康。","circulation 循環，congratulation 祝賀，calculation 計算。"],
  "115-en-9": ["strive for＝努力追求","下一句 work hard to pursue excellence 等於替前一句解釋。strive for perfection 是盡力追求完美。","ensure 是確保，通常直接接名詞。protest 是抗議，inspire 是激勵。"],
  "115-en-10": ["be respectful of＝尊重","inclusive environment 指包容的環境。面對彼此意見與文化背景，合理態度是尊重。","dominant 支配的，accurate 精確的，furious 暴怒的。"],
  "115-en-11": ["in spite of＝儘管","天氣糟糕，本來可能放棄，登山隊卻繼續往上。前後呈讓步。","in spite of 後面接名詞 the terrible weather。because of 是『因為』，would make 壞天氣成為繼續登山的原因，語意不合。"],
  "115-en-12": ["break the ice＝打破僵局","兩人起初幾乎不講話，合作之後關係變得自在。break the ice 就是消除初見的尷尬。","全句寫過去經過，所以用過去式 broke。make waves 指引起轟動，spring up 指突然出現。"],
  "115-en-13": ["draw on＝利用、借助","建置健康照護體系，需要運用不同醫院的 medical resources。draw on 後接資源、經驗或知識。","take up 可指開始從事或占用，put off 是延後，knock down 是推倒。"],
  "115-en-14": ["come to an agreement＝達成協議","談判好幾週後，雙方終於達成協議。an agreement 是固定搭配的線索。","turn down 是拒絕，give up 是放棄，tune out 是不再留意。"],
  "115-en-15": ["in place of＝取代","使用再生能源的目的是降低碳足跡，因此把傳統化石燃料替換掉。","on behalf of 代表，in charge of 負責，in light of 鑑於。"],
  "115-en-16": ["strike a balance between A and B＝在兩者間取得平衡","A 是建設基礎設施，B 是保護綠地。都市規劃需要兼顧。","keep in shape 是維持體態，get cold feet 是臨陣退縮，come to a standstill 是停擺。"],
  "115-en-17": ["get over＝克服","受訓之後，Mark 克服了害怕深池游泳的心理。get over a fear 是常見搭配。","get off 常指下車，call off 是取消，call out 可指點名或公開批評。"],
  "115-en-18": ["on top of that＝除此之外","第一句談身體和免疫，第二句再加入心理健康與減壓兩個好處。","On the contrary 表相反，Worst of all 加重壞處，That is to say 是換句話重述。"],
  "115-en-19": ["than 提示比較級","difficult 字較長，比較級是 more difficult。much 放在比較級前，把差距加強成『難得多』。","difficulty 是名詞，most difficult 是最高級。只寫 difficult 無法和 than 組成這個比較句型。"],
  "115-en-20": ["little 修飾不可數名詞","time 表示剩下的時間，這裡不可數。must finish quickly 說得趕快做完，所以剩的時間很少。","few、many 搭可數複數。much 可搭 time，卻是『很多』的意思。"],
  "115-en-21": ["過去分詞開頭表被動","誰把 Sandra 養大？是別人把她養大，所以她是被養育的一方。用 Raised in a small village。","可以展開理解為 Having been raised in a small village 或 Because she was raised there。"],
  "115-en-22": ["deny + V-ing＝否認做過某事","先看到 denied，後面講他否認在賽事中用藥。記 deny doing something。","直接接 taking；deny 和 decide to do 的接法不同。"],
  "115-en-23": ["whose 表示所有關係","innovative ideas 是那位商界人士的點子。用 whose innovative ideas 把名詞和所有者連起來。","who 和 whom 可以表示人，單獨放在 ideas 前面不能表達『其點子』。"],
  "115-en-24": ["混合假設句","when I was young 指過去，now 指現在。這句是假設過去若更努力，現在會有更好的工作機會。","過去和事實相反用 If + 主詞 + had + 過去分詞，現在的結果用 would + 原形動詞。"],
  "115-en-25": ["助動詞代替前文動詞","those 指其他孩子。前半句 who read regularly 是一般現在式，後半句 who don’t 省略 read regularly。","aren’t 和 weren’t 是 be 動詞，無法代替 read。haven’t 則需要前文是完成式或有相應語境。"],
  "115-en-26": ["since 在這裡＝因為","餐廳收到極正面的評論，因此很快受歡迎。前半句提供原因。","unless 除非，as though 彷彿，even though 儘管。這三項都不合此處的因果。"],
  "115-en-27": ["被動語態 be + 過去分詞","家事由家人分擔。housework 是不可數名詞，用單數 is，搭配過去分詞 shared。","were 和單數主語不搭；has been sharing、will share 會變成家事主動去分攤。"],
  "115-en-28": ["rather than＝而非、與其……不如……","主管會怪團隊成員而不肯道歉。對照 blame 和 offer，兩者都用原形。","instead 如果要接動作用 instead of offering；B 的 offered 也不能直接和 would blame 平行。"],
  "115-en-29": ["要求句型 insist that + 主詞 + 原形","句中 insists 表示『堅持要求』員工準時。that 後用原形 be。","這個用法和 insist 表示『堅稱某事是真的』不同。這題談要求，句型可理解為 should be。"],
  "115-en-30": ["逗號加 which 指前面整件事","班長投票反對提案，這一整件事讓所有人吃驚。用 which 接補充結果。","逗號後的補充關係子句用 which，不能用 that。and surprising 則缺少完整平行結構。"],
  "115-en-31": ["Not until 句首倒裝","直到簡報結束，講者才發現自己漏講重點。Not until 提到句首時，主要子句變成 did the speaker realize。","until 後的 the presentation ended 仍用正常語序。這題看到 did 在主詞前，就可辨認倒裝。"],
  "115-en-32": ["It is said that＝據說","It 是形式主詞，真正被人傳述的內容在 that 後面。句意是據說建築已存在五百多年。","There is 常用來表示某物存在，不能直接接 said that 作這個句型。"],
  "115-en-33": ["間接問句使用主詞＋動詞","the tourists asked the guide 後接間接問句。B 的 they should visit 使用正常語序，A 和 D 保留直接問句的倒裝。","原卷採 B。自己寫作時可用更自然的 where they should go，或 which places they should visit。"],
  "115-en-34": ["whoever＝任何……的人","空格所在的整段要充當 will receive 的主詞。Whoever discovers the cure 等於 Anyone who discovers the cure。","Anyone discovers 缺 who，No matter who 開頭通常帶讓步副詞子句，無法充當此處主詞。"],
  "115-en-35": ["文章主旨看開頭和結尾","首段說 Hamberg 對國家公園的創立與推廣很重要，末段說他的研究改變外界對 Sarek 的看法。","D 涵蓋首尾。冰河、國家公園制度及與其他科學家合作都是支撐主旨的細節。"],
  "115-en-36": ["篇章組織看年代","文章先寫 1895 年初到 Sarek，再寫持續研究、1909 年設公園，最後到 1996 年的世界遺產。","這種由早到晚呈現事件的組織叫 in order of time（時間順序）。"],
  "115-en-37": ["細節題回到第二段","第二段寫多數瑞典人認為山區危險可怕，Hamberg 卻看到很大的科學價值。C 說此前少有人知道其科學價值。","A 的 alone 和文中 joined forces 不合。B 說因礦藏而開發，文章沒有這條因果。"],
  "115-en-38": ["推論題抓先後關係","第二段開頭寫他 1895 年到 Sarek 之前，曾加入探索格陵蘭冰河的團隊。","因此可推知 B。文章說木屋是為觀測而建，並無普遍木屋、放逐族人或以觀光為研究目的的資訊。"],
  "115-en-39": ["intimidating＝令人畏懼的","第二段用 dangerous and frightening 描述當時大眾對山區的印象，末段在重提這個印象。","terrifying 也是令人害怕的。promising 有希望的，appealing 吸引人的，outgoing 外向的。"],
  "115-en-40": ["結尾段作用","最後一段把過去看成可怕荒野，與後來被認為美麗且獲列世界遺產的轉變連起來。","重點是總結 Hamberg 的貢獻，所以選 offering conclusive remarks（提出總結）。"]
};
